export default "      trace_id = trace_name\\n        vertex = component.get_vertex()\\n        if vertex:\\n            trace_id = vertex.id\\n        trace_type = component.trace_type\\n        inputs = self._cleanup_inputs(inputs)\\n        component_trace_context = ComponentTraceContext(trace_id, trace_name, trace_type, vertex, inputs, metadata)\\n        component_context_var.set(component_trace_context)\\n        trace_context = trace_context_var.get()\\n        if trace_context is None:\\n            msg = \\\"called trace_component but no trace context found\\\"\\n            logger.warning(msg)\\n            yield self\\n            return\\n        trace_context.all_inputs[trace_name] |= inputs or {}\\n        await trace_context.traces_queue.put((self._start_component_traces, (component_trace_context, trace_context)))\\n        try:\\n            yield self\\n        except Exception as e:\\n            await trace_context.traces_queue.put(\\n                (self._end_component_traces, (component_trace_context, trace_context, e))\\n            )\\n            raise\\n        else:\\n            await trace_context.traces_queue.put(\\n                (self._end_component_traces, (component_trace_context, trace_context, None))\\n            )\\n\\n    @property\\n    def project_name(self):\\n        if self.deactivated:\\n            return os.getenv(\\\"LANGCHAIN_PROJECT\\\", \\\"Langflow\\\")\\n        trace_context = trace_context_var.get()\\n        if trace_context is None:\\n            msg = \\\"called project_name but no trace context found\\\"\\n            logger.warning(msg)\\n            return None\\n        return trace_context.project_name\\n\\n    def add_log(self, trace_name: str, log: Log) -> None:\\n        \\\"\\\"\\\"Add a log to the current component trace context.\\\"\\\"\\\"\\n        if self.deactivated:\\n            return\\n        component_context = component_context_var.get()\\n        if component_context is None:\\n            logger.debug(\\\"called add_log but no component context found\\\")\\n            return\\n        component_context.logs[trace_name].append(log)\\n\\n    def set_outputs(\\n        self,\\n        trace_name: str,\\n        outputs: dict[str, Any],\\n        output_metadata: dict[str, Any] | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"Set the outputs for the current component trace context.\\\"\\\"\\\"\\n        if self.deactivated:\\n            return\\n        component_context = component_context_var.get()\\n        if component_context is None:\\n            logger.debug(\\\"called set_outputs but no component context found\\\")\\n            return\\n        component_context.outputs[trace_name] |= outputs or {}\\n        component_context.outputs_metadata[trace_name] |= output_metadata or {}\\n        trace_context = trace_context_var.get()\\n        if trace_context is None:\\n            msg = \\\"called set_outputs but no trace context found\\\"\\n            logger.warning(msg)\\n            return\\n        trace_context.all_outputs[trace_name] |= outputs or {}\\n\\n    def get_tracer(self, tracer_name: str) -> BaseTracer | None:\\n        # When tracing is deactivated there is no trace context by construction, so the warning\\n        # below is guaranteed noise: it fired once per component per run and accounted for the\\n        # majority of the log volume on a box with LANGFLOW_DEACTIVATE_TRACING=true. Every other\\n        # public method here already guards this way.\\n        if self.deactivated:\\n            return None\\n        trace_context = trace_context_var.get()\\n        if trace_context is None:\\n            msg = \\\"called get_tracer but no trace context found\\\"\\n            logger.warning(msg)\\n            return None\\n        return trace_context.tracers.get(tracer_name)\\n\\n    def get_langchain_callbacks(self) -> list[BaseCallbackHandler]:\\n        if self.deactivated:\\n            return []\\n        callbacks = []\\n        trace_context = trace_context_var.get()\\n        if trace_context is None:\\n            msg = \\\"called get_langchain_callbacks but no trace context found\\\"\\n            logger.warning(msg)\\n            return []\\n        for tracer in trace_context.tracers.values():\\n            if not tracer.ready:  # type: ignore[truthy-function]\\n                continue\\n            try:\\n                # A broken tracer (e.g. partial Langfuse creds) must never fail the run.\\n                langchain_callback = tracer.get_langchain_callback()\\n            except Exception as e:  # noqa: BLE001\\n                logger.warning(f\\\"Tracer {type(tracer).__name__} failed to provide a callback; skipping: {e}\\\")\\n                continue\\n            if langchain_callback:\\n                callbacks.append(langchain_callback)\\n        return callbacks\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/tracing/span_sorting.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ddfcbd90319885eeaa5ee9f27bab090f3e7fa568e362fe8cef90626d405e3105\",\"content\":\"\\\"\\\"\\\"Span pre-insertion utilities for the native tracer.\\n\\nProvides UUID resolution and topological sorting so that parent spans are\\nalways inserted before their children \u2014 a requirement for PostgreSQL's\\nimmediate foreign-key enforcement on ``span.parent_span_id \u2192 span.id``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\nfrom uuid import UUID, uuid5\\n\\nfrom lfx.log.logger import logger\\n\\n# Deterministic namespace for generating span UUIDs from non-UUID string IDs.\\nLANGFLOW_SPAN_NAMESPACE = UUID(\\\"a3e1c2d4-5b6f-7890-abcd-ef1234567890\\\")\\n\\n\\ndef resolve_span_uuids(\\n    completed_spans: list[dict[str, Any]],\\n    trace_id: UUID,\\n) -> list[tuple[dict[str, Any], UUID, UUID | None]]:\\n    \\\"\\\"\\\"Pre-compute DB UUIDs for each span and its parent.\\n\\n    Returns a list of (span_data, span_uuid, parent_uuid) tuples that can\\n    be topologically sorted before insertion.\\n\\n    Args:\\n        completed_spans: List of completed span dicts.\\n        trace_id: The trace UUID used as part of the deterministic namespace\\n            when generating UUIDs from non-UUID string IDs.\\n    \\\"\\\"\\\"\\n    resolved: list[tuple[dict[str, Any], UUID, UUID | None]] = []\\n    for span_data in completed_spans:\\n        try:\\n            span_uuid = UUID(span_data[\\\"id\\\"])\\n        except (ValueError, TypeError):\\n            span_uuid = uuid5(LANGFLOW_SPAN_NAMESPACE, f\\\"{trace_id}-{span_data['id']}\\\")\\n\\n        parent_uuid: UUID | None = None\\n        if span_data.get(\\\"parent_span_id\\\"):\\n            parent_id = span_data[\\\"parent_span_id\\\"]\\n            if isinstance(parent_id, UUID):\\n                parent_uuid = parent_id\\n            else:\\n                try:\\n                    parent_uuid = UUID(str(parent_id))\\n                except (ValueError, TypeError):\\n                    parent_uuid = uuid5(LANGFLOW_SPAN_NAMESPACE, f\\\"{trace_id}-{parent_id}\\\")\\n\\n        resolved.append((span_data, span_uuid, parent_uuid))\\n    return resolved\\n\\n\\ndef topological_sort_spans(\\n    resolved: list[tuple[dict[str, Any], UUID, UUID | None]],\\n) -> list[tuple[dict[str, Any], UUID, UUID | None]]:\\n    \\\"\\\"\\\"Sort spans so parents appear before children.\\n\\n    PostgreSQL enforces foreign-key constraints at INSERT time, so a child\\n    span referencing ``parent_span_id`` will fail if the parent row hasn't\\n    been written yet.  This performs a Kahn's-algorithm-style topological\\n    sort over the batch so that every parent is inserted first.\\n\\n    Spans whose ``parent_span_id`` points outside the current batch are\\n    detached from that missing parent. Native tracing persists a trace's\\n    spans in a single batch, so retaining the reference would violate the\\n    immediate foreign-key constraint.\\n    \\\"\\\"\\\"\\n    batch_ids = {span_uuid for _, span_uuid, _ in resolved}\\n\\n    normalized: list[tuple[dict[str, Any], UUID, UUID | None]] = []\\n    missing_parent_count = 0\\n    for span_data, span_uuid, parent_uuid in resolved:\\n        normalized_parent_uuid = parent_uuid\\n        if normalized_parent_uuid is not None and normalized_parent_uuid not in batch_ids:\\n            normalized_parent_uuid = None\\n            missing_parent_count += 1\\n        normalized.append((span_data, span_uuid, normalized_parent_uuid))\\n\\n    if missing_parent_count:\\n        logger.warning(\\n            \\\"Detached %d tracing spans from missing parents to preserve database integrity.\\\",\\n            missing_parent_count,\\n        )\\n\\n    sorted_spans: list[tuple[dict[str, Any], UUID, UUID | None]] = []\\n    inserted: set[UUID] = set()\\n    remaining = normalized\\n\\n    while remaining:\\n        next_round: list[tuple[dict[str, Any], UUID, UUID | None]] = []\\n        progress = False\\n        for item in remaining:\\n            _, span_uuid, parent_uuid = item\\n            if parent_uuid is None or parent_uuid in inserted:\\n                sorted_spans.append(item)\\n                inserted.add(span_uuid)\\n                progress = True\\n            else:\\n                next_round.append(item)\\n\\n        if not progress:\\n            # Cycle or unresolvable dependency detected.\\n            # To avoid reintroducing foreign-key violations, break the cycle by\\n            # nulling out parent_span_id for the remaining spans before inserting.\\n            if next_round:\\n                logger.warning(\\n                    \\\"Detected cycle or unresolvable span dependencies in tracing batch; \\\"\\n                    \\\"breaking parent relationships for %d spans to preserve DB integrity.\\\",\\n                    len(next_round),\\n                )\\n            for span_data, span_uuid, _parent_uuid in next_round:\\n                # Append with a nulled parent \u2014 do NOT mutate the original span_data\\n                # dict because callers may still reference it after the sort.\\n                sorted_spans.append((span_data, span_uuid, None))\\n            break\\n        remaining = next_round\\n\\n    return sorted_spans\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/tracing/traceloop.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7e2319837371a473a9e60f5803cc77a4aaf8109547737c3cc07e6fa0c7d36fb6\",\"content\":\"from __future__ import annotations\\n\\nimport json\\nimport math\\nimport os\\nimport threading\\nimport types\\nfrom contextlib import contextmanager\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING, Any\\nfrom urllib.parse import urlparse\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import APPLICATION_INSTRUMENTATION_SCOPES\\nfrom opentelemetry import trace\\nfrom opentelemetry.sdk.trace import SpanProcessor\\nfrom opentelemetry.trace import Span, use_span\\nfrom opentelemetry.trace.propagation.tracecontext import TraceContextTextMapPropagator\\nfrom traceloop.sdk import Traceloop\\nfrom traceloop.sdk.instruments import Instruments\\nfrom typing_extensions import override\\n\\nfrom langflow.services.tracing.base import BaseTracer\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Iterator, Sequence\\n    from uuid import UUID\\n\\n    from langchain_core.callbacks.base import BaseCallbackHandler\\n    from opentelemetry.propagators.textmap import CarrierT\\n    from opentelemetry.trace import Span\\n\\n    from langflow.graph.vertex.base import Vertex\\n    from langflow.services.tracing.schema import Log\\n\\n\\n# ---------------------------------------------------------------------------------------------\\n# Keeping the service's own telemetry out of Traceloop's exporter.\\n#\\n# The SDK takes no tracer provider. It adopts whichever provider is global and attaches its\\n# exporter to that, so its exporter sees every span on that provider -- including the service's\\n# own HTTP and flow spans. ``instrument_fastapi_app`` runs unconditionally at startup, so those\\n# HTTP spans exist in every install, whether or not an APM is configured. Without a filter they\\n# are shipped to the vendor along with the LLM traces the operator actually asked for.\\n# ---------------------------------------------------------------------------------------------\\n\\n# Traceloop.init is not reentrant (TracerWrapper is a singleton built in __new__) and the hook\\n# below is on a module attribute, so concurrent flow runs are serialised through this.\\n_INIT_LOCK = threading.Lock()\\n\\n# Set once the filter has been observed to install. Only the init that actually builds the\\n# SDK's pipeline runs the factory; later ones are no-ops and must not be read as a failure.\\n_boundary_installed = False\\n\\n\\nclass _ApplicationScopeFilter(SpanProcessor):\\n    \\\"\\\"\\\"Delegates to a Traceloop processor, minus the spans that belong to the operator's APM.\\n\\n    Everything the application allowlist does not claim is passed through, so the vendor keeps\\n    its own LLM spans and anything else it instruments. The default falls towards the vendor\\n    deliberately: the allowlist is the set we know the APM exports, and dropping only that is\\n    what makes this safe to wrap around a pipeline whose contents we do not control.\\n\\n    Note that ``APPLICATION_INSTRUMENTATION_SCOPES`` is therefore load-bearing in two\\n    directions. Adding a scope to it enriches the APM *and* removes that scope from every\\n    Traceloop trace.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, wrapped: SpanProcessor) -> None:\\n        self._wrapped = wrapped\\n        self._dropped_scopes: set[str] = set()\\n\\n    @override\\n    def on_start(self, span, parent_context=None) -> None:\\n        self._wrapped.on_start(span, parent_context)\\n\\n    @override\\n    def on_end(self, span) -> None:\\n        scope = span.instrumentation_scope.name if span.instrumentation_scope else \\\"\\\"\\n        if scope not in APPLICATION_INSTRUMENTATION_SCOPES:\\n            self._wrapped.on_end(span)\\n            return\\n        if scope not in self._dropped_scopes:\\n            self._dropped_scopes.add(scope)\\n            logger.debug(f\\\"Not sending {scope!r} spans to Traceloop; that is application telemetry.\\\")\\n\\n    @override\\n    def shutdown(self) -> None:\\n        self._wrapped.shutdown()\\n\\n    @override\\n    def force_flush(self, timeout_millis: int = 30000) -> bool:\\n        return self._wrapped.force_flush(timeout_millis)\\n\\n\\n@contextmanager\\ndef _application_telemetry_withheld() -> Iterator[None]:\\n    \\\"\\\"\\\"Wrap the SDK's span processor factory for the duration of ``Traceloop.init``.\\n\\n    The factory is the hook because it is the one place every export path goes through. The\\n    provider is not: patching ``add_span_processor`` only covers the case where a provider\\n    already exists, and misses the far more common one where no APM is configured, the global\\n    provider is still a proxy, and the SDK creates and registers its own concrete provider that\\n    the proxy then resolves onto. The provider is also shared, so a processor another\\n    integration registered during ``init`` would be wrapped and have this boundary applied\\n    backwards.\\n\\n    Passing ``processor=`` to ``init`` is the other obvious hook and is worse: it turns off the\\n    SDK's metrics, drops the ``TRACELOOP_HEADERS`` auth the Instana integration depends on,\\n    makes ``disable_batch`` inert and skips prompt sync. Wrapping the factory leaves all of that\\n    alone, because from ``init``'s point of view no processor was supplied.\\n\\n    Fails closed. ``traceloop-sdk`` is depended on across a wide range, and if a release stops\\n    routing through this factory the filter stops applying with no other symptom. A silent leak\\n    is the one failure mode an export boundary must not have, so an init that builds the SDK's\\n    pipeline without installing the filter raises instead of exporting unfiltered.\\n\\n    Serialised because flows run concurrently and the hook is on a module attribute: two tracers\\n    initialising at once would otherwise have the first one's restore run while the second is\\n    still inside init, leaving that run's processor unwrapped.\\n    \\\"\\\"\\\"\\n    global _boundary_installed  # noqa: PLW0603\\n    from traceloop.sdk.tracing import tracing as traceloop_tracing\\n\\n    with _INIT_LOCK:\\n        original = traceloop_tracing.get_default_span_processor\\n        installed: list[_ApplicationScopeFilter] = []\\n\\n        def get_default_span_processor(*args, **kwargs) -> SpanProcessor:\\n            span_processor = _ApplicationScopeFilter(original(*args, **kwargs))\\n            installed.append(span_processor)\\n            return span_processor\\n\\n        traceloop_tracing.get_default_span_processor = get_default_span_processor\\n        try:\\n            yield\\n        finally:\\n            traceloop_tracing.get_default_span_processor = original\\n\\n        if installed:\\n            _boundary_installed = True\\n        elif not _boundary_installed:\\n            msg = (\\n                \\\"Traceloop was initialised without the filter that keeps Langflow's own \\\"\\n                \\\"telemetry out of its exporter, so the integration has been disabled rather \\\"\\n                \\\"than shipping the service's HTTP and flow spans to the vendor. This means the \\\"\\n                \\\"installed traceloop-sdk no longer builds its exporter through \\\"\\n                \\\"get_default_span_processor; pin traceloop-sdk to a version that does.\\\"\\n            )\\n            logger.error(msg)\\n            raise RuntimeError(msg)\\n\\n\\nclass TraceloopTracer(BaseTracer):\\n    \\\"\\\"\\\"Traceloop tracer for Langflow.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        trace_name: str,\\n        trace_type: str,\\n        project_name: str,\\n        trace_id: UUID,\\n        user_id: str | None = None,\\n        session_id: str | None = None,\\n    ):\\n        self.trace_id = trace_id\\n        self.trace_name = trace_name\\n        self.trace_type = trace_type\\n        self.project_name = project_name\\n        self.user_id = user_id\\n        self.session_id = session_id\\n        self.child_spans: dict[str, Span] = {}\\n\\n        if not self._validate_configuration():\\n            self._ready = False\\n            return\\n\\n        api_key = os.getenv(\\\"TRACELOOP_API_KEY\\\", \\\"\\\").strip()\\n        api_endpoint = os.getenv(\\\"TRACELOOP_BASE_URL\\\", \\\"https://api.traceloop.com\\\")\\n        try:\\n            with _application_telemetry_withheld():\\n                Traceloop.init(\\n                    block_instruments={Instruments.PYMYSQL},\\n                    app_name=project_name,\\n                    disable_batch=True,\\n                    api_key=api_key,\\n                    api_endpoint=api_endpoint,\\n                )\\n            self._ready = True\\n            self._tracer = trace.get_tracer(\\\"langflow\\\")\\n            self.propagator = TraceContextTextMapPropagator()\\n            self.carrier: CarrierT = {}\\n\\n            self.root_span = self._tracer.start_span(\\n                name=trace_name,\\n                start_time=self._get_current_timestamp(),\\n            )\\n\\n            with use_span(self.root_span, end_on_exit=False):\\n                self.propagator.inject(carrier=self.carrier)\\n\\n        except Exception:  # noqa: BLE001\\n            logger.debug(\\\"Error setting up Traceloop tracer\\\", exc_info=True)\\n            self._ready = False\\n\\n    @property\\n    def ready(self) -> bool:\\n        return self._ready\\n\\n    def _validate_configuration(self) -> bool:\\n        api_key = os.getenv(\\\"TRACELOOP_API_KEY\\\", \\\"\\\").strip()\\n        if not api_key:\\n            return False\\n\\n        base_url = os.getenv(\\\"TRACELOOP_BASE_URL\\\", \\\"https://api.traceloop.com\\\")\\n        parsed = urlparse(base_url)\\n        if not parsed.netloc:\\n            logger.error(f\\\"Invalid TRACELOOP_BASE_URL: {base_url}\\\")\\n            return False\\n\\n        return True\\n\\n    def _convert_to_traceloop_type(self, value):\\n        \\\"\\\"\\\"Recursively converts a value to a Traceloop compatible type.\\\"\\\"\\\"\\n        from langchain_core.documents import Document\\n        from langchain_core.messages import BaseMessage, HumanMessage, SystemMessage\\n\\n        from langflow.schema.message import Message\\n\\n        try:\\n            if isinstance(value, dict):\\n                value = {key: self._convert_to_traceloop_type(val) for key, val in value.items()}\\n\\n            elif isinstance(value, list):\\n                value = [self._convert_to_traceloop_type(v) for v in value]\\n\\n            elif isinstance(value, Message):\\n                value = value.text\\n\\n            elif isinstance(value, (BaseMessage | HumanMessage | SystemMessage)):\\n                value = str(value.content) if value.content is not None else \\\"\\\"\\n\\n            elif isinstance(value, Document):\\n                value = value.page_content\\n\\n            elif isinstance(value, (types.GeneratorType | types.NoneType)):\\n                value = str(value)\\n\\n            elif isinstance(value, float) and not math.isfinite(value):\\n                value = \\\"NaN\\\"\\n\\n        except (TypeError, ValueError) as e:\\n            logger.warning(f\\\"Failed to convert value {value!r} to traceloop type: {e}\\\")\\n            return str(value)\\n        else:\\n            return value\\n\\n    def _convert_to_traceloop_dict(self, io_dict: Any) -> dict[str, Any]:\\n        \\\"\\\"\\\"Ensure values are OTel-compatible. Dicts stay dicts, lists get JSON-serialized.\\\"\\\"\\\"\\n        if isinstance(io_dict, dict):\\n            return {str(k): self._convert_to_traceloop_type(v) for k, v in io_dict.items()}\\n        if isinstance(io_dict, list):\\n            return {\\\"list\\\": json.dumps([self._convert_to_traceloop_type(v) for v in io_dict], default=str)}\\n\\n        return {\\\"value\\\": self._convert_to_traceloop_type(io_dict)}\\n\\n    @override\\n    def add_trace(\\n        self,\\n        trace_id: str,\\n        trace_name: str,\\n        trace_type: str,\\n        inputs: dict[str, Any],\\n        metadata: dict[str, Any] | None = None,\\n        vertex: Vertex | None = None,\\n    ) -> None:\\n        if not self.ready:\\n            return\\n\\n        span_context = self.propagator.extract(carrier=self.carrier)\\n        child_span = self._tracer.start_span(\\n            name=trace_name,\\n            context=span_context,\\n            start_time=self._get_current_timestamp(),\\n        )\\n\\n        attributes = {\\n            \\\"trace_id\\\": trace_id,\\n            \\\"trace_name\\\": trace_name,\\n            \\\"trace_type\\\": trace_type,\\n            \\\"inputs\\\": json.dumps(self._convert_to_traceloop_dict(inputs), default=str),\\n            **self._convert_to_traceloop_dict(metadata or {}),\\n        }\\n        if vertex and vertex.id is not None:\\n            attributes[\\\"vertex_id\\\"] = vertex.id\\n\\n        child_span.set_attributes(attributes)\\n\\n        self.child_spans[trace_id] = child_span\\n\\n    @override\\n    def end_trace(\\n        self,\\n        trace_id: str,\\n        trace_name: str,\\n        outputs: dict[str, Any] | None = None,\\n        error: Exception | None = None,\\n        logs: Sequence[Log | dict] = (),\\n    ) -> None:\\n        if not self._ready or trace_id not in self.child_spans:\\n            return\\n\\n        child_span = self.child_spans.pop(trace_id)\\n\\n        if outputs:\\n            child_span.set_attribute(\\\"outputs\\\", json.dumps(self._convert_to_traceloop_dict(outputs), default=str))\\n        if logs:\\n            child_span.set_attribute(\\\"logs\\\", json.dumps(self._convert_to_traceloop_dict(list(logs)), default=str))\\n        if error:\\n            child_span.record_exception(error)\\n\\n        child_span.end()\\n\\n    @override\\n    def end(\\n        self,\\n        inputs: dict[str, Any],\\n        outputs: dict[str, Any],\\n        error: Exception | None = None,\\n        metadata: dict[str, Any] | None = None,\\n    ) -> None:\\n        if not self.ready:\\n            return\\n\\n        safe_outputs = self._convert_to_traceloop_dict(outputs)\\n        safe_metadata = self._convert_to_traceloop_dict(metadata or {})\\n\\n        self.root_span.set_attributes(\\n            {\\n                \\\"workflow_name\\\": self.trace_name,\\n                \\\"workflow_id\\\": str(self.trace_id),\\n                \\\"outputs\\\": json.dumps(safe_outputs, default=str),\\n                **safe_metadata,\\n            }\\n        )\\n        if error:\\n            self.root_span.record_exception(error)\\n\\n        self.root_span.end()\\n\\n    @staticmethod\\n    def _get_current_timestamp() -> int:\\n        return int(datetime.now(timezone.utc).timestamp() * 1_000_000_000)\\n\\n    @override\\n    def get_langchain_callback(self) -> BaseCallbackHandler | None:\\n        return None\\n\\n    def close(self):\\n        try:\\n            provider = trace.get_tracer_provider()\\n            if hasattr(provider, \\\"force_flush\\\"):\\n                provider.force_flush(timeout_millis=3000)\\n        except (ValueError, RuntimeError, OSError) as e:\\n            logger.warning(f\\\"Error flushing spans: {e}\\\")\\n\\n    def __del__(self):\\n        self.close()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/tracing/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1e9b2e857b465947f6fe92bbfd5f168b3b393fd7a90ce0b12f7bf3d9558bf153\",\"content\":\"from typing import Any\\n\\nfrom lfx.schema.data import Data\\n\\n\\ndef convert_to_langchain_type(value):\\n    from langflow.schema.message import Message\\n\\n    if isinstance(value, dict):\\n        value = {key: convert_to_langchain_type(val) for key, val in value.items()}\\n    elif isinstance(value, list):\\n        value = [convert_to_langchain_type(v) for v in value]\\n    elif isinstance(value, Message):\\n        if \\\"prompt\\\" in value:\\n            value = value.load_lc_prompt()\\n        elif value.sender:\\n            value = value.to_lc_message()\\n        else:\\n            value = value.to_lc_document()\\n    elif isinstance(value, Data):\\n        value = value.to_lc_document() if \\\"text\\\" in value.data else value.data\\n    return value\\n\\n\\ndef convert_to_langchain_types(io_dict: dict[str, Any]):\\n    converted = {}\\n    for key, value in io_dict.items():\\n        converted[key] = convert_to_langchain_type(value)\\n    return converted\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/tracing/validation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f3cd5e075d62d7cc6397a79b1b74ea1b3d57665907ac69f2247d75da815244de\",\"content\":\"\\\"\\\"\\\"Input validation helpers for trace query parameters.\\n\\nValidates and sanitizes user-supplied inputs at the API boundary before\\nthey are passed to the repository layer.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\n\\ndef sanitize_query_string(value: str | None, max_len: int = 50) -> str | None:\\n    \\\"\\\"\\\"Sanitize a user-supplied query string for safe use in database queries.\\n\\n    Strips non-printable characters and truncates to ``max_len`` characters.\\n    Rejects by default: only printable ASCII (0x20-0x7E) is accepted.\\n\\n    Args:\\n        value: Raw query string from the request.\\n        max_len: Maximum allowed length after stripping.\\n\\n    Returns:\\n        Sanitized string, or ``None`` if the input was ``None`` or empty.\\n    \\\"\\\"\\\"\\n    if value is None:\\n        return None\\n    cleaned = \\\"\\\".join(ch for ch in value if \\\" \\\" <= ch <= \\\"~\\\").strip()\\n    return cleaned[:max_len] if cleaned else None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/transaction/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"59252102916cffb9fc86f61e8ee2feb81f4b4c111184ea18fa73aa9af958d624\",\"content\":\"\\\"\\\"\\\"Transaction service module for langflow.\\\"\\\"\\\"\\n\\nfrom langflow.services.transaction.factory import TransactionServiceFactory\\nfrom langflow.services.transaction.service import TransactionService\\n\\n__all__ = [\\\"TransactionService\\\", \\\"TransactionServiceFactory\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/transaction/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"707b160890b4784b62e639ef0ffc75db6dcbd581dd95b56ee950aa06fe7e4038\",\"content\":\"\\\"\\\"\\\"Transaction service factory for langflow.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom langflow.services.factory import ServiceFactory\\nfrom langflow.services.transaction.service import TransactionService\\n\\nif TYPE_CHECKING:\\n    from langflow.services.settings.service import SettingsService\\n\\n\\nclass TransactionServiceFactory(ServiceFactory):\\n    \\\"\\\"\\\"Factory for creating TransactionService instances.\\\"\\\"\\\"\\n\\n    def __init__(self):\\n        super().__init__(TransactionService)\\n\\n    def create(self, settings_service: SettingsService):\\n        \\\"\\\"\\\"Create a new TransactionService instance.\\n\\n        Args:\\n            settings_service: The settings service for checking if transactions are enabled.\\n\\n        Returns:\\n            A new TransactionService instance.\\n        \\\"\\\"\\\"\\n        return TransactionService(settings_service)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/transaction/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"89dfab167cfbbf6d39e7ada988809e55ff6da40e240216535e1eb7432fa87333\",\"content\":\"\\\"\\\"\\\"Transaction service implementation for langflow.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\nfrom uuid import UUID\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.deps import session_scope\\nfrom lfx.services.interfaces import TransactionServiceProtocol\\n\\nfrom langflow.services.base import Service\\nfrom langflow.services.database.models.transactions.crud import log_transaction as crud_log_transaction\\nfrom langflow.services.database.models.transactions.model import TransactionBase, TransactionTable\\n\\nif TYPE_CHECKING:\\n    from langflow.services.settings.service import SettingsService\\n\\n\\nclass TransactionService(Service, TransactionServiceProtocol):\\n    \\\"\\\"\\\"Concrete implementation of transaction logging service.\\n\\n    This service handles logging of component execution transactions to the database,\\n    tracking inputs, outputs, and status of each vertex build.\\n    \\\"\\\"\\\"\\n\\n    name = \\\"transaction_service\\\"\\n\\n    def __init__(self, settings_service: SettingsService):\\n        \\\"\\\"\\\"Initialize the transaction service.\\n\\n        Args:\\n            settings_service: The settings service for checking if transactions are enabled.\\n        \\\"\\\"\\\"\\n        self.settings_service = settings_service\\n        # Latch so the \\\"writer enabled but not running, using legacy path\\\" log\\n        # fires once per process instead of spamming on every transaction.\\n        self._legacy_fallback_logged: bool = False\\n\\n    async def log_transaction(\\n        self,\\n        flow_id: str,\\n        vertex_id: str,\\n        inputs: dict[str, Any] | None,\\n        outputs: dict[str, Any] | None,\\n        status: str,\\n        target_id: str | None = None,\\n        error: str | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"Log a transaction record for a vertex execution.\\n\\n        Args:\\n            flow_id: The flow ID (as string)\\n            vertex_id: The vertex/component ID\\n            inputs: Input parameters for the component\\n            outputs: Output results from the component\\n            status: Execution status (success/error)\\n            target_id: Optional target vertex ID\\n            error: Optional error message\\n        \\\"\\\"\\\"\\n        if not self.is_enabled():\\n            return\\n\\n        try:\\n            flow_uuid = UUID(flow_id) if isinstance(flow_id, str) else flow_id\\n\\n            transaction = TransactionBase(\\n                vertex_id=vertex_id,\\n                target_id=target_id,\\n                inputs=inputs,\\n                outputs=outputs,\\n                status=status,\\n                error=error,\\n                flow_id=flow_uuid,\\n            )\\n\\n            # When the telemetry writer is enabled and started, hand the row off\\n            # to its disk-backed outbox and return immediately \u2014 no DB connection\\n            # is acquired from the request pool. Falls through to the legacy\\n            # direct-write path when the writer isn't ready (e.g. very early in\\n            # lifespan) or has been disabled.\\n            if getattr(self.settings_service.settings, \\\"telemetry_writer_enabled\\\", False):\\n                from langflow.services.deps import get_telemetry_writer_service\\n\\n                writer = get_telemetry_writer_service()\\n                if writer is not None and writer.is_running():\\n                    table = TransactionTable(**transaction.model_dump())\\n                    if writer.enqueue_transaction(table.model_dump(mode=\\\"python\\\")):\\n                        return\\n                elif not self._legacy_fallback_logged:\\n                    self._legacy_fallback_logged = True\\n                    logger.warning(\\n                        \\\"telemetry_writer_enabled=True but writer is not running; \\\"\\n                        \\\"falling back to legacy direct-write path for transactions\\\"\\n                    )\\n\\n            async with session_scope() as session:\\n                await crud_log_transaction(session, transaction)\\n\\n        except Exception as exc:  # noqa: BLE001\\n            logger.debug(f\\\"Error logging transaction: {exc!s}\\\")\\n\\n    def is_enabled(self) -> bool:\\n        \\\"\\\"\\\"Check if transaction logging is enabled.\\n\\n        Returns:\\n            True if transaction logging is enabled, False otherwise.\\n        \\\"\\\"\\\"\\n        return getattr(self.settings_service.settings, \\\"transactions_storage_enabled\\\", False)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eb31b78dae18eb1490496267238e1697da550621ebac91f15c2cc5eca198f448\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nfrom enum import Enum\\nfrom importlib import import_module\\nfrom pathlib import Path\\nfrom secrets import token_urlsafe\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.settings.constants import (\\n    DEFAULT_SUPERUSER,\\n    LEGACY_DEFAULT_SUPERUSER_PASSWORD,\\n)\\nfrom lfx.services.settings.feature_flags import FEATURE_FLAGS\\nfrom sqlalchemy import delete\\nfrom sqlalchemy import exc as sqlalchemy_exc\\nfrom sqlmodel import col, select\\n\\nfrom langflow.services.cache.base import ExternalAsyncBaseCacheService\\nfrom langflow.services.cache.factory import CacheServiceFactory\\nfrom langflow.services.database.models.transactions.model import TransactionTable\\nfrom langflow.services.database.models.vertex_builds.model import VertexBuildTable\\nfrom langflow.services.database.utils import initialize_database\\nfrom langflow.services.schema import ServiceType\\n\\nfrom .deps import get_auth_service, get_db_service, get_service, get_settings_service, session_scope\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.manager import SettingsService\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\nclass SetupSuperuserResult(str, Enum):\\n    \\\"\\\"\\\"Distinct outcomes from ``setup_superuser`` (AUTO_LOGIN and credential paths).\\\"\\\"\\\"\\n\\n    AUTO_LOGIN_INITIALIZED = \\\"auto_login_initialized\\\"\\n    AUTO_LOGIN_ALREADY_SATISFIED = \\\"auto_login_already_satisfied\\\"\\n    AUTO_LOGIN_LOCK_TIMEOUT_SUPERUSER_PRESENT = \\\"auto_login_lock_timeout_superuser_present\\\"\\n    SUPERUSER_CREATED = \\\"superuser_created\\\"\\n    SUPERUSER_UNCHANGED = \\\"superuser_unchanged\\\"\\n\\n\\ndef _secret_value(secret) -> str:\\n    if not secret:\\n        return \\\"\\\"\\n    if hasattr(secret, \\\"get_secret_value\\\"):\\n        return secret.get_secret_value()\\n    return str(secret)\\n\\n\\ndef get_auto_login_superuser_password(auth_settings) -> str:\\n    configured_password = _secret_value(auth_settings.SUPERUSER_PASSWORD)\\n    legacy_password = LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value()\\n    if configured_password and configured_password != legacy_password:\\n        return configured_password\\n    return token_urlsafe(32)\\n\\n\\nasync def _get_superuser_by_username(session: AsyncSession, username: str):\\n    from langflow.services.database.models.user.model import User\\n\\n    stmt = select(User).where(\\n        User.username == username,\\n        User.is_superuser == True,  # noqa: E712\\n    )\\n    result = await session.exec(stmt)\\n    return result.first()\\n\\n\\nasync def _rotate_legacy_default_superuser_password(session: AsyncSession, user, replacement_password: str) -> bool:\\n    legacy_password = LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value()\\n    if not legacy_password or not user.password:\\n        return False\\n\\n    auth = get_auth_service()\\n    if not auth.verify_password(legacy_password, user.password):\\n        return False\\n\\n    user.password = auth.get_password_hash(replacement_password)\\n    session.add(user)\\n    await session.commit()\\n    await session.refresh(user)\\n    await logger.awarning(\\\"Rotated legacy default superuser password.\\\")\\n    return True\\n\\n\\nasync def get_or_create_super_user(\\n    session: AsyncSession,\\n    username,\\n    password,\\n    is_default,\\n    *,\\n    rotate_legacy_default_password: bool = False,\\n):\\n    from langflow.services.database.models.user.model import User\\n\\n    stmt = select(User).where(User.username == username)\\n    result = await session.exec(stmt)\\n    user = result.first()\\n\\n    auth = get_auth_service()\\n    if user and user.is_superuser:\\n        if rotate_legacy_default_password:\\n            await _rotate_legacy_default_superuser_password(session, user, password)\\n        return None  # Superuser already exists\\n\\n    if user and is_default:\\n        if user.is_superuser:\\n            if auth.verify_password(password, user.password):\\n                return None\\n            # Superuser exists but password is incorrect\\n            # which means that the user has changed the\\n            # base superuser credentials.\\n            # This means that the user has already created\\n            # a superuser and changed the password in the UI\\n            # so we don't need to do anything.\\n            await logger.adebug(\\n                \\\"Superuser exists but password is incorrect. \\\"\\n                \\\"This means that the user has changed the \\\"\\n                \\\"base superuser credentials.\\\"\\n            )\\n            return None\\n        logger.debug(\\\"User with superuser credentials exists but is not a superuser.\\\")\\n        return None\\n\\n    if user:\\n        if auth.verify_password(password, user.password):\\n            msg = \\\"User with superuser credentials exists but is not a superuser.\\\"\\n            raise ValueError(msg)\\n        msg = \\\"Incorrect superuser credentials\\\"\\n        raise ValueError(msg)\\n\\n    if is_default:\\n        logger.debug(\\\"Creating default superuser.\\\")\\n    else:\\n        logger.debug(\\\"Creating superuser.\\\")\\n    return await auth.create_super_user(username, password, db=session)\\n\\n\\nasync def setup_superuser(settings_service: SettingsService, session: AsyncSession) -> SetupSuperuserResult:\\n    if settings_service.auth_settings.AUTO_LOGIN:\\n        await logger.adebug(\\\"AUTO_LOGIN is set to True. Creating default superuser with full initialization.\\\")\\n        # Use file lock to prevent race conditions in multi-worker environments\\n        from tempfile import gettempdir\\n\\n        from filelock import FileLock\\n\\n        username = settings_service.auth_settings.SUPERUSER or DEFAULT_SUPERUSER\\n        configured_password = _secret_value(settings_service.auth_settings.SUPERUSER_PASSWORD)\\n        if configured_password == LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value():\\n            await logger.awarning(\\n                \\\"Ignoring legacy default LANGFLOW_SUPERUSER_PASSWORD in AUTO_LOGIN mode; \\\"\\n                \\\"generated a random bootstrap password instead.\\\"\\n            )\\n        password = get_auto_login_superuser_password(settings_service.auth_settings)\\n\\n        # Use file lock similar to starter projects\\n        lock_file = Path(gettempdir()) / \\\"langflow_auto_login_superuser.lock\\\"\\n        lock = FileLock(lock_file, timeout=5)\\n\\n        try:\\n            with lock:\\n                # Create user and initialize all related resources\\n                super_user = await get_or_create_super_user(\\n                    session,\\n                    username,\\n                    password,\\n                    is_default=True,\\n                    rotate_legacy_default_password=True,\\n                )\\n                if super_user:  # Only initialize if user was created\\n                    from langflow.initial_setup.setup import get_or_create_default_folder\\n                    from langflow.services.deps import get_variable_service\\n\\n                    # Recover MCP server config files orphaned when DB was reset but LANGFLOW_CONFIG_DIR was kept.\\n                    await migrate_orphaned_mcp_servers_config(session, settings_service, super_user)\\n\\n                    await get_variable_service().initialize_user_variables(super_user.id, session)\\n\\n                    # NOTE: Agentic variables are initialized separately in preload or main lifespan\\n                    # via initialize_agentic_global_variables() which handles all users at once.\\n                    # Do NOT initialize them here to avoid conflicts during preload.\\n\\n                    _ = await get_or_create_default_folder(session, super_user.id)\\n                    await logger.adebug(\\\"Auto-login superuser initialized successfully\\\")\\n                    return SetupSuperuserResult.AUTO_LOGIN_INITIALIZED\\n                existing_superuser = await _get_superuser_by_username(session, username)\\n                if existing_superuser is None:\\n                    msg = \\\"AUTO_LOGIN is enabled but the configured bootstrap user is not a superuser.\\\"\\n                    await logger.aerror(msg)\\n                    raise RuntimeError(msg)\\n                return SetupSuperuserResult.AUTO_LOGIN_ALREADY_SATISFIED\\n        except TimeoutError as exc:\\n            # Another worker may be handling it - but a stale/abandoned lock or dead holder\\n            # yields the same timeout with no initialization.\\n            await logger.awarning(\\n                \\\"Timed out waiting for AUTO_LOGIN superuser initialization lock \\\"\\n                \\\"(another worker may hold it, or the lock file may be stale). \\\"\\n                \\\"Verifying whether the default superuser exists.\\\",\\n            )\\n            exists = (await _get_superuser_by_username(session, username)) is not None\\n            if not exists:\\n                msg = (\\n                    \\\"AUTO_LOGIN is enabled but the default superuser was not initialized: \\\"\\n                    \\\"could not acquire the initialization lock within the timeout and no matching \\\"\\n                    \\\"superuser exists in the database. Retry startup or create a superuser manually.\\\"\\n                )\\n                await logger.aerror(msg)\\n                raise RuntimeError(msg) from exc\\n            return SetupSuperuserResult.AUTO_LOGIN_LOCK_TIMEOUT_SUPERUSER_PRESENT\\n        finally:\\n            settings_service.auth_settings.reset_credentials()\\n    # Remove the default superuser if it exists\\n    await teardown_superuser(settings_service, session)\\n    # If AUTO_LOGIN is disabled, require configured credentials.\\n    username = settings_service.auth_settings.SUPERUSER or DEFAULT_SUPERUSER\\n    password = _secret_value(settings_service.auth_settings.SUPERUSER_PASSWORD)\\n\\n    await logger.adebug(f\\\"Setup superuser: username={username}, has_password={bool(password)}\\\")\\n\\n    if not username or not password:\\n        msg = \\\"Username and password must be set\\\"\\n        await logger.aerror(f\\\"Missing credentials: username={username}, password={'set' if password else 'not set'}\\\")\\n        raise ValueError(msg)\\n\\n    if password == LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value():\\n        msg = \\\"LANGFLOW_SUPERUSER_PASSWORD cannot use the legacy default password\\\"\\n        await logger.aerror(msg)\\n        raise ValueError(msg)\\n\\n    is_default = (username == DEFAULT_SUPERUSER) and (password == LEGACY_DEFAULT_SUPERUSER_PASSWORD.get_secret_value())\\n\\n    try:\\n        await logger.adebug(f\\\"Creating/getting superuser: username={username}, is_default={is_default}\\\")\\n        user = await get_or_create_super_user(\\n            session=session,\\n            username=username,\\n            password=password,\\n            is_default=is_default,\\n            rotate_legacy_default_password=True,\\n        )\\n        if user is not None:\\n            await logger.adebug(\\\"Superuser created successfully.\\\")\\n            outcome = SetupSuperuserResult.SUPERUSER_CREATED\\n            # When the default superuser is recreated (e.g. after a DB reset in\\n            # AUTO_LOGIN mode) the per-user MCP servers config file saved under the\\n            # previous UUID becomes orphaned on disk. Best-effort recover it so\\n            # users don't lose their MCP server configuration across restarts.\\n            if is_default and settings_service.auth_settings.AUTO_LOGIN:\\n                await migrate_orphaned_mcp_servers_config(session, settings_service, user)\\n        else:\\n            outcome = SetupSuperuserResult.SUPERUSER_UNCHANGED\\n    except Exception as exc:\\n        await logger.aexception(f\\\"Failed to create superuser: {exc}\\\")\\n        msg = \\\"Could not create superuser. Please create a superuser manually.\\\"\\n        raise RuntimeError(msg) from exc\\n    else:\\n        return outcome\\n    finally:\\n        # Scrub credentials from in-memory settings after setup\\n        settings_service.auth_settings.reset_credentials()\\n\\n\\nasync def migrate_orphaned_mcp_servers_config(\\n    session: AsyncSession,\\n    settings_service: SettingsService,\\n    current_user,\\n) -> bool:\\n    \\\"\\\"\\\"Best-effort recovery of MCP servers config files orphaned by a DB reset.\\n\\n    The MCP servers config is persisted on disk at\\n    ``{config_dir}/{user_id}/_mcp_servers_{user_id}.json`` and tracked in the DB\\n    via a ``File`` row. When Langflow starts with a fresh database but the same\\n    config directory (common in containerized deployments without a persisted DB\\n    volume), the default superuser is recreated with a new UUID and the\\n    previously saved MCP config files become unreachable.\\n\\n    Recovery rules (intentionally conservative to avoid importing another user's\\n    config \u2014 MCP server entries can contain ``env`` and ``headers`` auth material):\\n\\n    * If the new user already has an MCP config file on disk without a matching\\n      ``File`` row, re-register the row (self-heal a partial previous migration).\\n    * If exactly one orphaned ``_mcp_servers_{uuid}.json`` is found in the config\\n      directory, migrate it.\\n    * If multiple orphans are found, skip and log \u2014 we can't safely identify the\\n      previous default superuser's file without extra metadata, so leave manual\\n      recovery to the operator.\\n\\n    Returns True when a file was migrated or a missing DB row was restored.\\n    \\\"\\\"\\\"\\n    from uuid import UUID\\n\\n    import aiofiles\\n    import anyio\\n\\n    from langflow.services.database.models.file.model import File as UserFile\\n\\n    try:\\n        config_dir_value = settings_service.settings.config_dir\\n        if not config_dir_value:\\n            return False\\n\\n        config_dir = Path(config_dir_value)\\n        if not config_dir.exists() or not config_dir.is_dir():\\n            return False\\n\\n        name_without_ext = f\\\"_mcp_servers_{current_user.id}\\\"\\n        existing_stmt = (\\n            select(UserFile).where(UserFile.user_id == current_user.id).where(UserFile.name == name_without_ext)\\n        )\\n        if (await session.exec(existing_stmt)).first() is not None:\\n            return False\\n\\n        current_user_dir = str(current_user.id)\\n        new_dir = config_dir / current_user_dir\\n        new_filename = f\\\"_mcp_servers_{current_user.id}.json\\\"\\n        new_file_path = new_dir / new_filename\\n        db_path = f\\\"{current_user.id}/{new_filename}\\\"\\n\\n        # Case 1: a previous migration attempt copied the file but failed before\\n        # committing the DB row. Re-register the existing file instead of\\n        # returning early and leaving the user with an invisible config.\\n        if new_file_path.exists():\\n            try:\\n                size = new_file_path.stat().st_size\\n            except OSError as exc:\\n                await logger.awarning(\\n                    \\\"Cannot stat existing MCP config %s while self-healing DB row: %s\\\",\\n                    new_file_path,\\n                    exc,\\n                )\\n                return False\\n            session.add(UserFile(user_id=current_user.id, name=name_without_ext, path=db_path, size=size))\\n            await session.commit()\\n            await logger.ainfo(\\n                \\\"Restored missing MCP servers config DB row for user %s from existing file %s\\\",\\n                current_user.id,\\n                new_file_path,\\n            )\\n            return True\\n\\n        def _find_orphans() -> list[tuple[float, Path]]:\\n            orphans: list[tuple[float, Path]] = []\\n            for entry in config_dir.iterdir():\\n                if not entry.is_dir() or entry.name == current_user_dir:\\n                    continue\\n                try:\\n                    UUID(entry.name)\\n                except ValueError:\\n                    continue\\n                mcp_path = entry / f\\\"_mcp_servers_{entry.name}.json\\\"\\n                if mcp_path.is_file():\\n                    try:\\n                        mtime = mcp_path.stat().st_mtime\\n                    except OSError:\\n                        continue\\n                    orphans.append((mtime, mcp_path))\\n            return orphans\\n\\n        orphans = await anyio.to_thread.run_sync(_find_orphans)\\n        if not orphans:\\n            return False\\n\\n        if len(orphans) > 1:\\n            orphan_paths = \\\", \\\".join(str(p) for _, p in sorted(orphans, key=lambda i: i[0], reverse=True))\\n            await logger.awarning(\\n                \\\"Found %d orphaned MCP servers config files in %s; skipping automatic \\\"\\n                \\\"migration to avoid restoring the wrong one. Move the intended file to \\\"\\n                \\\"%s to recover. Candidates: %s\\\",\\n                len(orphans),\\n                config_dir,\\n                new_file_path,\\n                orphan_paths,\\n            )\\n            return False\\n\\n        _, orphan_path = orphans[0]\\n\\n        async with aiofiles.open(str(orphan_path), \\\"rb\\\") as src:\\n            data = await src.read()\\n\\n        await anyio.to_thread.run_sync(lambda: new_dir.mkdir(parents=True, exist_ok=True))\\n        async with aiofiles.open(str(new_file_path), \\\"wb\\\") as dst:\\n            await dst.write(data)\\n\\n        session.add(UserFile(user_id=current_user.id, name=name_without_ext, path=db_path, size=len(data)))\\n        await session.commit()\\n\\n        await logger.ainfo(\\n            \\\"Migrated orphaned MCP servers config from %s to user %s\\\",\\n            orphan_path,\\n            current_user.id,\\n        )\\n    except Exception as exc:  # noqa: BLE001\\n        await logger.awarning(\\\"Failed to migrate orphaned MCP servers config: %s\\\", exc)\\n        return False\\n    else:\\n        return True\\n\\n\\nasync def teardown_superuser(settings_service: SettingsService, session: AsyncSession) -> None:\\n    \\\"\\\"\\\"Remove the default superuser when AUTO_LOGIN is disabled and it was never used to sign in.\\n\\n    If the default account has ``last_login_at`` set, it is kept. Deletion can still fail with\\n    an integrity error when the user owns rows (e.g. flows) without ORM cascade \u2014 callers see\\n    ``RuntimeError`` so startup or shutdown does not silently ignore the problem.\\n    \\\"\\\"\\\"\\n    if not settings_service.auth_settings.AUTO_LOGIN:\\n        await logger.adebug(\\\"AUTO_LOGIN is set to False. Removing default superuser if unused.\\\")\\n        try:\\n            username = DEFAULT_SUPERUSER\\n            from langflow.services.database.models.user.model import User\\n\\n            stmt = select(User).where(User.username == username)\\n            result = await session.exec(stmt)\\n            user = result.first()\\n\\n            if user and user.is_superuser is True and not user.last_login_at:\\n                await session.delete(user)\\n                await logger.adebug(\\\"Default superuser removed successfully.\\\")\\n        except Exception as exc:\\n            await logger.aexception(\\\"Could not remove default superuser.\\\")\\n            msg = \\\"Could not remove default superuser.\\\"\\n            raise RuntimeError(msg) from exc\\n\\n\\nasync def teardown_services() -> None:\\n    \\\"\\\"\\\"Teardown all the services.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        await teardown_superuser(get_settings_service(), session)\\n\\n    from lfx.services.manager import get_service_manager\\n\\n    service_manager = get_service_manager()\\n    await service_manager.teardown()\\n\\n\\ndef initialize_settings_service() -> None:\\n    \\\"\\\"\\\"Initialize the settings manager.\\\"\\\"\\\"\\n    from lfx.services.settings import factory as settings_factory\\n\\n    get_service(ServiceType.SETTINGS_SERVICE, settings_factory.SettingsServiceFactory())\\n\\n\\ndef initialize_session_service() -> None:\\n    \\\"\\\"\\\"Initialize the session manager.\\\"\\\"\\\"\\n    from langflow.services.cache import factory as cache_factory\\n    from langflow.services.session import factory as session_service_factory\\n\\n    initialize_settings_service()\\n\\n    get_service(\\n        ServiceType.CACHE_SERVICE,\\n        cache_factory.CacheServiceFactory(),\\n    )\\n\\n    get_service(\\n        ServiceType.SESSION_SERVICE,\\n        session_service_factory.SessionServiceFactory(),\\n    )\\n\\n\\nasync def clean_transactions(settings_service: SettingsService, session: AsyncSession) -> None:\\n    \\\"\\\"\\\"Clean up old transactions from the database.\\n\\n    This function deletes transactions that exceed the maximum number to keep (configured in settings).\\n    It orders transactions by timestamp descending and removes the oldest ones beyond the limit.\\n\\n    Args:\\n        settings_service: The settings service containing configuration like max_transactions_to_keep\\n        session: The database session to use for the deletion\\n    \\\"\\\"\\\"\\n    try:\\n        # Delete transactions using bulk delete\\n        delete_stmt = delete(TransactionTable).where(\\n            col(TransactionTable.id).in_(\\n                select(TransactionTable.id)\\n                .order_by(col(TransactionTable.timestamp).desc())\\n                .offset(settings_service.settings.max_transactions_to_keep)\\n            )\\n        )\\n\\n        await session.exec(delete_stmt)\\n        logger.debug(\\\"Successfully cleaned up old transactions\\\")\\n    except (sqlalchemy_exc.SQLAlchemyError, asyncio.TimeoutError) as exc:\\n        logger.error(f\\\"Error cleaning up transactions: {exc!s}\\\")\\n        # Don't re-raise since this is a cleanup task\\n\\n\\nasync def clean_authz_audit_log(settings_service: SettingsService, session: AsyncSession) -> int:\\n    \\\"\\\"\\\"Delete authz_audit_log rows older than ``AUTHZ_AUDIT_RETENTION_DAYS``.\\n\\n    Retention is configured via ``AuthSettings.AUTHZ_AUDIT_RETENTION_DAYS``;\\n    setting it to ``0`` disables pruning so operators relying on an external\\n    archival pipeline (Postgres partitioning, SIEM export) can opt out without\\n    losing rows here. The function is intentionally best-effort: failures are\\n    logged and swallowed so startup never fails because the audit table is\\n    transiently unreachable.\\n\\n    Returns the number of rows deleted (best-effort; ``-1`` when the rowcount\\n    is unavailable from the driver).\\n    \\\"\\\"\\\"\\n    try:\\n        retention_days = int(getattr(settings_service.auth_settings, \\\"AUTHZ_AUDIT_RETENTION_DAYS\\\", 90))\\n    except Exception:  # noqa: BLE001 \u2014 settings shape can vary in tests/stubs\\n        retention_days = 90\\n    if retention_days <= 0:\\n        logger.debug(\\\"authz_audit_log retention disabled (AUTHZ_AUDIT_RETENTION_DAYS=%d)\\\", retention_days)\\n        return 0\\n\\n    from datetime import datetime, timedelta, timezone\\n\\n    from langflow.services.database.models.auth import AuthzAuditLog\\n\\n    cutoff = datetime.now(timezone.utc) - timedelta(days=retention_days)\\n    try:\\n        delete_stmt = delete(AuthzAuditLog).where(col(AuthzAuditLog.timestamp) < cutoff)\\n        result = await session.exec(delete_stmt)\\n        deleted = getattr(result, \\\"rowcount\\\", None)\\n        deleted_count = int(deleted) if deleted is not None and deleted >= 0 else -1\\n        logger.debug(\\n            \\\"authz_audit_log cleanup removed %s rows older than %d days\\\",\\n            deleted_count if deleted_count >= 0 else \\\"?\\\",\\n            retention_days,\\n        )\\n    except (sqlalchemy_exc.SQLAlchemyError, asyncio.TimeoutError) as exc:\\n        logger.warning(\\\"authz_audit_log cleanup failed: %s\\\", exc)\\n        return -1\\n    else:\\n        return deleted_count\\n\\n\\nasync def clean_vertex_builds(settings_service: SettingsService, session: AsyncSession) -> None:\\n    \\\"\\\"\\\"Clean up old vertex builds from the database.\\n\\n    This function deletes vertex builds that exceed the maximum number to keep (configured in settings).\\n    It orders vertex builds by timestamp descending and removes the oldest ones beyond the limit.\\n\\n    Args:\\n        settings_service: The settings service containing configuration like max_vertex_builds_to_keep\\n        session: The database session to use for the deletion\\n    \\\"\\\"\\\"\\n    try:\\n        # Delete vertex builds using bulk delete\\n        delete_stmt = delete(VertexBuildTable).where(\\n            col(VertexBuildTable.id).in_(\\n                select(VertexBuildTable.id)\\n                .order_by(col(VertexBuildTable.timestamp).desc())\\n                .offset(settings_service.settings.max_vertex_builds_to_keep)\\n            )\\n        )\\n\\n        await session.exec(delete_stmt)\\n        logger.debug(\\\"Successfully cleaned up old vertex builds\\\")\\n    except (sqlalchemy_exc.SQLAlchemyError, asyncio.TimeoutError) as exc:\\n        logger.error(f\\\"Error cleaning up vertex builds: {exc!s}\\\")\\n        # Don't re-raise since this is a cleanup task\\n\\n\\ndef register_all_service_factories() -> None:\\n    \\\"\\\"\\\"Register all available service factories with the service manager.\\\"\\\"\\\"\\n    # Import all service factories\\n    from lfx.services.manager import get_service_manager\\n    from lfx.services.schema import ServiceType\\n\\n    service_manager = get_service_manager()\\n    from lfx.services.executor import factory as executor_factory\\n    from lfx.services.mcp_composer import factory as mcp_composer_factory\\n    from lfx.services.model_provider_policy.service import ModelProviderPolicyService\\n    from lfx.services.policy_bundle.service import PolicyBundleService\\n    from lfx.services.settings import factory as settings_factory\\n\\n    from langflow.services.auth import factory as auth_factory\\n    from langflow.services.auth.service import AuthService\\n    from langflow.services.authorization import factory as authorization_factory\\n    from langflow.services.authorization.service import LangflowAuthorizationService\\n    from langflow.services.cache import factory as cache_factory\\n    from langflow.services.catalog_policy import factory as catalog_policy_factory\\n    from langflow.services.catalog_policy.service import LangflowCatalogPolicyService\\n    from langflow.services.chat import factory as chat_factory\\n    from langflow.services.checkpoint import factory as checkpoint_factory\\n    from langflow.services.database import factory as database_factory\\n    from langflow.services.job_queue import factory as job_queue_factory\\n    from langflow.services.session import factory as session_factory\\n    from langflow.services.shared_component_cache import factory as shared_component_cache_factory\\n    from langflow.services.state import factory as state_factory\\n    from langflow.services.storage import factory as storage_factory\\n    from langflow.services.store import factory as store_factory\\n    from langflow.services.task import factory as task_factory\\n    from langflow.services.telemetry import factory as telemetry_factory\\n    from langflow.services.telemetry_writer import factory as telemetry_writer_factory\\n    from langflow.services.tracing import factory as tracing_factory\\n    from langflow.services.transaction import factory as transaction_factory\\n    from langflow.services.variable import factory as variable_factory\\n\\n    # Register all factories\\n    service_manager.register_factory(settings_factory.SettingsServiceFactory())\\n    service_manager.register_factory(cache_factory.CacheServiceFactory())\\n    service_manager.register_factory(chat_factory.ChatServiceFactory())\\n    service_manager.register_factory(database_factory.DatabaseServiceFactory())\\n    service_manager.register_factory(session_factory.SessionServiceFactory())\\n    service_manager.register_factory(storage_factory.StorageServiceFactory())\\n    service_manager.register_factory(variable_factory.VariableServiceFactory())\\n    service_manager.register_factory(telemetry_factory.TelemetryServiceFactory())\\n    service_manager.register_factory(tracing_factory.TracingServiceFactory())\\n    service_manager.register_factory(transaction_factory.TransactionServiceFactory())\\n    service_manager.register_factory(telemetry_writer_factory.TelemetryWriterServiceFactory())\\n    service_manager.register_factory(state_factory.StateServiceFactory())\\n    service_manager.register_factory(checkpoint_factory.CheckpointServiceFactory())\\n    service_manager.register_factory(job_queue_factory.JobQueueServiceFactory())\\n    service_manager.register_factory(task_factory.TaskServiceFactory())\\n    service_manager.register_factory(store_factory.StoreServiceFactory())\\n    service_manager.register_factory(shared_component_cache_factory.SharedComponentCacheServiceFactory())\\n    # Override LFX's no-op auth service with Langflow's full JWT implementation\\n    service_manager.register_service_class(ServiceType.AUTH_SERVICE, AuthService, override=True)\\n    service_manager.register_factory(auth_factory.AuthServiceFactory())\\n    # Same pattern as ``auth_service``: register the OSS pass-through here with\\n    # ``override=True`` so Langflow always has a default. A registered\\n    # authorization plugin replaces it by listing its class in\\n    # ``LANGFLOW_CONFIG_DIR/lfx.toml`` (config files use ``override=True`` via\\n    # ``_discover_from_config``). Plain entry-point discovery uses\\n    # ``override=False`` and would lose to this default \u2014 the supported\\n    # override path is the ``lfx.toml`` config, matching SSO.\\n    service_manager.register_service_class(\\n        ServiceType.AUTHORIZATION_SERVICE, LangflowAuthorizationService, override=True\\n    )\\n    service_manager.register_factory(authorization_factory.AuthorizationServiceFactory())\\n    service_manager.register_service_class(\\n        ServiceType.POLICY_BUNDLE_SERVICE,\\n        PolicyBundleService,\\n        override=True,\\n    )\\n    service_manager.register_service_class(\\n        ServiceType.CATALOG_POLICY_SERVICE,\\n        LangflowCatalogPolicyService,\\n        override=True,\\n    )\\n    service_manager.register_factory(catalog_policy_factory.CatalogPolicyServiceFactory())\\n    service_manager.register_service_class(\\n        ServiceType.MODEL_PROVIDER_POLICY_SERVICE,\\n        ModelProviderPolicyService,\\n        override=True,\\n    )\\n    service_manager.register_factory(mcp_composer_factory.MCPComposerServiceFactory())\\n    service_manager.register_factory(executor_factory.ExecutorServiceFactory())\\n    service_manager.set_factory_registered()\\n\\n\\ndef register_builtin_adapters() -> None:\\n    \\\"\\\"\\\"Import built-in adapter registration modules.\\n\\n    Mirrors ``register_all_service_factories()`` for the adapter registry system.\\n    Each import registers the adapter class on the AdapterRegistry singleton.\\n\\n    TODO: Watsonx risks are documented here because registration is runtime-optional:\\n    missing ``ibm_*`` modules should skip adapter registration, but broad\\n    ``ModuleNotFoundError`` handling can also hide internal import regressions.\\n    Future deployment API routing must treat \\\"provider exists but adapter is not\\n    registered in this runtime\\\" as an explicit, deterministic error path.\\n    Keep direct adapter imports limited to guarded paths and maintain CI\\n    coverage that confirms Watsonx tests run (not skip) in eligible environments.\\n    \\\"\\\"\\\"\\n    if not FEATURE_FLAGS.wxo_deployments:\\n        logger.debug(\\\"Skipping deployment adapter registration: wxo_deployments feature flag disabled\\\")\\n        return\\n\\n    try:\\n        import_module(\\\"langflow.services.adapters.deployment.watsonx_orchestrate.register\\\")\\n    except ModuleNotFoundError as exc:\\n        logger.info(\\\"Skipping Watsonx Orchestrate adapter registration: %s\\\", exc)\\n\\n\\ndef register_builtin_deployment_mappers() -> None:\\n    \\\"\\\"\\\"Import built-in deployment mapper modules so registration side effects fire.\\\"\\\"\\\"\\n    if not FEATURE_FLAGS.wxo_deployments:\\n        logger.debug(\\\"Skipping deployment mapper registration: wxo_deployments feature flag disabled\\\")\\n        return\\n\\n    try:\\n        import_module(\\\"langflow.api.v1.mappers.deployments.watsonx_orchestrate\\\")\\n    except ModuleNotFoundError as exc:\\n        logger.info(\\\"Skipping Watsonx Orchestrate deployment mapper registration: %s\\\", exc)\\n\\n\\nasync def hydrate_catalog_policy() -> None:\\n    \\\"\\\"\\\"Hydrate durable catalog policy without making startup fail closed.\\\"\\\"\\\"\\n    from langflow.services.deps import get_catalog_policy_service\\n\\n    try:\\n        await get_catalog_policy_service().hydrate()\\n    except Exception as exc:  # noqa: BLE001\\n        # Catalog policy is explicitly fail-open. Keep the immutable empty\\n        # snapshot when durable policy cannot be hydrated, but make the\\n        # governance outage visible to operators.\\n        await logger.awarning(\\\"Catalog policy hydration failed; continuing with allow-all policy: %s\\\", exc)\\n\\n\\nasync def initialize_services(*, fix_migration: bool = False, skip_superuser_setup: bool = False) -> None:\\n    \\\"\\\"\\\"Initialize all the services needed.\\\"\\\"\\\"\\n    from langflow.helpers.windows_postgres_helper import configure_windows_postgres_event_loop\\n\\n    configure_windows_postgres_event_loop(source=\\\"initialize_services\\\")\\n\\n    # Register all service factories first\\n    register_all_service_factories()\\n    register_builtin_adapters()\\n    register_builtin_deployment_mappers()\\n\\n    cache_service = get_service(ServiceType.CACHE_SERVICE, default=CacheServiceFactory())\\n    # Test external cache connection\\n    if isinstance(cache_service, ExternalAsyncBaseCacheService) and not (await cache_service.is_connected()):\\n        msg = \\\"Cache service failed to connect to external database\\\"\\n        raise ConnectionError(msg)\\n\\n    # Fail fast if the Redis-backed job queue is selected but Redis is unreachable.\\n    # Otherwise Langflow boots \\\"fine\\\" and emits confusing connection errors only\\n    # when a flow is executed. Only probes when the redis backend is selected, so\\n    # the default asyncio backend is unaffected.\\n    if get_settings_service().settings.job_queue_type == \\\"redis\\\":\\n        from langflow.services.job_queue.factory import JobQueueServiceFactory\\n        from langflow.services.job_queue.service import RedisJobQueueService\\n\\n        queue_service = get_service(ServiceType.JOB_QUEUE_SERVICE, default=JobQueueServiceFactory())\\n        if isinstance(queue_service, RedisJobQueueService) and not (await queue_service.is_connected()):\\n            msg = (\\n                f\\\"Job queue backend 'redis' is selected (LANGFLOW_JOB_QUEUE_TYPE=redis) but Redis is \\\"\\n                f\\\"not reachable at {queue_service.connection_target}. Start Redis, fix the \\\"\\n                \\\"LANGFLOW_REDIS_QUEUE_* settings, or set LANGFLOW_JOB_QUEUE_TYPE=asyncio.\\\"\\n            )\\n            raise ConnectionError(msg)\\n\\n    # Setup the superuser\\n    await initialize_database(fix_migration=fix_migration)\\n    from langflow.services.policy_bundle import hydrate_policy_bundle\\n\\n    async with session_scope() as session:\\n        await hydrate_policy_bundle(session)\\n    # Preserve the pre-bundle plugin lifecycle for catalog implementations\\n    # that load their own source in hydrate(). Bundle-aware services treat\\n    # this as an idempotent read of the already published revision.\\n    await hydrate_catalog_policy()\\n    db_service = get_db_service()\\n    await db_service.initialize_alembic_log_file()\\n    settings_service = get_service(ServiceType.SETTINGS_SERVICE)\\n    if not skip_superuser_setup:\\n        async with session_scope() as session:\\n            await setup_superuser(settings_service, session)\\n        try:\\n            await get_db_service().assign_orphaned_flows_to_superuser()\\n        except sqlalchemy_exc.IntegrityError as exc:\\n            await logger.awarning(f\\\"Error assigning orphaned flows to the superuser: {exc!s}\\\")\\n\\n    async with session_scope() as session:\\n        await clean_transactions(settings_service, session)\\n        await clean_vertex_builds(settings_service, session)\\n        await clean_authz_audit_log(settings_service, session)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/variable/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/variable/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b96f0d29a8eeb75deadbec6848ec59f9ffbe6cc9b5f60857da490dd007464ee7\",\"content\":\"import abc\\nfrom uuid import UUID\\n\\nfrom pydantic import SecretStr\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.services.base import Service\\nfrom langflow.services.database.models.variable.model import Variable, VariableRead, VariableUpdate\\n\\n\\nclass VariableService(Service):\\n    \\\"\\\"\\\"Abstract base class for a variable service.\\\"\\\"\\\"\\n\\n    name = \\\"variable_service\\\"\\n\\n    async def initialize_all_user_variables(self) -> None:\\n        \\\"\\\"\\\"Sync environment defaults at startup; external stores opt out by default.\\\"\\\"\\\"\\n\\n    async def get_default_field_bindings(\\n        self,\\n        user_id: UUID | str,\\n        session: AsyncSession,\\n    ) -> list[tuple[str, list[str] | None]]:\\n        \\\"\\\"\\\"Return non-secret variable metadata used for default-field binding.\\n\\n        External variable-service implementations remain source compatible and\\n        opt out by default. Implementations must not fetch or decrypt values.\\n        \\\"\\\"\\\"\\n        _ = user_id, session\\n        return []\\n\\n    @abc.abstractmethod\\n    async def initialize_user_variables(self, user_id: UUID | str, session: AsyncSession) -> None:\\n        \\\"\\\"\\\"Initialize user variables.\\n\\n        Args:\\n            user_id: The user ID.\\n            session: The database session.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def get_variable(self, user_id: UUID | str, name: str, field: str, session: AsyncSession) -> str | SecretStr:\\n        \\\"\\\"\\\"Async get a variable value.\\n\\n        Args:\\n            user_id: The user ID.\\n            name: The name of the variable.\\n            field: The field of the variable.\\n            session: The database session.\\n\\n        Returns:\\n            The value of the variable.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def list_variables(self, user_id: UUID | str, session: AsyncSession) -> list[str | None]:\\n        \\\"\\\"\\\"List all variables.\\n\\n        Args:\\n            user_id: The user ID.\\n            session: The database session.\\n\\n        Returns:\\n            A list of variable names.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def update_variable(self, user_id: UUID | str, name: str, value: str, session: AsyncSession) -> Variable:\\n        \\\"\\\"\\\"Update a variable.\\n\\n        Args:\\n            user_id: The user ID.\\n            name: The name of the variable.\\n            value: The value of the variable.\\n            session: The database session.\\n\\n        Returns:\\n            The updated variable.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def delete_variable(self, user_id: UUID | str, name: str, session: AsyncSession) -> None:\\n        \\\"\\\"\\\"Delete a variable.\\n\\n        Args:\\n            user_id: The user ID.\\n            name: The name of the variable.\\n            session: The database session.\\n\\n        Returns:\\n            The deleted variable.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def delete_variable_by_id(self, user_id: UUID | str, variable_id: UUID, session: AsyncSession) -> None:\\n        \\\"\\\"\\\"Delete a variable by ID.\\n\\n        Args:\\n            user_id: The user ID.\\n            variable_id: The ID of the variable.\\n            session: The database session.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def create_variable(\\n        self,\\n        user_id: UUID | str,\\n        name: str,\\n        value: str,\\n        *,\\n        default_fields: list[str],\\n        type_: str,\\n        session: AsyncSession,\\n    ) -> Variable:\\n        \\\"\\\"\\\"Create a variable.\\n\\n        Args:\\n            user_id: The user ID.\\n            name: The name of the variable.\\n            value: The value of the variable.\\n            default_fields: The default fields of the variable.\\n            type_: The type of the variable.\\n            session: The database session.\\n\\n        Returns:\\n            The created variable.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def get_all(self, user_id: UUID | str, session: AsyncSession) -> list[VariableRead]:\\n        \\\"\\\"\\\"Get all variables.\\n\\n        Args:\\n            user_id: The user ID.\\n            session: The database session.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def get_variable_by_id(self, user_id: UUID | str, variable_id: UUID | str, session: AsyncSession) -> Variable:\\n        \\\"\\\"\\\"Get a variable by ID.\\n\\n        Args:\\n            user_id: The user ID.\\n            variable_id: The ID of the variable.\\n            session: The database session.\\n\\n        Returns:\\n            The variable.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def get_variable_object(self, user_id: UUID | str, name: str, session: AsyncSession) -> Variable:\\n        \\\"\\\"\\\"Get a variable object by name.\\n\\n        Args:\\n            user_id: The user ID.\\n            name: The name of the variable.\\n            session: The database session.\\n\\n        Returns:\\n            The variable object.\\n        \\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    async def update_variable_fields(\\n        self, user_id: UUID | str, variable_id: UUID | str, variable: VariableUpdate, session: AsyncSession\\n    ) -> Variable:\\n        \\\"\\\"\\\"Update specific fields of a variable.\\n\\n        Args:\\n            user_id: The user ID.\\n            variable_id: The ID of the variable.\\n            variable: The variable update model with fields to update.\\n            session: The database session.\\n\\n        Returns:\\n            The updated variable.\\n        \\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/variable/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0d840b46bc378943632dc61cb76a63c9c0d9e28097a4b9cb9e7393292828213a\",\"content\":\"CREDENTIAL_TYPE = \\\"Credential\\\"\\nGENERIC_TYPE = \\\"Generic\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/variable/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"852e6205179f75c0bbef808947211aae8cf767fb418b662d04e71cadd496653c\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom typing_extensions import override\\n\\nfrom langflow.services.factory import ServiceFactory\\nfrom langflow.services.variable.service import DatabaseVariableService, VariableService\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.service import SettingsService\\n\\n\\nclass VariableServiceFactory(ServiceFactory):\\n    def __init__(self) -> None:\\n        super().__init__(VariableService)\\n\\n    @override\\n    def create(self, settings_service: SettingsService):\\n        # here you would have logic to create and configure a VariableService\\n        # based on the settings_service\\n\\n        if settings_service.settings.variable_store == \\\"kubernetes\\\":\\n            # Keep it here to avoid import errors\\n            from langflow.services.variable.kubernetes import KubernetesSecretService\\n\\n            return KubernetesSecretService(settings_service)\\n        return DatabaseVariableService(settings_service)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/variable/kubernetes.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ff9e42655378152fdffac1e24753f5913a80da7fa0de2de533e3e213f1ed5d6d\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport os\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.variable import VariableNotFoundError\\nfrom typing_extensions import override\\n\\nfrom langflow.services.auth import utils as auth_utils\\nfrom langflow.services.base import Service\\nfrom langflow.services.database.models.variable.model import Variable, VariableCreate, VariableRead, VariableUpdate\\nfrom langflow.services.variable.base import VariableService\\nfrom langflow.services.variable.constants import CREDENTIAL_TYPE, GENERIC_TYPE\\nfrom langflow.services.variable.kubernetes_secrets import KubernetesSecretManager, encode_user_id\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from lfx.services.settings.service import SettingsService\\n    from sqlmodel import Session\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\nclass KubernetesSecretService(VariableService, Service):\\n    def __init__(self, settings_service: SettingsService):\\n        self.settings_service = settings_service\\n        # TODO: settings_service to set kubernetes namespace\\n        self.kubernetes_secrets = KubernetesSecretManager()\\n\\n    @override\\n    async def initialize_user_variables(self, user_id: UUID | str, session: AsyncSession) -> None:\\n        # Check for environment variables that should be stored in the database\\n        should_or_should_not = \\\"Should\\\" if self.settings_service.settings.store_environment_variables else \\\"Should not\\\"\\n        await logger.ainfo(f\\\"{should_or_should_not} store environment variables in the kubernetes.\\\")\\n        if self.settings_service.settings.store_environment_variables:\\n            variables = {}\\n            for var in self.settings_service.settings.variables_to_get_from_environment:\\n                if var in os.environ:\\n                    await logger.adebug(f\\\"Creating {var} variable from environment.\\\")\\n                    value = os.environ[var]\\n                    if isinstance(value, str):\\n                        value = value.strip()\\n                    key = CREDENTIAL_TYPE + \\\"_\\\" + var\\n                    variables[key] = str(value)\\n\\n            try:\\n                secret_name = encode_user_id(user_id)\\n                await asyncio.to_thread(\\n                    self.kubernetes_secrets.create_secret,\\n                    name=secret_name,\\n                    data=variables,\\n                )\\n            except Exception:  # noqa: BLE001\\n                logger.exception(f\\\"Error creating {var} variable\\\")\\n\\n        else:\\n            logger.info(\\\"Skipping environment variable storage.\\\")\\n\\n    # resolve_variable is a helper function that resolves the variable name to the actual key in the secret\\n    def resolve_variable(\\n        self,\\n        secret_name: str,\\n        user_id: UUID | str,\\n        name: str,\\n    ) -> tuple[str, str]:\\n        variables = self.kubernetes_secrets.get_secret(name=secret_name)\\n        if not variables:\\n            msg = f\\\"user_id {user_id} variable not found.\\\"\\n            raise VariableNotFoundError(msg)\\n\\n        if name in variables:\\n            return name, variables[name]\\n        credential_name = CREDENTIAL_TYPE + \\\"_\\\" + name\\n        if credential_name in variables:\\n            return credential_name, variables[credential_name]\\n        msg = f\\\"user_id {user_id} variable name {name} not found.\\\"\\n        raise VariableNotFoundError(msg)\\n\\n    @override\\n    async def get_variable(self, user_id: UUID | str, name: str, field: str, session: AsyncSession) -> str:\\n        secret_name = encode_user_id(user_id)\\n        key, value = await asyncio.to_thread(self.resolve_variable, secret_name, user_id, name)\\n        if key.startswith(CREDENTIAL_TYPE + \\\"_\\\") and field == \\\"session_id\\\":\\n            msg = (\\n                f\\\"variable {name} of type 'Credential' cannot be used in a Session ID field \\\"\\n                \\\"because its purpose is to prevent the exposure of values.\\\"\\n            )\\n            raise TypeError(msg)\\n        return value\\n\\n    @override\\n    async def list_variables(\\n        self,\\n        user_id: UUID | str,\\n        session: Session,\\n    ) -> list[str | None]:\\n        variables = await asyncio.to_thread(self.kubernetes_secrets.get_secret, name=encode_user_id(user_id))\\n        if not variables:\\n            return []\\n\\n        names = []\\n        for key in variables:\\n            if key.startswith(CREDENTIAL_TYPE + \\\"_\\\"):\\n                names.append(key[len(CREDENTIAL_TYPE) + 1 :])\\n            else:\\n                names.append(key)\\n        return names\\n\\n    def _update_variable(\\n        self,\\n        user_id: UUID | str,\\n        name: str,\\n        value: str,\\n    ):\\n        secret_name = encode_user_id(user_id)\\n        secret_key, _ = self.resolve_variable(secret_name, user_id, name)\\n        return self.kubernetes_secrets.update_secret(name=secret_name, data={secret_key: value})\\n\\n    @override\\n    async def update_variable(\\n        self,\\n        user_id: UUID | str,\\n        name: str,\\n        value: str,\\n        session: AsyncSession,\\n    ):\\n        return await asyncio.to_thread(self._update_variable, user_id, name, value)\\n\\n    def _delete_variable(self, user_id: UUID | str, name: str) -> None:\\n        secret_name = encode_user_id(user_id)\\n        secret_key, _ = self.resolve_variable(secret_name, user_id, name)\\n        self.kubernetes_secrets.delete_secret_key(name=secret_name, key=secret_key)\\n\\n    @override\\n    async def delete_variable(self, user_id: UUID | str, name: str, session: AsyncSession) -> None:\\n        await asyncio.to_thread(self._delete_variable, user_id, name)\\n\\n    @override\\n    async def delete_variable_by_id(self, user_id: UUID | str, variable_id: UUID | str, session: AsyncSession) -> None:\\n        await self.delete_variable(user_id, str(variable_id), session)\\n\\n    @override\\n    async def create_variable(\\n        self,\\n        user_id: UUID | str,\\n        name: str,\\n        value: str,\\n        *,\\n        default_fields: list[str],\\n        type_: str,\\n        session: AsyncSession,\\n    ) -> Variable:\\n        secret_name = encode_user_id(user_id)\\n        secret_key = name\\n        if type_ == CREDENTIAL_TYPE:\\n            secret_key = CREDENTIAL_TYPE + \\\"_\\\" + name\\n        else:\\n            type_ = GENERIC_TYPE\\n\\n        await asyncio.to_thread(\\n            self.kubernetes_secrets.upsert_secret, secret_name=secret_name, data={secret_key: value}\\n        )\\n\\n        variable_base = VariableCreate(\\n            name=name,\\n            type=type_,\\n            value=auth_utils.encrypt_api_key(value),\\n            default_fields=default_fields,\\n        )\\n        return Variable.model_validate(variable_base, from_attributes=True, update={\\\"user_id\\\": user_id})\\n\\n    @override\\n    async def get_all(self, user_id: UUID | str, session: AsyncSession) -> list[VariableRead]:\\n        secret_name = encode_user_id(user_id)\\n        variables = await asyncio.to_thread(self.kubernetes_secrets.get_secret, name=secret_name)\\n        if not variables:\\n            return []\\n\\n        variables_read = []\\n        for key, value in variables.items():\\n            name = key\\n            type_ = GENERIC_TYPE\\n            if key.startswith(CREDENTIAL_TYPE + \\\"_\\\"):\\n                name = key[len(CREDENTIAL_TYPE) + 1 :]\\n                type_ = CREDENTIAL_TYPE\\n\\n            decrypted_value = None\\n            if type_ == GENERIC_TYPE:\\n                decrypted_value = value\\n\\n            variable_base = VariableCreate(\\n                name=name,\\n                type=type_,\\n                value=auth_utils.encrypt_api_key(value),\\n                default_fields=[],\\n            )\\n            variable = Variable.model_validate(variable_base, from_attributes=True, update={\\\"user_id\\\": user_id})\\n            variable_read = VariableRead.model_validate(variable, from_attributes=True)\\n            variable_read.value = decrypted_value\\n            variable_read.has_value = bool(value.strip())\\n            variables_read.append(variable_read)\\n\\n        return variables_read\\n\\n    @override\\n    async def get_variable_by_id(self, user_id: UUID | str, variable_id: UUID | str, session: AsyncSession) -> Variable:\\n        \\\"\\\"\\\"Get a variable by ID.\\n\\n        Note: Kubernetes secrets don't have IDs, so we use the variable_id as the name.\\n        \\\"\\\"\\\"\\n        secret_name = encode_user_id(user_id)\\n        key, value = await asyncio.to_thread(self.resolve_variable, secret_name, user_id, str(variable_id))\\n\\n        name = key\\n        type_ = GENERIC_TYPE\\n        if key.startswith(CREDENTIAL_TYPE + \\\"_\\\"):\\n            name = key[len(CREDENTIAL_TYPE) + 1 :]\\n            type_ = CREDENTIAL_TYPE\\n\\n        variable_base = VariableCreate(\\n            name=name,\\n            type=type_,\\n            value=auth_utils.encrypt_api_key(value),\\n            default_fields=[],\\n        )\\n        return Variable.model_validate(variable_base, from_attributes=True, update={\\\"user_id\\\": user_id})\\n\\n    @override\\n    async def get_variable_object(self, user_id: UUID | str, name: str, session: AsyncSession) -> Variable:\\n        \\\"\\\"\\\"Get a variable object by name.\\\"\\\"\\\"\\n        secret_name = encode_user_id(user_id)\\n        key, value = await asyncio.to_thread(self.resolve_variable, secret_name, user_id, name)\\n\\n        var_name = key\\n        type_ = GENERIC_TYPE\\n        if key.startswith(CREDENTIAL_TYPE + \\\"_\\\"):\\n            var_name = key[len(CREDENTIAL_TYPE) + 1 :]\\n            type_ = CREDENTIAL_TYPE\\n\\n        variable_base = VariableCreate(\\n            name=var_name,\\n            type=type_,\\n            value=auth_utils.encrypt_api_key(value),\\n            default_fields=[],\\n        )\\n        return Variable.model_validate(variable_base, from_attributes=True, update={\\\"user_id\\\": user_id})\\n\\n    @override\\n    async def update_variable_fields(\\n        self, user_id: UUID | str, variable_id: UUID | str, variable: VariableUpdate, session: AsyncSession\\n    ) -> Variable:\\n        \\\"\\\"\\\"Update specific fields of a variable.\\n\\n        Note: Kubernetes secrets don't have IDs, so we use the variable name for updates.\\n        \\\"\\\"\\\"\\n        if variable.name:\\n            name = variable.name\\n        else:\\n            # Try to get the current variable to find its name\\n            current_var = await self.get_variable_by_id(user_id, variable_id, session)\\n            name = current_var.name\\n\\n        if variable.value is not None:\\n            await self.update_variable(user_id, name, variable.value, session)\\n\\n        # Return the updated variable\\n        return await self.get_variable_object(user_id, name, session)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/variable/kubernetes_secrets.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d6cd5fa3540544b53b76bf61085569fcfda593a9079cb385a60eb5932967375b\",\"content\":\"from base64 import b64decode, b64encode\\nfrom http import HTTPStatus\\nfrom uuid import UUID\\n\\nfrom kubernetes import client, config\\nfrom kubernetes.client.rest import ApiException\\nfrom lfx.log.logger import logger\\n\\n\\nclass KubernetesSecretManager:\\n    \\\"\\\"\\\"A class for managing Kubernetes secrets.\\\"\\\"\\\"\\n\\n    def __init__(self, namespace: str = \\\"langflow\\\"):\\n        \\\"\\\"\\\"Initialize the KubernetesSecretManager class.\\n\\n        Args:\\n            namespace (str): The namespace in which to perform secret operations.\\n        \\\"\\\"\\\"\\n        config.load_kube_config()\\n        self.namespace = namespace\\n\\n        # initialize the Kubernetes API client\\n        self.core_api = client.CoreV1Api()\\n\\n    def create_secret(\\n        self,\\n        name: str,\\n        data: dict,\\n        secret_type: str = \\\"Opaque\\\",  # noqa: S107\\n    ):\\n        \\\"\\\"\\\"Create a new secret in the specified namespace.\\n\\n        Args:\\n            name (str): The name of the secret to create.\\n            data (dict): A dictionary containing the key-value pairs for the secret data.\\n            secret_type (str, optional): The type of secret to create. Defaults to 'Opaque'.\\n\\n        Returns:\\n            V1Secret: The created secret object.\\n        \\\"\\\"\\\"\\n        encoded_data = {k: b64encode(v.encode()).decode() for k, v in data.items()}\\n\\n        secret_metadata = client.V1ObjectMeta(name=name)\\n        secret = client.V1Secret(\\n            api_version=\\\"v1\\\", kind=\\\"Secret\\\", metadata=secret_metadata, type=secret_type, data=encoded_data\\n        )\\n\\n        return self.core_api.create_namespaced_secret(self.namespace, secret)\\n\\n    def upsert_secret(self, secret_name: str, data: dict):\\n        \\\"\\\"\\\"Upsert a secret in the specified namespace.\\n\\n        If the secret doesn't exist, it will be created.\\n        If it exists, it will be updated with new data while preserving existing keys.\\n\\n        :param secret_name: Name of the secret\\n        :param new_data: Dictionary containing new key-value pairs for the secret\\n        :return: Created or updated secret object\\n        \\\"\\\"\\\"\\n        try:\\n            # Try to read the existing secret\\n            existing_secret = self.core_api.read_namespaced_secret(secret_name, self.namespace)\\n\\n            # If secret exists, update it\\n            existing_data = {k: b64decode(v).decode() for k, v in existing_secret.data.items()}\\n            existing_data.update(data)\\n\\n            # Encode all data to base64\\n            encoded_data = {k: b64encode(v.encode()).decode() for k, v in existing_data.items()}\\n\\n            # Update the existing secret\\n            existing_secret.data = encoded_data\\n            return self.core_api.replace_namespaced_secret(secret_name, self.namespace, existing_secret)\\n\\n        except ApiException as e:\\n            if e.status == HTTPStatus.NOT_FOUND:\\n                # Secret doesn't exist, create a new one\\n                return self.create_secret(secret_name, data)\\n            logger.exception(f\\\"Error upserting secret {secret_name}\\\")\\n            raise\\n\\n    def get_secret(self, name: str) -> dict | None:\\n        \\\"\\\"\\\"Read a secret from the specified namespace.\\n\\n        Args:\\n            name (str): The name of the secret to read.\\n\\n        Returns:\\n            V1Secret: The secret object.\\n        \\\"\\\"\\\"\\n        try:\\n            secret = self.core_api.read_namespaced_secret(name, self.namespace)\\n            return {k: b64decode(v).decode() for k, v in secret.data.items()}\\n        except ApiException as e:\\n            if e.status == HTTPStatus.NOT_FOUND:\\n                return None\\n            raise\\n\\n    def update_secret(self, name: str, data: dict):\\n        \\\"\\\"\\\"Update an existing secret in the specified namespace.\\n\\n        Args:\\n            name (str): The name of the secret to update.\\n            data (dict): A dictionary containing the key-value pairs for the updated secret data.\\n\\n        Returns:\\n            V1Secret: The updated secret object.\\n        \\\"\\\"\\\"\\n        # Get the existing secret\\n        secret = self.core_api.read_namespaced_secret(name, self.namespace)\\n        if secret is None:\\n            raise ApiException(status=404, reason=\\\"Not Found\\\", msg=\\\"Secret not found\\\")\\n\\n        # Update the secret data\\n        encoded_data = {k: b64encode(v.encode()).decode() for k, v in data.items()}\\n        secret.data.update(encoded_data)\\n\\n        # Update the secret in Kubernetes\\n        return self.core_api.replace_namespaced_secret(name, self.namespace, secret)\\n\\n    def delete_secret_key(self, name: str, key: str):\\n        \\\"\\\"\\\"Delete a key from the specified secret in the namespace.\\n\\n        Args:\\n            name (str): The name of the secret.\\n            key (str): The key to delete from the secret.\\n\\n        Returns:\\n            V1Secret: The updated secret object.\\n        \\\"\\\"\\\"\\n        # Get the existing secret\\n        secret = self.core_api.read_namespaced_secret(name, self.namespace)\\n        if secret is None:\\n            raise ApiException(status=404, reason=\\\"Not Found\\\", msg=\\\"Secret not found\\\")\\n\\n        # Delete the key from the secret data\\n        if key in secret.data:\\n            del secret.data[key]\\n        else:\\n            raise ApiException(status=404, reason=\\\"Not Found\\\", msg=\\\"Key not found in the secret\\\")\\n\\n        # Update the secret in Kubernetes\\n        return self.core_api.replace_namespaced_secret(name, self.namespace, secret)\\n\\n    def delete_secret(self, name: str):\\n        \\\"\\\"\\\"Delete a secret from the specified namespace.\\n\\n        Args:\\n            name (str): The name of the secret to delete.\\n\\n        Returns:\\n            V1Status: The status object indicating the success or failure of the operation.\\n        \\\"\\\"\\\"\\n        return self.core_api.delete_namespaced_secret(name, self.namespace)\\n\\n\\n# utility function to encode user_id to base64 lower case and numbers only\\n# this is required by kubernetes secret name restrictions\\ndef encode_user_id(user_id: UUID | str) -> str:\\n    # Handle UUID\\n    if isinstance(user_id, UUID):\\n        return f\\\"uuid-{str(user_id).lower()}\\\"[:253]\\n\\n    # Convert string to lowercase\\n    user_id_ = str(user_id).lower()\\n\\n    # If the user_id looks like an email, replace @ and . with allowed characters\\n    if \\\"@\\\" in user_id_ or \\\".\\\" in user_id_:\\n        user_id_ = user_id_.replace(\\\"@\\\", \\\"-at-\\\").replace(\\\".\\\", \\\"-dot-\\\")\\n\\n    # Encode the user_id to base64\\n    # encoded = base64.b64encode(user_id.encode(\\\"utf-8\\\")).decode(\\\"utf-8\\\")\\n\\n    # Replace characters not allowed in Kubernetes names\\n    user_id_ = user_id_.replace(\\\"+\\\", \\\"-\\\").replace(\\\"/\\\", \\\"_\\\").rstrip(\\\"=\\\")\\n\\n    # Ensure the name starts with an alphanumeric character\\n    if not user_id_[0].isalnum():\\n        user_id_ = \\\"a-\\\" + user_id_\\n\\n    # Truncate to 253 characters (Kubernetes name length limit)\\n    user_id_ = user_id_[:253]\\n\\n    if not all(c.isalnum() or c in \\\"-_\\\" for c in user_id_):\\n        msg = f\\\"Invalid user_id: {user_id_}\\\"\\n        raise ValueError(msg)\\n\\n    # Ensure the name ends with an alphanumeric character\\n    while not user_id_[-1].isalnum():\\n        user_id_ = user_id_[:-1]\\n\\n    return user_id_\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/variable/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0231e2e8c0f378d123d5250f538e5e3ea037f01d199bc77bc3fd7edf8e9b778b\",\"content\":\"from __future__ import annotations\\n\\nimport os\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING\\nfrom uuid import UUID\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.authorization.base import ResourceVisibilityScope\\nfrom lfx.services.settings.constants import AGENTIC_VARIABLES\\nfrom lfx.services.variable import VariableNotFoundError\\nfrom sqlmodel import col, select, update\\n\\nfrom langflow.services.auth import utils as auth_utils\\nfrom langflow.services.base import Service\\nfrom langflow.services.database.models.variable.model import Variable, VariableCreate, VariableRead, VariableUpdate\\nfrom langflow.services.variable.base import VariableService\\nfrom langflow.services.variable.constants import CREDENTIAL_TYPE, GENERIC_TYPE\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Sequence\\n\\n    from lfx.services.settings.service import SettingsService\\n    from pydantic import SecretStr\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\ndef has_variable_value(variable: Variable) -> bool:\\n    \\\"\\\"\\\"Return whether a variable has a usable value without exposing credentials.\\\"\\\"\\\"\\n    if not variable.value:\\n        return False\\n    if variable.type != CREDENTIAL_TYPE:\\n        return bool(variable.value.strip())\\n    try:\\n        decrypted_value = auth_utils.decrypt_api_key(variable.value)\\n    except Exception:  # noqa: BLE001\\n        return False\\n    return bool(decrypted_value and decrypted_value.strip())\\n\\n\\nclass DatabaseVariableService(VariableService, Service):\\n    def __init__(self, settings_service: SettingsService):\\n        self.settings_service = settings_service\\n\\n    async def initialize_all_user_variables(self) -> None:\\n        \\\"\\\"\\\"Import environment defaults for existing users independently of their login method.\\n\\n        Page through user IDs and commit each user's imports separately to bound\\n        memory usage and transaction duration during startup.\\n        \\\"\\\"\\\"\\n        settings = self.settings_service.settings\\n        if not settings.store_environment_variables or not any(\\n            os.environ.get(name, \\\"\\\").strip() for name in settings.variables_to_get_from_environment\\n        ):\\n            return\\n\\n        from lfx.base.models.unified_models import get_model_provider_metadata\\n\\n        from langflow.services.database.models.user.model import User\\n        from langflow.services.deps import session_scope\\n\\n        secret_names = {\\n            variable[\\\"variable_key\\\"]\\n            for provider in get_model_provider_metadata().values()\\n            for variable in provider.get(\\\"variables\\\", [])\\n            if variable.get(\\\"is_secret\\\") and variable.get(\\\"variable_key\\\")\\n        }\\n        if not any(\\n            (value := os.environ.get(name, \\\"\\\").strip()) and not (name in secret_names and value.lower() == \\\"dummy\\\")\\n            for name in settings.variables_to_get_from_environment\\n        ):\\n            return\\n\\n        last_user_id: UUID | None = None\\n        failed_users = 0\\n        while True:\\n            async with session_scope() as session:\\n                query = select(User.id).order_by(User.id).limit(100)\\n                if last_user_id is not None:\\n                    query = query.where(User.id > last_user_id)\\n                user_ids = (await session.exec(query)).all()\\n            if not user_ids:\\n                break\\n            for user_id in user_ids:\\n                try:\\n                    async with session_scope() as session:\\n                        await self.initialize_user_variables(user_id, session)\\n                except Exception:  # noqa: BLE001\\n                    failed_users += 1\\n                    await logger.aexception(\\\"Environment variable import failed for user %s; continuing\\\", user_id)\\n            last_user_id = user_ids[-1]\\n        if failed_users:\\n            # Let the startup gate remain incomplete so workers can retry a\\n            # partial master sweep, after all other users have been processed.\\n            msg = f\\\"Environment variable import failed for {failed_users} users\\\"\\n            raise RuntimeError(msg)\\n\\n    async def get_default_field_bindings(\\n        self,\\n        user_id: UUID | str,\\n        session: AsyncSession,\\n    ) -> list[tuple[str, list[str] | None]]:\\n        \\\"\\\"\\\"Read only names and default fields; never materialize variable values.\\\"\\\"\\\"\\n        stmt = (\\n            select(Variable.name, Variable.default_fields)\\n            .where(Variable.user_id == user_id)\\n            .order_by(col(Variable.name), col(Variable.id))\\n        )\\n        return [(name, default_fields) for name, default_fields in (await session.exec(stmt)).all() if name]\\n\\n    async def initialize_user_variables(self, user_id: UUID | str, session: AsyncSession) -> None:\\n        if not self.settings_service.settings.store_environment_variables:\\n            await logger.adebug(\\\"Skipping environment variable storage.\\\")\\n            return\\n\\n        # Import provider metadata to identify placeholder API-key values and\\n        # enforce provider-governance policy for environment imports.\\n        try:\\n            from lfx.base.models.unified_models import get_model_provider_metadata\\n            from lfx.services.model_provider_policy import ModelProviderPolicyPurpose, resolve_model_provider_policy\\n\\n            from langflow.services.database.models.user.model import User\\n\\n            var_to_provider = {}\\n            provider_variables = {}\\n            metadata = get_model_provider_metadata()\\n            # Serialize imports for the same user across PostgreSQL workers so\\n            # concurrent startup/login imports cannot create duplicate rows.\\n            principal = await session.get(User, UUID(str(user_id)), with_for_update=True)\\n            for provider, meta in metadata.items():\\n                for var in meta.get(\\\"variables\\\", []):\\n                    var_key = var.get(\\\"variable_key\\\")\\n                    if var_key:\\n                        var_to_provider[var_key] = provider\\n                        provider_variables[var_key] = var\\n            provider_policy = resolve_model_provider_policy(\\n                user_id=user_id,\\n                providers=metadata,\\n                purpose=ModelProviderPolicyPurpose.CONFIGURE,\\n                attributes={\\\"is_superuser\\\": bool(principal and principal.is_superuser)},\\n            )\\n        except Exception:  # noqa: BLE001\\n            await logger.aexception(\\\"Could not resolve model-provider metadata; skipping environment variable import\\\")\\n            return\\n\\n        for var_name in self.settings_service.settings.variables_to_get_from_environment:\\n            # Check if session is still usable before processing each variable\\n            if not session.is_active:\\n                await logger.awarning(\\n                    \\\"Session is no longer active during variable initialization. \\\"\\n                    \\\"Some environment variables may not have been processed.\\\"\\n                )\\n                break\\n\\n            provider_name = var_to_provider.get(var_name)\\n            if provider_name is not None and not provider_policy.allows(provider_name):\\n                continue\\n\\n            if var_name in os.environ and os.environ[var_name].strip():\\n                value = os.environ[var_name].strip()\\n\\n                # Skip placeholder/test values like \\\"dummy\\\" for API key variables only\\n                # This prevents test environments from overwriting user-configured model provider keys\\n                var_info = provider_variables.get(var_name, {})\\n                is_provider_variable = bool(var_info)\\n                is_secret_variable = var_info.get(\\\"is_secret\\\", False)\\n\\n                if is_provider_variable and is_secret_variable and value.lower() == \\\"dummy\\\":\\n                    await logger.adebug(\\n                        f\\\"Skipping API key variable {var_name} with placeholder value 'dummy' \\\"\\n                        \\\"to preserve user configuration\\\"\\n                    )\\n                    continue\\n\\n                query = select(Variable).where(Variable.user_id == user_id, Variable.name == var_name)\\n                try:\\n                    existing = (await session.exec(query)).first()\\n                except Exception as e:  # noqa: BLE001\\n                    await logger.aexception(f\\\"Error querying {var_name} variable: {e!s}\\\")\\n                    # If session got rolled back during query, stop processing\\n                    if not session.is_active:\\n                        await logger.awarning(\\n                            f\\\"Session rolled back during {var_name} query. Stopping variable initialization.\\\"\\n                        )\\n                        break\\n                    continue\\n\\n                try:\\n                    if existing:\\n                        if existing.type != CREDENTIAL_TYPE or existing.is_environment_managed is False:\\n                            continue\\n                        if existing.is_environment_managed is None:\\n                            await self._adopt_environment_variable(existing, value, session)\\n                        elif existing.created_at is not None and existing.updated_at == existing.created_at:\\n                            await self._update_environment_variable(existing, value, session)\\n                        else:\\n                            # Older workers cannot write the origin flag. A\\n                            # changed timestamp still protects their user edits.\\n                            await logger.adebug(\\\"Preserving variable %s modified by an older worker\\\", var_name)\\n                    else:\\n                        variable = await self.create_variable(\\n                            user_id=user_id,\\n                            name=var_name,\\n                            value=value,\\n                            # Model Providers resolve these at runtime; Apply To Fields is user-owned.\\n                            default_fields=[],\\n                            type_=CREDENTIAL_TYPE,\\n                            session=session,\\n                        )\\n                        variable.is_environment_managed = True\\n                        # Keep the timestamp marker to detect edits by older\\n                        # workers during a rolling upgrade.\\n                        variable.updated_at = variable.created_at\\n                        session.add(variable)\\n                        await session.flush()\\n                    await logger.adebug(f\\\"Processed {var_name} variable from environment.\\\")\\n                except Exception as e:  # noqa: BLE001\\n                    await logger.aexception(f\\\"Error processing {var_name} variable: {e!s}\\\")\\n                    # If session got rolled back due to error, stop processing\\n                    if not session.is_active:\\n                        await logger.awarning(\\n                            f\\\"Session rolled back after error processing {var_name}. Stopping variable initialization.\\\"\\n                        )\\n                        break\\n\\n    async def _adopt_environment_variable(self, variable: Variable, value: str, session: AsyncSession) -> None:\\n        \\\"\\\"\\\"Adopt an unknown legacy credential only while it matches the environment.\\\"\\\"\\\"\\n        if auth_utils.decrypt_api_key(variable.value) != value:\\n            return\\n        created_at = variable.created_at or datetime.now(timezone.utc)\\n        statement = (\\n            update(Variable)\\n            .where(\\n                Variable.id == variable.id,\\n                Variable.user_id == variable.user_id,\\n                Variable.name == variable.name,\\n                Variable.type == CREDENTIAL_TYPE,\\n                col(Variable.is_environment_managed).is_(None),\\n                Variable.updated_at == variable.updated_at,\\n                Variable.value == variable.value,\\n            )\\n            .values(is_environment_managed=True, created_at=created_at, updated_at=created_at)\\n            .execution_options(synchronize_session=False)\\n        )\\n        await session.exec(statement)\\n        await session.refresh(variable)\\n\\n    async def _update_environment_variable(self, variable: Variable, value: str, session: AsyncSession) -> None:\\n        \\\"\\\"\\\"Rotate a managed credential only if no concurrent edit changed the row.\\\"\\\"\\\"\\n        if auth_utils.decrypt_api_key(variable.value) == value:\\n            return\\n        statement = (\\n            update(Variable)\\n            .where(\\n                Variable.id == variable.id,\\n                Variable.user_id == variable.user_id,\\n                Variable.name == variable.name,\\n                Variable.type == CREDENTIAL_TYPE,\\n                col(Variable.is_environment_managed).is_(True),\\n                Variable.created_at == variable.created_at,\\n                Variable.updated_at == variable.updated_at,\\n                Variable.value == variable.value,\\n            )\\n            .values(value=auth_utils.encrypt_api_key(value, settings_service=self.settings_service))\\n            .execution_options(synchronize_session=False)\\n        )\\n        await session.exec(statement)\\n        await session.refresh(variable)\\n\\n    async def get_variable_object(\\n        self,\\n        user_id: UUID | str,\\n        name: str,\\n        session: AsyncSession,\\n    ) -> Variable:\\n        # we get the credential from the database\\n        stmt = select(Variable).where(Variable.user_id == user_id, Variable.name == name)\\n        variable = (await session.exec(stmt)).first()\\n\\n        if not variable or not variable.value:\\n            msg = f\\\"{name} variable not found.\\\"\\n            raise VariableNotFoundError(msg)\\n\\n        return variable\\n\\n    async def get_variable(\\n        self,\\n        user_id: UUID | str,\\n        name: str,\\n        field: str,\\n        session: AsyncSession,\\n    ) -> str | SecretStr:\\n        # we get the credential from the database\\n        # credential = session.query(Variable).filter(Variable.user_id == user_id, Variable.name == name).first()\\n        try:\\n            variable = await self.get_variable_object(user_id, name, session)\\n        except VariableNotFoundError as owned_lookup_error:\\n            # Runtime resolution may use an explicitly shared variable, but it\\n            # must never broaden administrative get/update/delete lookups. An\\n            # owned variable wins on name collisions; otherwise require one\\n            # unambiguous READ-visible row from the authorization plugin.\\n            from langflow.services.deps import get_authorization_service\\n\\n            authz = get_authorization_service()\\n            if not await authz.is_enabled() or not await authz.supports_cross_user_fetch():\\n                raise\\n            get_visibility = getattr(authz, \\\"get_resource_visibility\\\", None)\\n            if get_visibility is None:\\n                # Compatibility for duck-typed authorization services that\\n                # predate ResourceVisibilityScope.\\n                visible_ids = await authz.list_visible_resource_ids(\\n                    user_id=UUID(str(user_id)),\\n                    resource_type=\\\"variable\\\",\\n                    domain=\\\"*\\\",\\n                    act=\\\"read\\\",\\n                )\\n                visibility = None if visible_ids is None else ResourceVisibilityScope(resource_ids=tuple(visible_ids))\\n            else:\\n                visibility = await get_visibility(\\n                    user_id=UUID(str(user_id)),\\n                    resource_type=\\\"variable\\\",\\n                    domain=\\\"*\\\",\\n                    act=\\\"read\\\",\\n                )\\n            if visibility is None or not (visibility.all_resources or visibility.resource_ids):\\n                raise\\n\\n            shared_clauses = [\\n                Variable.name == name,\\n                Variable.user_id != user_id,\\n            ]\\n            if not visibility.all_resources:\\n                shared_clauses.append(col(Variable.id).in_(visibility.resource_ids))\\n            shared_variables = list((await session.exec(select(Variable).where(*shared_clauses))).all())\\n            if not shared_variables:\\n                raise\\n            if len(shared_variables) > 1:\\n                msg = f\\\"Multiple shared variables named '{name}' are visible; use an owned variable with that name.\\\"\\n                raise ValueError(msg) from owned_lookup_error\\n            variable = shared_variables[0]\\n\\n        if variable.type == CREDENTIAL_TYPE and field == \\\"session_id\\\":\\n            msg = (\\n                f\\\"variable {name} of type 'Credential' cannot be used in a Session ID field \\\"\\n                \\\"because its purpose is to prevent the exposure of values.\\\"\\n            )\\n            raise TypeError(msg)\\n\\n        # Only decrypt CREDENTIAL type variables; GENERIC variables are stored as plain text.\\n        # CREDENTIAL values are wrapped in pydantic.SecretStr so that any consumer that echoes\\n        # the value through a stringification path (Message.text, status, traces, logs) gets\\n        # \\\"**********\\\" instead of the raw secret. Consumers that genuinely need the raw value\\n        # call .get_secret_value() at the boundary (e.g. provider client construction).\\n        if variable.type == CREDENTIAL_TYPE:\\n            from pydantic import SecretStr\\n\\n            decrypted = auth_utils.decrypt_api_key(variable.value)\\n            if not decrypted:\\n                msg = (\\n                    f\\\"Could not decrypt credential variable '{name}'. The stored value cannot be \\\"\\n                    \\\"decrypted with the current LANGFLOW_SECRET_KEY \u2014 it may have been encrypted \\\"\\n                    \\\"with a different key.\\\"\\n                )\\n                raise ValueError(msg)\\n            return SecretStr(decrypted)\\n        # GENERIC type - return as-is\\n        return variable.value\\n\\n    async def get_all(\\n        self,\\n        user_id: UUID | str,\\n        session: AsyncSession,\\n        *,\\n        visibility: ResourceVisibilityScope | None = None,\\n        include_empty_names: set[str] | None = None,\\n    ) -> list[VariableRead]:\\n        stmt = select(Variable).order_by(col(Variable.name), col(Variable.id))\\n        if visibility is None:\\n            stmt = stmt.where(Variable.user_id == user_id)\\n        else:\\n            from langflow.services.authorization.listing import restrict_to_owned_or_visible_scope\\n\\n            # Variable has no canonical workspace/project columns, so\\n            # domain-only grants intentionally remain owner-scoped.\\n            stmt = restrict_to_owned_or_visible_scope(\\n                stmt,\\n                id_column=Variable.id,\\n                owner_clause=Variable.user_id == user_id,\\n                visibility=visibility,\\n            )\\n        variables = list((await session.exec(stmt)).all())\\n        include_empty_names = include_empty_names or set()\\n        variables_read = []\\n        for variable in variables:\\n            is_owner = str(variable.user_id) == str(user_id)\\n            value = None\\n            if variable.type == GENERIC_TYPE and is_owner:\\n                if not variable.value and variable.name not in include_empty_names:\\n                    if variable.name in AGENTIC_VARIABLES:\\n                        await logger.adebug(\\n                            \\\"Agentic placeholder variable '%s' has no stored value \u2014 skipping.\\\", variable.name\\n                        )\\n                    else:\\n                        await logger.awarning(\\\"Variable '%s' has no stored value \u2014 skipping.\\\", variable.name)\\n                    continue\\n                if variable.value:\\n                    # Security defense-in-depth: a GENERIC variable is stored as plain text, so its\\n                    # value must never be a Fernet token. If it is (e.g. a CREDENTIAL row that was\\n                    # relabeled GENERIC), do NOT decrypt-and-return it \u2014 that would leak the secret.\\n                    if isinstance(variable.value, str) and variable.value.startswith(\\\"gAAAAA\\\"):\\n                        await logger.awarning(\\n                            \\\"Skipping variable '%s': a GENERIC variable holds ciphertext \\\"\\n                            \\\"(likely a CREDENTIAL row relabeled GENERIC); not decrypting or returning it.\\\",\\n                            variable.name,\\n                        )\\n                        continue\\n                    value = auth_utils.decrypt_api_key(variable.value)\\n                    if not value:\\n                        await logger.awarning(\\n                            \\\"Variable '%s' could not be decrypted \u2014 likely encrypted with a different \\\"\\n                            \\\"LANGFLOW_SECRET_KEY. Skipping.\\\",\\n                            variable.name,\\n                        )\\n                        continue\\n                else:\\n                    # Optional settings use an empty value as a meaningful reset\\n                    # while retaining the row UUID.\\n                    value = \\\"\\\"\\n\\n            # Model validate will set value to None if credential type\\n            variable_read = VariableRead.model_validate(variable, from_attributes=True)\\n            variable_read.has_value = has_variable_value(variable)\\n            variable_read.is_owner = is_owner\\n            # Deliberately conservative: resource owners can manage shares.\\n            # Enterprise may authorize additional administrators server-side,\\n            # but the list UI must not show a re-share control to recipients.\\n            variable_read.can_manage_shares = is_owner\\n            # Shared values are usable only inside runtime variable resolution;\\n            # API list responses expose metadata but never plaintext values.\\n            if variable.type == GENERIC_TYPE and is_owner:\\n                variable_read.value = value\\n            elif not is_owner:\\n                variable_read.value = None\\n\\n            variables_read.append(variable_read)\\n        return variables_read\\n\\n    async def get_all_decrypted_variables(\\n        self,\\n        user_id: UUID | str,\\n        session: AsyncSession,\\n    ) -> dict[str, str]:\\n        \\\"\\\"\\\"Get all variables for a user with decrypted values.\\n\\n        Args:\\n            user_id: The user ID to get variables for\\n            session: Database session\\n\\n        Returns:\\n            Dictionary mapping variable names to decrypted values\\n        \\\"\\\"\\\"\\n        # Convert string to UUID if needed for SQLAlchemy query\\n        user_id_uuid = UUID(user_id) if isinstance(user_id, str) else user_id\\n        stmt = select(Variable).where(Variable.user_id == user_id_uuid)\\n        variables = (await session.exec(stmt)).all()\\n\\n        result = {}\\n        for var in variables:\\n            if var.name and var.value:\\n                try:\\n                    decrypted_value = auth_utils.decrypt_api_key(var.value)\\n                except Exception as e:  # noqa: BLE001\\n                    await logger.awarning(f\\\"Decryption failed for variable '{var.name}': {e}. Skipping\\\")\\n                    continue\\n\\n                if not decrypted_value:\\n                    await logger.awarning(f\\\"Decryption returned empty for variable '{var.name}'. Skipping\\\")\\n                    continue\\n\\n                result[var.name] = decrypted_value\\n\\n        return result\\n\\n    async def get_variable_by_id(\\n        self,\\n        user_id: UUID | str,\\n        variable_id: UUID | str,\\n        session: AsyncSession,\\n    ) -> Variable:\\n        query = select(Variable).where(Variable.id == variable_id, Variable.user_id == user_id)\\n        variable = (await session.exec(query)).first()\\n        if not variable:\\n            msg = f\\\"{variable_id} variable not found.\\\"\\n            raise ValueError(msg)\\n        return variable\\n\\n    async def list_variables(self, user_id: UUID | str, session: AsyncSession) -> list[str | None]:\\n        variables = await self.get_all(user_id=user_id, session=session)\\n        return [variable.name for variable in variables if variable]\\n\\n    async def get_available_variable_names(\\n        self,\\n        user_id: UUID | str,\\n        names: set[str],\\n        session: AsyncSession,\\n    ) -> set[str]:\\n        \\\"\\\"\\\"Return requested variable names that have a usable owned value.\\n\\n        Args:\\n            user_id: The user whose variables should be checked.\\n            names: Variable names to check.\\n            session: Database session.\\n\\n        Returns:\\n            Names whose stored values are non-empty and, for credentials, decryptable.\\n        \\\"\\\"\\\"\\n        if not names:\\n            return set()\\n\\n        stmt = select(Variable).where(\\n            Variable.user_id == user_id,\\n            col(Variable.name).in_(names),\\n        )\\n        variables = (await session.exec(stmt)).all()\\n        return {variable.name for variable in variables if has_variable_value(variable)}\\n\\n    async def update_variable(\\n        self,\\n        user_id: UUID | str,\\n        name: str,\\n        value: str,\\n        session: AsyncSession,\\n    ):\\n        stmt = select(Variable).where(Variable.user_id == user_id, Variable.name == name)\\n        variable = (await session.exec(stmt)).first()\\n        if not variable:\\n            msg = f\\\"{name} variable not found.\\\"\\n            raise ValueError(msg)\\n\\n        # Validate that GENERIC variables don't start with Fernet signature\\n        if variable.type == GENERIC_TYPE and value.startswith(\\\"gAAAAA\\\"):\\n            msg = (\\n                f\\\"Generic variable '{name}' cannot start with 'gAAAAA' as this is reserved \\\"\\n                \\\"for encrypted values. Please use a different value.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n        # Only encrypt CREDENTIAL_TYPE variables\\n        if variable.type == CREDENTIAL_TYPE:\\n            variable.value = auth_utils.encrypt_api_key(value, settings_service=self.settings_service)\\n        else:\\n            variable.value = value\\n        variable.updated_at = datetime.now(timezone.utc)\\n        variable.is_environment_managed = False\\n        session.add(variable)\\n        await session.flush()\\n        await session.refresh(variable)\\n        return variable\\n\\n    async def update_variable_fields(\\n        self,\\n        user_id: UUID | str,\\n        variable_id: UUID | str,\\n        variable: VariableUpdate,\\n        session: AsyncSession,\\n    ):\\n        query = select(Variable).where(Variable.id == variable_id, Variable.user_id == user_id)\\n        db_variable = (await session.exec(query)).one()\\n\\n        # Security: prevent a CREDENTIAL -> GENERIC type-confusion that would expose the\\n        # decrypted secret. Credential values are stored as Fernet ciphertext (\\\"gAAAAA...\\\").\\n        # Relabeling the row GENERIC *without* supplying a fresh value would leave that\\n        # ciphertext in place; get_all() then decrypts GENERIC values and returns the\\n        # plaintext (e.g. the server's shared provider keys). Reject that transition.\\n        resulting_type = variable.type if variable.type is not None else db_variable.type\\n        if (\\n            resulting_type == GENERIC_TYPE\\n            and variable.value is None\\n            and isinstance(db_variable.value, str)\\n            and db_variable.value.startswith(\\\"gAAAAA\\\")\\n        ):\\n            msg = \\\"Cannot change a credential variable to a generic variable without providing a new value.\\\"\\n            raise ValueError(msg)\\n\\n        # Handle value encryption based on variable type (consistent with update_variable and create_variable)\\n        if variable.value is not None:\\n            variable_type = variable.type if variable.type is not None else db_variable.type\\n\\n            # Validate that GENERIC variables don't start with Fernet signature\\n            if variable_type == GENERIC_TYPE and variable.value.startswith(\\\"gAAAAA\\\"):\\n                msg = (\\n                    f\\\"Generic variable '{db_variable.name}' cannot start with 'gAAAAA' as this is reserved \\\"\\n                    \\\"for encrypted values. Please use a different value.\\\"\\n                )\\n                raise ValueError(msg)\\n\\n            # Only encrypt CREDENTIAL_TYPE variables (consistent with update_variable and create_variable)\\n            if variable_type == CREDENTIAL_TYPE:\\n                variable.value = auth_utils.encrypt_api_key(variable.value, settings_service=self.settings_service)\\n            # GENERIC_TYPE variables are stored as plain text\\n\\n        claims_value = (\\n            variable.value is not None\\n            or (variable.name is not None and variable.name != db_variable.name)\\n            or (variable.type is not None and variable.type != db_variable.type)\\n        )\\n        if claims_value:\\n            db_variable.is_environment_managed = False\\n        # Apply-to-fields edits must retain the marker on managed credentials.\\n        if claims_value or db_variable.is_environment_managed is not True:\\n            db_variable.updated_at = datetime.now(timezone.utc)\\n        variable_data = variable.model_dump(exclude_unset=True)\\n        for key, value in variable_data.items():\\n            setattr(db_variable, key, value)\\n\\n        session.add(db_variable)\\n        await session.flush()\\n        await session.refresh(db_variable)\\n        return db_variable\\n\\n    async def delete_variable(\\n        self,\\n        user_id: UUID | str,\\n        name: str,\\n        session: AsyncSession,\\n    ) -> None:\\n        stmt = select(Variable).where(Variable.user_id == user_id).where(Variable.name == name)\\n        variable = (await session.exec(stmt)).first()\\n        if not variable:\\n            msg = f\\\"{name} variable not found.\\\"\\n            raise ValueError(msg)\\n        await session.delete(variable)\\n\\n    async def delete_variable_by_id(self, user_id: UUID | str, variable_id: UUID, session: AsyncSession) -> None:\\n        stmt = select(Variable).where(Variable.user_id == user_id, Variable.id == variable_id)\\n        variable = (await session.exec(stmt)).first()\\n        if not variable:\\n            msg = f\\\"{variable_id} variable not found.\\\"\\n            raise ValueError(msg)\\n        await session.delete(variable)\\n\\n    async def create_variable(\\n        self,\\n        user_id: UUID | str,\\n        name: str,\\n        value: str,\\n        *,\\n        default_fields: Sequence[str] = (),\\n        type_: str = CREDENTIAL_TYPE,\\n        session: AsyncSession,\\n    ):\\n        # Validate that GENERIC variables don't start with Fernet signature\\n        if type_ == GENERIC_TYPE and value.startswith(\\\"gAAAAA\\\"):\\n            msg = (\\n                f\\\"Generic variable '{name}' cannot start with 'gAAAAA' as this is reserved \\\"\\n                \\\"for encrypted values. Please use a different value.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n        # Only encrypt CREDENTIAL_TYPE variables\\n        encrypted_value = auth_utils.encrypt_api_key(value) if type_ == CREDENTIAL_TYPE else value\\n        variable_base = VariableCreate(\\n            name=name,\\n            type=type_,\\n            value=encrypted_value,\\n            default_fields=list(default_fields),\\n        )\\n        variable = Variable.model_validate(\\n            variable_base, from_attributes=True, update={\\\"user_id\\\": user_id, \\\"is_environment_managed\\\": False}\\n        )\\n        session.add(variable)\\n        await session.flush()\\n        await session.refresh(variable)\\n        return variable\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/warm_registry/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"080323de0862d4a8555ad72e860b2439c33863254596b9ca41ef620889920711\",\"content\":\"\\\"\\\"\\\"Opt-in, process-local in-memory flow-graph registry.\\n\\nHolds bounded structural ``Graph`` templates for eligible v1/v2 sync runs. Every\\nrequest still performs its normal authentication/authorization and revision checks;\\nstream, background, public, and request-mutated runs stay cold. Each machine keeps\\nresident entries current against the shared ``flow`` table without Redis.\\n\\\"\\\"\\\"\\n\\nfrom langflow.services.warm_registry.service import WarmGraphRegistry, get_warm_registry\\n\\n__all__ = [\\\"WarmGraphRegistry\\\", \\\"get_warm_registry\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/warm_registry/reconcile.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e4dcd49d83a48a50c80ded9819321de9733d07b1302d9fe8c6343d0078503c86\",\"content\":\"\\\"\\\"\\\"Reconcile the warm registry against the shared ``flow`` table (no Redis).\\n\\nThe execution DB is the single source of truth and the only coordination channel:\\neach machine independently diffs its registry against it. There is no cross-machine\\nmessaging: creates add rows, edits advance revisions, and deletes remove rows. Every\\nmachine's next reconcile pass converges.\\n\\nRules:\\n- change-marker per flow = ``updated_at`` isoformat; a differing version rebuilds.\\n- registry key absent from the manifest -> evict (covers hard-delete).\\n- **fail-safe:** only reconcile when the manifest query SUCCEEDS. A DB error must\\n  never mass-evict the registry, so on failure we keep the current state.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport tempfile\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING\\nfrom uuid import UUID\\n\\nfrom filelock import FileLock\\nfrom filelock import Timeout as FileLockTimeout\\nfrom lfx.log.logger import logger\\nfrom sqlmodel import col, select\\n\\nfrom langflow.services.database.models.flow.model import Flow, FlowRead\\nfrom langflow.services.deps import get_settings_service, session_scope\\nfrom langflow.services.warm_registry.service import (\\n    FlowStoreUnavailableError,\\n    WarmRegistryCapacityError,\\n    flow_version,\\n    get_warm_registry,\\n)\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.graph.base import Graph\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\n_WARM_ALL_LOCK_PATH = Path(tempfile.gettempdir()) / \\\"langflow_warm_registry.lock\\\"\\n_WARM_ALL_LOCK_POLL_SECONDS = 0.5\\n\\n\\nasync def _fetch_flow(session: AsyncSession, flow_id: str, *, user_id: object | None = None) -> Flow | None:\\n    \\\"\\\"\\\"Fetch by canonical UUID, or by endpoint name within one owner namespace.\\\"\\\"\\\"\\n    try:\\n        uid: UUID | None = UUID(flow_id)\\n    except ValueError:\\n        uid = None\\n    if uid is not None:\\n        flow = (await session.exec(select(Flow).where(Flow.id == uid))).first()\\n        if flow is not None:\\n            return flow\\n    if user_id is None:\\n        return None\\n    try:\\n        owner_id = user_id if isinstance(user_id, UUID) else UUID(str(user_id))\\n    except ValueError:\\n        return None\\n    return (await session.exec(select(Flow).where(Flow.endpoint_name == flow_id, Flow.user_id == owner_id))).first()\\n\\n\\nasync def warm_one(flow_id: str, *, user_id: object | None = None) -> tuple[Graph, str] | None:\\n    \\\"\\\"\\\"Lazy-warm a single flow into the registry on a cache miss.\\n\\n    Returns the ``(template, version)`` entry, or ``None`` when the flow genuinely\\n    does not exist / has no data (caller maps that to a 404). A DB *availability*\\n    failure instead raises :class:`FlowStoreUnavailableError` so the caller can answer\\n    503 (retryable) rather than a permanent-looking 404 \u2014 important on a cold worker\\n    during pool exhaustion. Registered under the canonical UUID. Endpoint-name lookup\\n    requires ``user_id`` and is owner-scoped; share-aware cross-owner resolution must\\n    use the authorization-aware DB path instead of this local cache.\\n    \\\"\\\"\\\"\\n    reg = get_warm_registry()\\n    try:\\n        async with session_scope() as session:\\n            flow = await _fetch_flow(session, flow_id, user_id=user_id)\\n            snapshot = FlowRead.model_validate(flow, from_attributes=True) if flow is not None else None\\n    except Exception as exc:\\n        # A transient store failure must be distinguishable from not-found: re-raise\\n        # as a typed availability error (host -> 503) instead of collapsing to None.\\n        logger.exception(\\\"warm_registry: warm_one query failed for %s\\\", flow_id)\\n        raise FlowStoreUnavailableError(flow_id) from exc\\n    if snapshot is None or not snapshot.data:\\n        return None\\n    if snapshot.updated_at is None:\\n        # A nullable legacy timestamp cannot provide a monotonic cache revision.\\n        # Keep this flow on the cold path until a real writer advances it.\\n        return None\\n    canonical = str(snapshot.id)\\n    try:\\n        await reg.add(\\n            canonical,\\n            snapshot.name,\\n            snapshot.data,\\n            flow_version(snapshot.updated_at),\\n            flow=snapshot,\\n        )\\n    except WarmRegistryCapacityError:\\n        # Capacity is a cache decision, never an execution error. The caller\\n        # continues through its established cold build path.\\n        logger.info(\\\"warm_registry: flow %s is outside configured cache bounds\\\", canonical)\\n        return None\\n    return reg.get(canonical)\\n\\n\\nasync def _warm_all_unlocked() -> None:\\n    \\\"\\\"\\\"Build this worker's registry while the machine-local startup lock is held.\\\"\\\"\\\"\\n    reg = get_warm_registry()\\n    preload_limit = get_settings_service().settings.warm_registry_preload_limit\\n    limit = min(preload_limit, reg.remaining_entries())\\n    if limit <= 0:\\n        logger.info(\\\"warm_registry: eager preload disabled; flows will warm lazily\\\")\\n        return\\n\\n    async with session_scope() as session:\\n        flow_ids = (\\n            await session.exec(\\n                select(Flow.id)\\n                .where(col(Flow.updated_at).is_not(None))\\n                .order_by(col(Flow.updated_at).desc())\\n                .limit(limit)\\n            )\\n        ).all()\\n    warmed = 0\\n    # Fetch one full payload at a time. This keeps automatic preload bounded by\\n    # both ``preload_limit`` and the registry byte limits instead of materializing\\n    # every tenant row in one result set.\\n    for flow_id in flow_ids:\\n        try:\\n            async with session_scope() as session:\\n                row = (await session.exec(select(Flow).where(Flow.id == flow_id))).first()\\n            if row is None:\\n                continue\\n            flow = FlowRead.model_validate(row, from_attributes=True)\\n            if not flow.data or flow.updated_at is None:\\n                continue\\n            # Deliberately sequential: Graph.from_payload is CPU-heavy and an\\n            # unbounded gather here would merely move the startup spike in-process.\\n            await reg.add(\\n                str(flow.id),\\n                flow.name,\\n                flow.data,\\n                flow_version(flow.updated_at),\\n                flow=flow,\\n            )\\n            warmed += 1\\n        except WarmRegistryCapacityError:\\n            # Capacity is a cache decision, never an execution error (see class docstring).\\n            # Log at INFO without a stack trace \u2014 matches the resolver-side handling above \u2014\\n            # so an operator holding oversized flows doesn't get a traceback per flow.\\n            logger.info(\\\"warm_registry: flow %s is outside configured cache bounds during warm_all\\\", flow_id)\\n        except Exception:  # noqa: BLE001 \u2014 one bad flow must not abort warming the rest\\n            logger.exception(\\\"warm_registry: failed to build flow %s during warm_all\\\", flow_id)\\n    logger.info(\\\"warm_registry: warmed %d flow(s) at startup\\\", warmed)\\n\\n\\nasync def warm_all() -> None:\\n    \\\"\\\"\\\"Preload a configured bounded flow set, serializing work across local workers.\\n\\n    The default preload limit is zero, so shared deployments warm lazily after an\\n    authorized request. Dedicated execution workers may opt into bounded preload.\\n    Registries are process-local; the machine-local lock prevents workers from\\n    preloading simultaneously. Lock acquisition runs in a thread so a waiting worker\\n    keeps its event loop responsive; release is guaranteed on every error path.\\n    \\\"\\\"\\\"\\n    # ``to_thread`` may acquire and release on different executor threads, so the\\n    # lock context must be shared rather than FileLock's thread-local default.\\n    lock = FileLock(_WARM_ALL_LOCK_PATH, thread_local=False)\\n    logger.info(\\\"warm_registry: waiting for machine-local startup warm lock\\\")\\n    while True:\\n        try:\\n            # A finite poll both avoids FileLock's same-process deadlock guard in\\n            # tests and gives cancellation regular checkpoints during a long warm.\\n            await asyncio.to_thread(lock.acquire, timeout=_WARM_ALL_LOCK_POLL_SECONDS)\\n            break\\n        except FileLockTimeout:\\n            continue\\n    try:\\n        await _warm_all_unlocked()\\n    finally:\\n        await asyncio.to_thread(lock.release)\\n\\n\\nasync def reconcile_once() -> None:\\n    \\\"\\\"\\\"One reconcile pass: add new/changed, evict deleted. Fail-safe on DB error.\\\"\\\"\\\"\\n    reg = get_warm_registry()\\n    active_ids = reg.active_ids()\\n    active_uuids: list[UUID] = []\\n    for sid in active_ids:\\n        try:\\n            active_uuids.append(UUID(sid))\\n        except ValueError:\\n            # Registry runtime keys are canonical UUIDs. A malformed legacy/test\\n            # key has no matching DB row and is treated as deleted below.\\n            continue\\n\\n    preload_limit = get_settings_service().settings.warm_registry_preload_limit\\n    preload_slots = max(0, min(reg.remaining_entries(), preload_limit - len(reg)))\\n\\n    # Query only resident entries (bounded by max_entries) plus a bounded newest\\n    # set when explicit preload has spare slots. A tenant-wide manifest every 20s\\n    # would make shared-cluster DB work grow without bound.\\n    try:\\n        async with session_scope() as session:\\n            manifest = []\\n            if active_uuids:\\n                active_stmt = select(Flow.id, Flow.updated_at).where(col(Flow.id).in_(active_uuids))\\n                manifest.extend((await session.exec(active_stmt)).all())\\n            if preload_slots:\\n                # Failed revisions are filtered after their timestamp is read so\\n                # a later revision of the same flow remains eligible. Overfetch by\\n                # the bounded tombstone count to keep rejected newest rows from\\n                # permanently starving older valid candidates.\\n                preload_scan_limit = preload_slots + reg.rejection_count()\\n                preload_stmt = (\\n                    select(Flow.id, Flow.updated_at)\\n                    .where(col(Flow.updated_at).is_not(None))\\n                    .order_by(col(Flow.updated_at).desc())\\n                    .limit(preload_scan_limit)\\n                )\\n                if active_uuids:\\n                    preload_stmt = preload_stmt.where(col(Flow.id).not_in(active_uuids))\\n                manifest.extend((await session.exec(preload_stmt)).all())\\n    except Exception:  # noqa: BLE001\\n        # Critical safety rail: never run the evict step on a failed manifest query,\\n        # or an empty/partial result would wipe the whole registry. Keep current\\n        # state and let the next pass retry.\\n        logger.exception(\\\"warm_registry: manifest query failed; keeping current registry\\\")\\n        return\\n\\n    # Diff the manifest against the cache: NEW (absent), CHANGED (version differs).\\n    manifest_ids: set[str] = set()\\n    new_ids: list[UUID] = []\\n    changed_ids: list[UUID] = []\\n    unversioned_ids: list[str] = []\\n    for flow_id, updated_at in manifest:\\n        sid = str(flow_id)\\n        manifest_ids.add(sid)\\n        cached = reg.version_of(sid)\\n        if updated_at is None:\\n            if cached is not None:\\n                unversioned_ids.append(sid)\\n            continue\\n        version = flow_version(updated_at)\\n        if cached is None:\\n            # A failed/oversized revision is already known to be unsuitable.\\n            # Skip it before selecting the full ``data`` row so the tombstone\\n            # backs off database transfer as well as graph parsing.\\n            if reg.rejects_version(sid, version):\\n                continue\\n            if len(new_ids) < preload_slots:\\n                new_ids.append(flow_id)\\n        elif cached != version:\\n            changed_ids.append(flow_id)\\n\\n    # Deletion propagation: cached minus live = upstream-deleted -> evict.\\n    evicted = active_ids - manifest_ids\\n    for sid in evicted:\\n        await reg.evict(sid)\\n        logger.info(\\\"warm_registry: evicted deleted flow %s\\\", sid)\\n    for sid in unversioned_ids:\\n        await reg.evict(sid)\\n        logger.info(\\\"warm_registry: evicted unversioned flow %s\\\", sid)\\n\\n    # Fetch ``data`` only for new+changed flows and (re)build them.\\n    to_build = new_ids + changed_ids\\n    if to_build:\\n        for flow_id in to_build:\\n            try:\\n                async with session_scope() as session:\\n                    row = (await session.exec(select(Flow).where(Flow.id == flow_id))).first()\\n                if row is None:\\n                    continue\\n                flow = FlowRead.model_validate(row, from_attributes=True)\\n            except Exception:  # noqa: BLE001\\n                logger.exception(\\\"warm_registry: change fetch failed for %s; will retry\\\", flow_id)\\n                continue\\n            sid = str(flow.id)\\n            if not flow.data or flow.updated_at is None:\\n                # A (re)deployed flow whose executable data is now empty is not runnable.\\n                # Tombstone a versioned empty row as well as evicting an older\\n                # template. Otherwise a newest empty flow consumes the same bounded\\n                # preload slot on every pass and starves older runnable candidates.\\n                if flow.updated_at is None:\\n                    await reg.evict(sid)\\n                else:\\n                    await reg.reject_revision(\\n                        sid,\\n                        flow_version(flow.updated_at),\\n                        name=flow.name,\\n                        flow=flow,\\n                    )\\n                continue\\n            try:\\n                await reg.add(\\n                    sid,\\n                    flow.name,\\n                    flow.data,\\n                    flow_version(flow.updated_at),\\n                    flow=flow,\\n                )\\n                verb = \\\"added new\\\" if flow.id in new_ids else \\\"rebuilt changed\\\"\\n                logger.info(\\\"warm_registry: %s flow %s (%r)\\\", verb, flow.id, flow.name)\\n            except WarmRegistryCapacityError:\\n                # Capacity is a cache decision, never an execution error (see class docstring).\\n                # INFO, no stack trace \u2014 matches the resolver-side handling at the top of this\\n                # module \u2014 so an oversized flow doesn't emit a traceback every reconcile pass.\\n                logger.info(\\\"warm_registry: flow %s is outside configured cache bounds\\\", flow.id)\\n            except Exception:  # noqa: BLE001\\n                logger.exception(\\\"warm_registry: rebuild failed for %s\\\", flow.id)\\n\\n    if new_ids or changed_ids or evicted or unversioned_ids:\\n        logger.info(\\n            \\\"warm_registry: reconcile pass \u2014 +%d new, ~%d changed, -%d deleted (registry now %d)\\\",\\n            len(new_ids),\\n            len(changed_ids),\\n            len(evicted) + len(unversioned_ids),\\n            len(reg),\\n        )\\n    else:\\n        logger.debug(\\\"warm_registry: reconcile pass \u2014 no changes (registry %d)\\\", len(reg))\\n\\n\\nasync def reconcile_loop(interval: float | None = None) -> None:\\n    \\\"\\\"\\\"Run :func:`reconcile_once` forever every ``interval`` seconds.\\n\\n    ``interval`` defaults to ``settings.warm_reconcile_interval``\\n    (env ``LANGFLOW_WARM_RECONCILE_INTERVAL``, 20s).\\n    \\\"\\\"\\\"\\n    if interval is None:\\n        interval = get_settings_service().settings.warm_reconcile_interval\\n    logger.info(\\\"warm_registry: reconcile loop started (interval=%ss)\\\", interval)\\n    while True:\\n        # Sleep before the first pass: warm_all() already filled the registry at startup.\\n        await asyncio.sleep(interval)\\n        try:\\n            await reconcile_once()\\n        except asyncio.CancelledError:\\n            raise\\n        except Exception:  # noqa: BLE001 \u2014 the loop must survive a bad pass\\n            logger.exception(\\\"warm_registry: reconcile pass errored; continuing\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/warm_registry/resolver.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"305360b67f78a35166f75aa81831c13901ccbe6d559c4243506c1655fcd8471e\",\"content\":\"\\\"\\\"\\\"Metadata-validated flow resolution for warm workflow execution.\\n\\nThe registry keeps a complete :class:`FlowRead` snapshot next to each graph so\\nan execution request does not need to select the (potentially large) ``data``\\ncolumn again.  Before returning that snapshot, this module reads only the\\nsmall set of metadata columns that affect ownership, authorization, routing,\\nor the registry version.  A changed or deleted row is evicted with a\\ncompare-and-evict operation and the caller falls back to the normal full-flow\\nresolver.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, cast\\nfrom uuid import UUID\\n\\nfrom sqlmodel import select\\n\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.deps import (\\n    get_authorization_service,\\n    get_settings_service,\\n    session_scope,\\n)\\nfrom langflow.services.warm_registry.service import flow_version, get_warm_registry\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Sequence\\n    from datetime import datetime\\n\\n    from langflow.services.database.models.flow.model import FlowRead\\n\\n\\ndef _warm_registry_active() -> bool:\\n    \\\"\\\"\\\"Return whether warm execution is enabled for this process.\\\"\\\"\\\"\\n    return bool(getattr(get_settings_service().settings, \\\"warm_registry_enabled\\\", False))\\n\\n\\ndef _metadata_revision(row: Sequence[object]) -> tuple[object, ...]:\\n    \\\"\\\"\\\"Convert the narrow metadata row to the registry revision shape.\\\"\\\"\\\"\\n    values: tuple[object, ...] = tuple(row)\\n    return (flow_version(cast(\\\"datetime | None\\\", values[0])), *values[1:])\\n\\n\\nasync def resolve_warm_flow_for_execution(\\n    identifier: str,\\n    user_id: UUID | str | None,\\n    *,\\n    widen_for_shares: bool = False,\\n) -> FlowRead | None:\\n    \\\"\\\"\\\"Return a current, isolated cached ``FlowRead`` or ``None`` to fetch cold.\\n\\n    Endpoint aliases are always resolved in the caller owner's namespace.\\n    Cross-owner widening is allowed only for canonical UUIDs and only when the\\n    active authorization service explicitly enables share-aware fetching.\\n    This mirrors ``get_flow_by_id_or_endpoint_name`` without making ambiguous\\n    endpoint names process-global.\\n\\n    The validation query intentionally excludes ``Flow.data``.  A cache miss,\\n    a stale/deleted snapshot, or an identifier that cannot safely use the\\n    cache returns ``None``; the API layer then invokes its existing full-row\\n    helper and retains the established 404/503 error mapping.\\n    \\\"\\\"\\\"\\n    if not _warm_registry_active() or user_id is None:\\n        return None\\n\\n    try:\\n        caller_id = user_id if isinstance(user_id, UUID) else UUID(str(user_id))\\n    except (TypeError, ValueError, AttributeError):\\n        return None\\n\\n    registry = get_warm_registry()\\n    try:\\n        flow_key = str(UUID(str(identifier)))\\n    except (TypeError, ValueError, AttributeError):\\n        # Endpoint names are unique per owner only.  Never search another\\n        # owner's aliases, even when share-aware fetching is enabled.\\n        resolved = registry.get_flow_by_endpoint_with_revision(caller_id, str(identifier))\\n        owner_scoped = True\\n        if resolved is not None and resolved[0].user_id != caller_id:\\n            return None\\n    else:\\n        resolved = registry.get_flow_with_revision(flow_key)\\n        if resolved is None:\\n            return None\\n        snapshot = resolved[0]\\n        owner_scoped = snapshot.user_id == caller_id\\n        if not owner_scoped:\\n            if not widen_for_shares:\\n                return None\\n            authz = get_authorization_service()\\n            if not await authz.is_enabled() or not await authz.supports_cross_user_fetch():\\n                return None\\n\\n    if resolved is None:\\n        return None\\n    snapshot, observed_revision = resolved\\n\\n    flow_id = str(snapshot.id)\\n\\n    # Select only the fields that can invalidate the cached resolution and\\n    # execution-route decision.  In particular, Flow.data is not selected.\\n    stmt = select(\\n        Flow.updated_at,\\n        Flow.name,\\n        Flow.user_id,\\n        Flow.workspace_id,\\n        Flow.folder_id,\\n        Flow.endpoint_name,\\n        Flow.webhook,\\n        Flow.access_type,\\n        Flow.mcp_enabled,\\n        Flow.flow_type,\\n        Flow.a2a_enabled,\\n    ).where(Flow.id == snapshot.id)\\n    if owner_scoped:\\n        stmt = stmt.where(Flow.user_id == caller_id)\\n\\n    async with session_scope() as session:\\n        row = (await session.exec(stmt)).first()\\n\\n    if row is None or _metadata_revision(row) != observed_revision:\\n        await registry.evict_if_revision(flow_id, observed_revision)\\n        return None\\n\\n    # Reconcile may have published a newer snapshot while the metadata query\\n    # awaited the DB.  Never return the older object in that race; the caller's\\n    # cold fallback is safe and the next request can use the new revision.\\n    if registry.get_entry_revision(flow_id) != observed_revision:\\n        return None\\n\\n    # get_flow_with_revision already returned an isolated deep copy.\\n    return snapshot\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/warm_registry/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3aa913f7e6dc9990caa1ec15d37d082106f8ba3e9bef679c4525d6b4a360a1cb\",\"content\":\"\\\"\\\"\\\"The bounded per-worker warm graph registry.\\n\\nEach process-local entry contains a parsed structural ``Graph`` template, a\\nminimal execution/auth ``FlowRead`` snapshot, and the flow's ``updated_at``\\nrevision. Component constructors are deliberately deferred until a request-local\\ncopy is bound to the caller. Resident entries and in-flight builds share explicit\\nentry/byte budgets so warming cannot turn tenant data into unbounded worker work.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nfrom collections import OrderedDict\\nfrom copy import deepcopy\\nfrom dataclasses import dataclass\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING\\nfrom weakref import WeakValueDictionary\\n\\nimport orjson\\nfrom lfx.log.logger import logger\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.graph.base import Graph\\n\\n    from langflow.services.database.models.flow.model import FlowRead\\n\\n\\ndef flow_version(updated_at: datetime | None) -> str:\\n    \\\"\\\"\\\"Normalize a flow change marker for ordering and exact cache matching.\\\"\\\"\\\"\\n    if updated_at is None:\\n        return \\\"\\\"\\n    normalized = (\\n        updated_at.replace(tzinfo=timezone.utc) if updated_at.tzinfo is None else updated_at.astimezone(timezone.utc)\\n    )\\n    return normalized.isoformat()\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass WarmFlowEntry:\\n    \\\"\\\"\\\"One atomically published graph and its isolated flow-resolution metadata.\\\"\\\"\\\"\\n\\n    graph: Graph\\n    version: str\\n    flow: FlowRead | None\\n    revision: tuple[object, ...]\\n\\n\\nclass FlowStoreUnavailableError(Exception):\\n    \\\"\\\"\\\"The flow store could not be reached while (lazily) warming a flow.\\n\\n    Distinguishes a transient availability failure (DB down / pool exhausted) from a\\n    genuine not-found, so the API layer can answer 503 (retryable) instead of 404\\n    (permanent). Raised by ``warm_one``; translated to an HTTP 503 by the host.\\n    \\\"\\\"\\\"\\n\\n\\nclass WarmRegistryCapacityError(Exception):\\n    \\\"\\\"\\\"A flow cannot fit within this worker's configured warm-cache bounds.\\\"\\\"\\\"\\n\\n    def __init__(self, message: str, *, transient: bool = False) -> None:\\n        super().__init__(message)\\n        self.transient = transient\\n\\n\\nclass WarmGraphRegistry:\\n    \\\"\\\"\\\"In-memory canonical-flow registry for one worker process.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        *,\\n        max_entries: int = 128,\\n        max_flow_bytes: int = 2_000_000,\\n        max_total_bytes: int = 32_000_000,\\n        preload_limit: int = 0,\\n    ) -> None:\\n        # flow UUID (str) -> immutable entry. One dict per\\n        # worker process; nothing is shared across processes/machines \u2014 the\\n        # reconcile loop against the shared DB is what keeps them converged.\\n        self._flows: dict[str, WarmFlowEntry] = {}\\n        # (owner user UUID, endpoint name) -> canonical flow UUID. Endpoint names\\n        # are unique only within an owner, never process-global.\\n        self._endpoint_aliases: dict[tuple[str | None, str], str] = {}\\n        # Guards writers (add/evict) so concurrent reconcile/warm calls can't leave a\\n        # half-written dict. Reads (``get``) are plain dict lookups (atomic in CPython)\\n        # and take no lock, keeping the hot request path fast.\\n        self._lock = asyncio.Lock()\\n        # Serialize builds for one flow while still allowing unrelated flows to build\\n        # concurrently. The cache is rechecked after acquiring this lock, so concurrent\\n        # misses for the same version collapse to one ``Graph.from_payload`` call.\\n        self._build_locks: WeakValueDictionary[str, asyncio.Lock] = WeakValueDictionary()\\n        # Latest (version, full metadata revision) whose build failed. This tombstone\\n        # keeps a delayed observation of older DB state \u2014 including the same timestamp\\n        # with older aliases \u2014 from resurrecting the stale graph evicted on failure.\\n        # A failed revision is not retried every reconcile interval; a later\\n        # database revision clears the backoff and gets one fresh build attempt.\\n        self._failed_revisions: OrderedDict[str, tuple[str, tuple[object, ...]]] = OrderedDict()\\n        # Serialized JSON bytes are a stable accounting unit. Parsed graphs have\\n        # additional overhead, so the defaults intentionally leave headroom.\\n        self._max_entries = max_entries\\n        self._max_flow_bytes = max_flow_bytes\\n        self._max_total_bytes = max_total_bytes\\n        # Preload scan window. The tombstone budget is sized against this (the population\\n        # that can be selected and rejected), NOT against max_entries (an unrelated\\n        # resident-entry limit) \u2014 otherwise un-warmable flows above 2*max_entries rotate\\n        # their tombstones forever and are re-selected/re-read every reconcile pass.\\n        self._preload_limit = preload_limit\\n        self._flow_payload_bytes: dict[str, int] = {}\\n        self._total_payload_bytes = 0\\n        # Charge concurrent builds against the same budgets as resident entries.\\n        self._build_reservations: dict[str, int] = {}\\n        self._reserved_payload_bytes = 0\\n        # Bound CPU-heavy snapshot/parse work and the executor queue feeding it.\\n        self._build_semaphore = asyncio.Semaphore(max(1, min(max_entries, 4)))\\n\\n    def _build_lock(self, flow_id: str) -> asyncio.Lock:\\n        \\\"\\\"\\\"Return the stable per-flow build lock for this registry.\\\"\\\"\\\"\\n        # There is no await between lookup and insertion, so this is atomic with respect\\n        # to other tasks on the event loop (all registry mutation is async/task-local).\\n        return self._build_locks.setdefault(flow_id, asyncio.Lock())\\n\\n    def _record_failed_locked(self, flow_id: str, version: str, revision: tuple[object, ...]) -> None:\\n        \\\"\\\"\\\"Record a bounded retry tombstone while the registry lock is held.\\\"\\\"\\\"\\n        self._failed_revisions[flow_id] = (version, revision)\\n        self._failed_revisions.move_to_end(flow_id)\\n        # Budget must cover the flows preload can scan and reject, not the resident-entry\\n        # limit. Sizing it against max_entries alone let an un-warmable population larger\\n        # than 2*max_entries evict older tombstones, so those flows dropped out of the\\n        # backoff and were re-selected as \\\"new\\\" every pass \u2014 a full SELECT + deepcopy +\\n        # serialize per flow per interval, forever, with no cache benefit.\\n        #\\n        # Known limitation: if the preloadable set holds MORE un-warmable flows than this\\n        # budget, the oldest tombstone is still dropped and that flow can be re-attempted on\\n        # a later pass. The warning below surfaces that so an operator can raise\\n        # max_flow_bytes or lower preload_limit; a full fix (cheap size pre-check so\\n        # oversized flows are skipped without a tombstone) is tracked separately.\\n        max_tombstones = max(self._max_entries * 2, self._preload_limit)\\n        if len(self._failed_revisions) > max_tombstones:\\n            logger.warning(\\n                \\\"warm_registry: tombstone budget (%d) reached; dropping the oldest failure marker. \\\"\\n                \\\"More flows are un-warmable than the budget can track, so some will be re-attempted \\\"\\n                \\\"each reconcile pass (extra DB reads for no cache benefit). Raise \\\"\\n                \\\"LANGFLOW_WARM_REGISTRY_MAX_FLOW_BYTES or lower LANGFLOW_WARM_REGISTRY_PRELOAD_LIMIT.\\\",\\n                max_tombstones,\\n            )\\n        while len(self._failed_revisions) > max_tombstones:\\n            self._failed_revisions.popitem(last=False)\\n\\n    @staticmethod\\n    def _revision(version: str, name: str | None, flow: FlowRead | None) -> tuple[object, ...]:\\n        \\\"\\\"\\\"Return the build/resolution revision used for cache rechecks.\\n\\n        ``updated_at`` remains the ordering marker. Resolution and route-gate fields\\n        join the equality revision so an add that carries changed metadata cannot be\\n        skipped merely because it observed the same timestamp representation.\\n        \\\"\\\"\\\"\\n        if flow is None:\\n            return (version, name)\\n        return (\\n            version,\\n            flow.name,\\n            flow.user_id,\\n            flow.workspace_id,\\n            flow.folder_id,\\n            flow.endpoint_name,\\n            flow.webhook,\\n            flow.access_type,\\n            flow.mcp_enabled,\\n            flow.flow_type,\\n            flow.a2a_enabled,\\n        )\\n\\n    @staticmethod\\n    def _endpoint_key(flow: FlowRead | None) -> tuple[str | None, str] | None:\\n        if flow is None or not flow.endpoint_name:\\n            return None\\n        owner_id = str(flow.user_id) if flow.user_id is not None else None\\n        return owner_id, flow.endpoint_name\\n\\n    def _remove_entry_locked(self, flow_id: str) -> None:\\n        \\\"\\\"\\\"Remove one entry and its alias while ``self._lock`` is held.\\\"\\\"\\\"\\n        entry = self._flows.pop(flow_id, None)\\n        if entry is None:\\n            return\\n        endpoint_key = self._endpoint_key(entry.flow)\\n        if endpoint_key is not None and self._endpoint_aliases.get(endpoint_key) == flow_id:\\n            self._endpoint_aliases.pop(endpoint_key, None)\\n        self._total_payload_bytes -= self._flow_payload_bytes.pop(flow_id, 0)\\n\\n    @staticmethod\\n    def _build(flow_id: str, name: str | None, data: dict) -> Graph:\\n        \\\"\\\"\\\"Parse ``flow.data`` into a structural ``Graph`` template.\\n\\n        ``data`` is deepcopied first because ``from_payload`` rewrites the payload\\n        in place (legacy component migration), and the caller's dict may be the DB\\n        row's own mapping. Components and extension events are deferred; the\\n        request-local ``copy_for_run`` binds identity and constructs components.\\n        \\\"\\\"\\\"\\n        from lfx.graph.graph.base import Graph\\n\\n        return Graph.from_payload(\\n            deepcopy(data),\\n            flow_id=flow_id,\\n            flow_name=name,\\n            instantiate_components=False,\\n            emit_extension_events=False,\\n        )\\n\\n    @classmethod\\n    def _prepare_snapshot(\\n        cls,\\n        name: str | None,\\n        data: dict,\\n        version: str,\\n        flow: FlowRead | None,\\n    ) -> tuple[FlowRead | None, tuple[object, ...], str | None, dict, int]:\\n        \\\"\\\"\\\"Create and measure the retained execution snapshot off-loop.\\n\\n        Descriptive and A2A presentation fields are not used by the warm sync\\n        execution path and may be arbitrarily large, so retain only executable,\\n        authorization, routing, and revision fields. The measured JSON includes\\n        every retained field, not just ``flow.data``.\\n        \\\"\\\"\\\"\\n        if flow is None:\\n            build_data = deepcopy(data)\\n            stored_flow = None\\n            build_name = name\\n            measured: object = build_data\\n        else:\\n            from langflow.services.database.models.flow.model import FlowRead\\n\\n            snapshot_data = deepcopy(flow.data if flow.data is not None else data)\\n            stored_flow = FlowRead(\\n                id=flow.id,\\n                name=flow.name,\\n                data=snapshot_data,\\n                updated_at=flow.updated_at,\\n                user_id=flow.user_id,\\n                folder_id=flow.folder_id,\\n                workspace_id=flow.workspace_id,\\n                endpoint_name=flow.endpoint_name,\\n                webhook=flow.webhook,\\n                access_type=flow.access_type,\\n                mcp_enabled=flow.mcp_enabled,\\n                flow_type=flow.flow_type,\\n                a2a_enabled=flow.a2a_enabled,\\n            )\\n            build_data = snapshot_data\\n            build_name = stored_flow.name\\n            measured = stored_flow.model_dump(mode=\\\"json\\\")\\n        revision = cls._revision(version, name, stored_flow)\\n        return stored_flow, revision, build_name, build_data, len(orjson.dumps(measured))\\n\\n    @staticmethod\\n    async def _await_task_without_abandoning(task):\\n        \\\"\\\"\\\"Wait for owned work to finish despite repeated caller cancellation.\\\"\\\"\\\"\\n        caller_cancelled = False\\n        # ``asyncio.wait`` reports completion without propagating the owned\\n        # task's exception, letting cancellation retain precedence while the\\n        # resource-owning task is drained.\\n        completion = asyncio.create_task(asyncio.wait({task}))\\n        while not completion.done():\\n            try:\\n                await asyncio.shield(completion)\\n            except asyncio.CancelledError:\\n                # Each cancel request can interrupt a fresh await. Keep shielding\\n                # until the owned task is actually done; otherwise a native\\n                # ``to_thread`` worker can outlive its semaphore/byte reservation.\\n                caller_cancelled = True\\n\\n        if caller_cancelled:\\n            # Observe a worker exception so asyncio does not report it as unhandled;\\n            # cancellation remains the request-visible outcome, as before.\\n            if not task.cancelled():\\n                with contextlib.suppress(Exception):\\n                    task.result()\\n            raise asyncio.CancelledError\\n        return task.result()\\n\\n    @classmethod\\n    async def _to_thread_without_abandoning(cls, function, *args):\\n        \\\"\\\"\\\"Keep the build slot held until thread work ends, even if cancelled.\\\"\\\"\\\"\\n        task = asyncio.create_task(asyncio.to_thread(function, *args))\\n        return await cls._await_task_without_abandoning(task)\\n\\n    def _capacity_reason_locked(self, flow_id: str, entry_bytes: int) -> tuple[str | None, bool]:\\n        \\\"\\\"\\\"Return a capacity reason and whether only competing builds cause it.\\\"\\\"\\\"\\n        current_bytes = self._flow_payload_bytes.get(flow_id, 0)\\n        resident_flow_ids = set(self._flows)\\n        resident_flow_ids.add(flow_id)\\n        resident_total = self._total_payload_bytes + entry_bytes - current_bytes\\n        if len(resident_flow_ids) > self._max_entries:\\n            return \\\"entry count\\\", False\\n        if resident_total > self._max_total_bytes:\\n            return \\\"total entry bytes\\\", False\\n\\n        # A reservation for a resident flow replaces that resident's bytes; it\\n        # does not consume an additional entry or a second full byte allocation.\\n        projected_flow_ids = resident_flow_ids.copy()\\n        projected_total = resident_total\\n        for reserved_id, reserved_bytes in self._build_reservations.items():\\n            if reserved_id == flow_id:\\n                continue\\n            projected_flow_ids.add(reserved_id)\\n            projected_total += reserved_bytes - self._flow_payload_bytes.get(reserved_id, 0)\\n        if len(projected_flow_ids) > self._max_entries:\\n            return \\\"entry count\\\", True\\n        if projected_total > self._max_total_bytes:\\n            return \\\"total entry bytes\\\", True\\n        return None, False\\n\\n    def _reserve_build_locked(self, flow_id: str, entry_bytes: int) -> None:\\n        self._build_reservations[flow_id] = entry_bytes\\n        self._reserved_payload_bytes += entry_bytes\\n\\n    def _release_build_locked(self, flow_id: str) -> None:\\n        self._reserved_payload_bytes -= self._build_reservations.pop(flow_id, 0)\\n\\n    async def _release_build_cancellation_safe(self, flow_id: str) -> None:\\n        \\\"\\\"\\\"Release a reservation even when the owning request is cancelled.\\\"\\\"\\\"\\n\\n        async def _release() -> None:\\n            async with self._lock:\\n                self._release_build_locked(flow_id)\\n\\n        task = asyncio.create_task(_release())\\n        await self._await_task_without_abandoning(task)\\n\\n    @contextlib.asynccontextmanager\\n    async def _build_reservation(self, flow_id: str, entry_bytes: int):\\n        \\\"\\\"\\\"Atomically reserve capacity and always release it on context exit.\\\"\\\"\\\"\\n        async with self._lock:\\n            reason, transient = self._capacity_reason_locked(flow_id, entry_bytes)\\n            if reason is not None:\\n                msg = f\\\"warm registry {reason} limit reached while adding flow {flow_id}\\\"\\n                raise WarmRegistryCapacityError(msg, transient=transient)\\n            self._reserve_build_locked(flow_id, entry_bytes)\\n        try:\\n            yield\\n        finally:\\n            await self._release_build_cancellation_safe(flow_id)\\n\\n    def _publish_locked(\\n        self,\\n        *,\\n        flow_id: str,\\n        version: str,\\n        graph: Graph,\\n        stored_flow: FlowRead | None,\\n        revision: tuple[object, ...],\\n        entry_bytes: int,\\n    ) -> None:\\n        \\\"\\\"\\\"Publish one completed build while ``self._lock`` is held.\\\"\\\"\\\"\\n        current = self._flows.get(flow_id)\\n        if current is not None and current.version >= version:\\n            return\\n        failed = self._failed_revisions.get(flow_id)\\n        if failed is not None and failed[0] >= version:\\n            return\\n        reason, transient = self._capacity_reason_locked(flow_id, entry_bytes)\\n        if reason is not None:\\n            msg = f\\\"warm registry {reason} limit reached while adding flow {flow_id}\\\"\\n            raise WarmRegistryCapacityError(msg, transient=transient)\\n\\n        current_payload_bytes = self._flow_payload_bytes.get(flow_id, 0)\\n        old_endpoint_key = self._endpoint_key(current.flow) if current is not None else None\\n        new_endpoint_key = self._endpoint_key(stored_flow)\\n        if old_endpoint_key is not None and self._endpoint_aliases.get(old_endpoint_key) == flow_id:\\n            self._endpoint_aliases.pop(old_endpoint_key, None)\\n        self._flows[flow_id] = WarmFlowEntry(\\n            graph=graph,\\n            version=version,\\n            flow=stored_flow,\\n            revision=revision,\\n        )\\n        self._total_payload_bytes -= current_payload_bytes\\n        self._flow_payload_bytes[flow_id] = entry_bytes\\n        self._total_payload_bytes += entry_bytes\\n        if new_endpoint_key is not None:\\n            self._endpoint_aliases[new_endpoint_key] = flow_id\\n        if failed is not None and (failed[0] < version or (failed[0] == version and failed[1] == revision)):\\n            self._failed_revisions.pop(flow_id, None)\\n\\n    async def add(\\n        self,\\n        flow_id: str,\\n        name: str | None,\\n        data: dict,\\n        version: str,\\n        *,\\n        flow: FlowRead | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"Build ``data`` into a template and store it under ``flow_id`` at ``version``.\\n\\n        Duplicate misses are singleflighted per flow. Snapshotting and parsing run\\n        off-loop behind a small global semaphore, and each in-flight build reserves\\n        its entry/byte budget before parsing. ``flow`` is complete in runtime callers,\\n        but only the fields required for sync execution are retained.\\n\\n        Versions are ISO-formatted ``updated_at`` values, so their lexical order is\\n        chronological. A cached/tombstoned newer version always wins over a delayed\\n        older request. If a newer payload fails to build, any resident older template\\n        is evicted and the failed revision is tombstoned: serving no graph is safer\\n        than continuing to serve a graph known not to match the database.\\n        \\\"\\\"\\\"\\n        async with self._build_lock(flow_id):\\n            # Reject known/current revisions before copying or serializing tenant\\n            # data. Tombstones therefore back off all cache-side CPU work.\\n            current = self._flows.get(flow_id)\\n            # Equal timestamps are not orderable. Keep the already-published entry;\\n            # request-side metadata validation evicts it before a legitimate same-time\\n            # replacement is rebuilt. This also prevents a delayed old alias/scope\\n            # snapshot from overwriting the current entry at the same timestamp.\\n            if current is not None and current.version >= version:\\n                return\\n            failed = self._failed_revisions.get(flow_id)\\n            if failed is not None:\\n                failed_version, _failed_revision = failed\\n                if failed_version >= version:\\n                    return\\n\\n            async with self._build_semaphore:\\n                cheap_revision = self._revision(version, name, flow)\\n                try:\\n                    (\\n                        stored_flow,\\n                        revision,\\n                        build_name,\\n                        build_data,\\n                        entry_bytes,\\n                    ) = await self._to_thread_without_abandoning(self._prepare_snapshot, name, data, version, flow)\\n                except Exception:\\n                    async with self._lock:\\n                        current = self._flows.get(flow_id)\\n                        if current is not None and current.version < version:\\n                            self._remove_entry_locked(flow_id)\\n                        self._record_failed_locked(flow_id, version, cheap_revision)\\n                    raise\\n\\n                if entry_bytes > self._max_flow_bytes:\\n                    async with self._lock:\\n                        current = self._flows.get(flow_id)\\n                        if current is not None and (\\n                            current.version < version or (current.version == version and current.revision != revision)\\n                        ):\\n                            self._remove_entry_locked(flow_id)\\n                        self._record_failed_locked(flow_id, version, revision)\\n                    msg = f\\\"flow {flow_id} entry is {entry_bytes} bytes; warm limit is {self._max_flow_bytes} bytes\\\"\\n                    raise WarmRegistryCapacityError(msg)\\n\\n                try:\\n                    async with self._build_reservation(flow_id, entry_bytes):\\n                        try:\\n                            graph = await self._to_thread_without_abandoning(\\n                                self._build, flow_id, build_name, build_data\\n                            )\\n                        except asyncio.CancelledError:\\n                            raise\\n                        except Exception:\\n                            async with self._lock:\\n                                current = self._flows.get(flow_id)\\n                                if current is not None and (\\n                                    current.version < version\\n                                    or (current.version == version and current.revision != revision)\\n                                ):\\n                                    self._remove_entry_locked(flow_id)\\n                                failed = self._failed_revisions.get(flow_id)\\n                                if failed is None or failed[0] <= version:\\n                                    self._record_failed_locked(flow_id, version, revision)\\n                            raise\\n\\n                        async with self._lock:\\n                            self._publish_locked(\\n                                flow_id=flow_id,\\n                                version=version,\\n                                graph=graph,\\n                                stored_flow=stored_flow,\\n                                revision=revision,\\n                                entry_bytes=entry_bytes,\\n                            )\\n                except WarmRegistryCapacityError as exc:\\n                    # Capacity rejection is a cache decision. Tombstone every\\n                    # intrinsically rejected revision so requests and reconcile\\n                    # do not repeat snapshot/serialization work. Pressure caused\\n                    # only by another in-flight build is retryable because that\\n                    # competing build may still fail or be cancelled.\\n                    async with self._lock:\\n                        current = self._flows.get(flow_id)\\n                        if current is not None and (\\n                            current.version < version or (current.version == version and current.revision != revision)\\n                        ):\\n                            self._remove_entry_locked(flow_id)\\n                        if not exc.transient:\\n                            self._record_failed_locked(flow_id, version, revision)\\n                    raise\\n\\n    def get(self, flow_id: str) -> tuple[Graph, str] | None:\\n        \\\"\\\"\\\"Return the shared ``(template, version)`` for ``flow_id`` or ``None``.\\n\\n        The template is NOT copied here \u2014 the caller deepcopies before running.\\n        \\\"\\\"\\\"\\n        entry = self._flows.get(flow_id)\\n        return (entry.graph, entry.version) if entry is not None else None\\n\\n    def get_flow(self, flow_id: str) -> FlowRead | None:\\n        \\\"\\\"\\\"Return an isolated ``FlowRead`` snapshot for a canonical UUID.\\\"\\\"\\\"\\n        resolved = self.get_flow_with_revision(flow_id)\\n        return resolved[0] if resolved is not None else None\\n\\n    def get_flow_with_revision(self, flow_id: str) -> tuple[FlowRead, tuple[object, ...]] | None:\\n        \\\"\\\"\\\"Return one entry's isolated flow snapshot and matching revision.\\n\\n        Reading both values from the same immutable entry is important for shared-flow\\n        resolution, which can await authorization-service checks before validating the\\n        revision. Separate lookups could otherwise pair an old snapshot with a newly\\n        reconciled revision.\\n        \\\"\\\"\\\"\\n        entry = self._flows.get(str(flow_id))\\n        if entry is None or entry.flow is None:\\n            return None\\n        return entry.flow.model_copy(deep=True), entry.revision\\n\\n    def get_flow_by_endpoint(self, user_id: object | None, endpoint_name: str) -> FlowRead | None:\\n        \\\"\\\"\\\"Resolve an endpoint name only within the caller owner's namespace.\\\"\\\"\\\"\\n        resolved = self.get_flow_by_endpoint_with_revision(user_id, endpoint_name)\\n        return resolved[0] if resolved is not None else None\\n\\n    def get_flow_by_endpoint_with_revision(\\n        self,\\n        user_id: object | None,\\n        endpoint_name: str,\\n    ) -> tuple[FlowRead, tuple[object, ...]] | None:\\n        \\\"\\\"\\\"Resolve an owner-qualified alias and return one coherent entry snapshot.\\\"\\\"\\\"\\n        owner_id = str(user_id) if user_id is not None else None\\n        flow_id = self._endpoint_aliases.get((owner_id, endpoint_name))\\n        return self.get_flow_with_revision(flow_id) if flow_id is not None else None\\n\\n    def revision_of(self, flow_id: str) -> tuple[object, ...] | None:\\n        \\\"\\\"\\\"Return the immutable resolution/build revision for metadata validation.\\\"\\\"\\\"\\n        entry = self._flows.get(str(flow_id))\\n        return entry.revision if entry is not None else None\\n\\n    def get_entry_revision(self, flow_id: str) -> tuple[object, ...] | None:\\n        \\\"\\\"\\\"Backward-compatible descriptive alias for :meth:`revision_of`.\\\"\\\"\\\"\\n        return self.revision_of(flow_id)\\n\\n    def version_of(self, flow_id: str) -> str | None:\\n        \\\"\\\"\\\"Return just the cached version for ``flow_id`` (or ``None``) without the graph.\\\"\\\"\\\"\\n        hit = self._flows.get(flow_id)\\n        return hit.version if hit is not None else None\\n\\n    def rejects_version(self, flow_id: str, version: str) -> bool:\\n        \\\"\\\"\\\"Return whether a failed/newer revision should stay on the cold path.\\\"\\\"\\\"\\n        failed = self._failed_revisions.get(flow_id)\\n        return failed is not None and failed[0] >= version\\n\\n    def rejection_count(self) -> int:\\n        \\\"\\\"\\\"Return the bounded number of revisions reconcile may need to scan past.\\\"\\\"\\\"\\n        return len(self._failed_revisions)\\n\\n    async def reject_revision(\\n        self,\\n        flow_id: str,\\n        version: str,\\n        *,\\n        name: str | None = None,\\n        flow: FlowRead | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"Keep a known non-runnable revision cold and evict any older template.\\\"\\\"\\\"\\n        revision = self._revision(version, name, flow)\\n        async with self._build_lock(flow_id), self._lock:\\n            current = self._flows.get(flow_id)\\n            if current is not None and current.version > version:\\n                return\\n            if current is not None:\\n                self._remove_entry_locked(flow_id)\\n            failed = self._failed_revisions.get(flow_id)\\n            if failed is None or failed[0] <= version:\\n                self._record_failed_locked(flow_id, version, revision)\\n\\n    async def evict(self, flow_id: str) -> None:\\n        \\\"\\\"\\\"Drop ``flow_id`` from the cache (no-op if already gone).\\\"\\\"\\\"\\n        # Wait for an in-flight build of this flow before evicting it. Otherwise a\\n        # delete/empty-data reconcile could pop the old entry and have the delayed\\n        # build immediately resurrect it.\\n        async with self._build_lock(flow_id), self._lock:\\n            self._remove_entry_locked(flow_id)\\n\\n    async def evict_if_revision(self, flow_id: str, revision: tuple[object, ...]) -> bool:\\n        \\\"\\\"\\\"Evict only if ``flow_id`` still has the caller-observed revision.\\n\\n        Request-side metadata validation can race a reconcile rebuild. Comparing under\\n        the per-flow writer lock prevents a stale validator from deleting the newer\\n        graph/snapshot/alias that won that race.\\n        \\\"\\\"\\\"\\n        async with self._build_lock(flow_id), self._lock:\\n            current = self._flows.get(flow_id)\\n            if current is None or current.revision != revision:\\n                return False\\n            self._remove_entry_locked(flow_id)\\n            return True\\n\\n    def active_ids(self) -> set[str]:\\n        \\\"\\\"\\\"Snapshot of the currently cached flow ids (reconcile diffs this vs the DB manifest).\\\"\\\"\\\"\\n        return set(self._flows)\\n\\n    def remaining_entries(self) -> int:\\n        \\\"\\\"\\\"Return entry slots not occupied or reserved by an in-flight build.\\\"\\\"\\\"\\n        reserved_new_ids = set(self._build_reservations).difference(self._flows)\\n        return max(0, self._max_entries - len(self._flows) - len(reserved_new_ids))\\n\\n    def __len__(self) -> int:\\n        return len(self._flows)\\n\\n\\n_warm_registry: WarmGraphRegistry | None = None\\n\\n\\ndef get_warm_registry() -> WarmGraphRegistry:\\n    \\\"\\\"\\\"Return the process-local warm registry singleton, creating it on first use.\\\"\\\"\\\"\\n    global _warm_registry  # noqa: PLW0603\\n    if _warm_registry is None:\\n        from langflow.services.deps import get_settings_service\\n\\n        settings = get_settings_service().settings\\n        max_entries = settings.warm_registry_max_entries\\n        preload_limit = settings.warm_registry_preload_limit\\n        # A preload_limit above max_entries is a misconfiguration: the cache can hold at\\n        # most max_entries resident templates, so preload effectively fills no more than\\n        # that (preload_slots is min()'d against remaining capacity). Warn \u2014 don't clamp \u2014\\n        # so the operator can fix the config; the value is still passed through so the\\n        # tombstone budget can size against the operator's stated preload intent.\\n        if preload_limit > max_entries:\\n            logger.warning(\\n                \\\"warm_registry: LANGFLOW_WARM_REGISTRY_PRELOAD_LIMIT (%d) exceeds \\\"\\n                \\\"LANGFLOW_WARM_REGISTRY_MAX_ENTRIES (%d); at most %d flows can stay resident, \\\"\\n                \\\"so preload cannot warm more than that. Set preload_limit <= max_entries.\\\",\\n                preload_limit,\\n                max_entries,\\n                max_entries,\\n            )\\n        _warm_registry = WarmGraphRegistry(\\n            max_entries=max_entries,\\n            max_flow_bytes=settings.warm_registry_max_flow_bytes,\\n            max_total_bytes=settings.warm_registry_max_total_bytes,\\n            preload_limit=preload_limit,\\n        )\\n        logger.debug(\\\"warm_registry: initialized process-local registry\\\")\\n    return _warm_registry\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/settings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9ce40a6b2af105ba5720962fde81adfbadf514e4a34c8ede52b83f02e87abe73\",\"content\":\"import os\\n\\nDEV = os.getenv(\\\"LANGFLOW_DEV\\\", \\\"false\\\").lower() == \\\"true\\\"\\n\\n\\ndef _set_dev(value) -> None:\\n    global DEV  # noqa: PLW0603\\n    DEV = value\\n\\n\\ndef set_dev(value) -> None:\\n    _set_dev(value)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/template/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"db28b4550983fd45fcf7f06cc9b9e6e62c952ee42059be5f587b7a7b184739a3\",\"content\":\"\\\"\\\"\\\"Backwards compatibility module for langflow.template.\\\"\\\"\\\"\\n\\nfrom lfx.template import *  # noqa: F403\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/template/field/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"11f4256f1da810020ac4c281130dc5f6397f12feb57960d01c9f76fe3aeb8071\",\"content\":\"\\\"\\\"\\\"Backwards compatibility module for langflow.template.field.\\\"\\\"\\\"\\n\\nfrom lfx.template.field import *  # noqa: F403\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/template/field/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"739613b507a39bd3c5d81c23b491a39b63f51d93f2b85fa0e8f9d41c2716e185\",\"content\":\"\\\"\\\"\\\"Backwards compatibility module for langflow.template.field.base.\\\"\\\"\\\"\\n\\nfrom lfx.template.field.base import *  # noqa: F403\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/template/frontend_node.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f61d996f10245e379441bd11a12c8ef57e0550dc3fb40c88877d1f509c0073cd\",\"content\":\"\\\"\\\"\\\"Backwards compatibility module for langflow.template.frontend_node.\\\"\\\"\\\"\\n\\nfrom lfx.template.frontend_node import *  # noqa: F403\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/template/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5d4576fcf6117e1fead40135edbb2b7515874879f73a34133f9d346e59e012c9\",\"content\":\"\\\"\\\"\\\"Backwards compatibility module for langflow.template.utils.\\\"\\\"\\\"\\n\\nfrom lfx.template.utils import *  # noqa: F403\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f1a18073d0ca38081a3b0147c1125cc3ca71d99835b88a88b1198bd117297a2a\",\"content\":\"\\\"\\\"\\\"Tests package for langflow.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/api/v1/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/api/v1/test_deployment_guard_delete_endpoints.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b2ed1ba58c54f892973fd6dcb1e7e6d211d28be3c23fc352bdb3557f54e692ee\",\"content\":\"from __future__ import annotations\\n\\nfrom http import HTTPStatus\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi import FastAPI\\nfrom fastapi.responses import JSONResponse\\nfrom httpx import ASGITransport, AsyncClient\\nfrom langflow.api.utils import cascade_delete_flow\\nfrom langflow.api.v1.projects import delete_project\\nfrom langflow.services.database.models.deployment.exceptions import DeploymentGuardError\\n\\n\\nclass _ExecResult:\\n    def __init__(self, value, rowcount: int = 0):\\n        self._value = value\\n        self.rowcount = rowcount\\n\\n    def first(self):\\n        return self._value\\n\\n    def all(self):\\n        return self._value\\n\\n\\nclass _AsyncNullContext:\\n    async def __aenter__(self):\\n        return None\\n\\n    async def __aexit__(self, exc_type, exc, tb):\\n        return False\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_project_raises_guard_error_from_app_level_check(monkeypatch):\\n    project_id = uuid4()\\n    user_id = uuid4()\\n\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.projects.get_settings_service\\\",\\n        lambda: SimpleNamespace(settings=SimpleNamespace(add_projects_to_mcp_servers=False)),\\n    )\\n    monkeypatch.setattr(\\\"langflow.api.v1.projects.cleanup_mcp_on_delete\\\", AsyncMock())\\n    monkeypatch.setattr(\\\"langflow.api.v1.mappers.deployments.sync.sync_project_deployments\\\", AsyncMock())\\n\\n    session = AsyncMock()\\n    project = SimpleNamespace(id=project_id, name=\\\"Test Project\\\", auth_settings=None)\\n    session.exec = AsyncMock(\\n        side_effect=[\\n            _ExecResult(project),  # initial project lookup\\n            _ExecResult([]),  # first attempt: flows query\\n            _ExecResult(uuid4()),  # first attempt: check_project_has_deployments\\n            _ExecResult([]),  # second attempt: flows query\\n            _ExecResult(uuid4()),  # second attempt: check_project_has_deployments\\n        ]\\n    )\\n    session.delete = AsyncMock()\\n    session.flush = AsyncMock()\\n    session.begin_nested = lambda: _AsyncNullContext()\\n\\n    with pytest.raises(\\n        DeploymentGuardError,\\n        match=(\\n            r\\\"project cannot be deleted because it has deployments\\\\. \\\"\\n            r\\\"Please delete its deployments first\\\\.\\\"\\n        ),\\n    ):\\n        await delete_project(\\n            session=session,\\n            project_id=project_id,\\n            current_user=SimpleNamespace(id=user_id),\\n        )\\n\\n    session.flush.assert_not_awaited()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_project_remaps_flow_guard_to_project_guard(monkeypatch):\\n    project_id = uuid4()\\n    user_id = uuid4()\\n    flow_id = uuid4()\\n\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.projects.get_settings_service\\\",\\n        lambda: SimpleNamespace(settings=SimpleNamespace(add_projects_to_mcp_servers=False)),\\n    )\\n    monkeypatch.setattr(\\\"langflow.api.v1.projects.cleanup_mcp_on_delete\\\", AsyncMock())\\n    monkeypatch.setattr(\\\"langflow.api.v1.mappers.deployments.sync.sync_project_deployments\\\", AsyncMock())\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.projects.cascade_delete_flow\\\",\\n        AsyncMock(\\n            side_effect=DeploymentGuardError(\\n                code=\\\"FLOW_HAS_DEPLOYED_VERSIONS\\\",\\n                technical_detail=(\\n                    \\\"DELETE flow_version blocked: dependent rows exist in flow_version_deployment_attachment \\\"\\n                    \\\"for the target flow.\\\"\\n                ),\\n                detail=(\\n                    \\\"This flow cannot be deleted because it has deployed versions. \\\"\\n                    \\\"Please remove its versions from deployments first.\\\"\\n                ),\\n            )\\n        ),\\n    )\\n\\n    session = AsyncMock()\\n    project = SimpleNamespace(id=project_id, name=\\\"Test Project\\\", auth_settings=None)\\n    session.exec = AsyncMock(\\n        side_effect=[\\n            _ExecResult(project),  # initial project lookup\\n            _ExecResult([SimpleNamespace(id=flow_id)]),  # first attempt: flows query\\n            _ExecResult([SimpleNamespace(id=flow_id)]),  # second attempt: flows query\\n        ]\\n    )\\n    session.delete = AsyncMock()\\n    session.flush = AsyncMock()\\n    session.begin_nested = lambda: _AsyncNullContext()\\n\\n    with pytest.raises(\\n        DeploymentGuardError,\\n        match=(\\n            r\\\"project cannot be deleted because it has deployments\\\\. \\\"\\n            r\\\"Please delete its deployments first\\\\.\\\"\\n        ),\\n    ) as exc_info:\\n        await delete_project(\\n            session=session,\\n            project_id=project_id,\\n            current_user=SimpleNamespace(id=user_id),\\n        )\\n\\n    assert exc_info.value.code == \\\"PROJECT_HAS_DEPLOYMENTS\\\"\\n    assert \\\"DELETE folder blocked while deleting project flows\\\" in exc_info.value.technical_detail\\n    session.flush.assert_not_awaited()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_cascade_delete_flow_raises_guard_error_from_app_level_check():\\n    \\\"\\\"\\\"cascade_delete_flow should run app-level guard checks before issuing deletes.\\\"\\\"\\\"\\n    flow_id = uuid4()\\n\\n    session = AsyncMock()\\n    session.exec = AsyncMock(return_value=_ExecResult(uuid4()))\\n\\n    with pytest.raises(\\n        DeploymentGuardError,\\n        match=(\\n            r\\\"flow cannot be deleted because it has deployed versions\\\\. \\\"\\n            r\\\"Please remove its versions from deployments first\\\\.\\\"\\n        ),\\n    ):\\n        await cascade_delete_flow(session, flow_id)\\n    assert session.exec.await_count == 2\\n\\n\\n@pytest.mark.asyncio\\nasync def test_cascade_delete_flow_prunes_orphan_attachments_before_delete_statements():\\n    \\\"\\\"\\\"cascade_delete_flow should remove stale attachment rows before deleting flow rows.\\\"\\\"\\\"\\n    flow_id = uuid4()\\n\\n    session = AsyncMock()\\n    session.exec = AsyncMock(\\n        side_effect=[\\n            _ExecResult(None, rowcount=1),  # prune orphan attachments\\n            _ExecResult(None),  # live deployment attachment lookup\\n            _ExecResult(None),  # message delete\\n            _ExecResult(None),  # transaction delete\\n            _ExecResult(None),  # vertex_build delete\\n            _ExecResult(None),  # flow_version delete\\n            _ExecResult([]),  # trace id lookup\\n            _ExecResult(None),  # flow delete\\n        ]\\n    )\\n\\n    await cascade_delete_flow(session, flow_id)\\n\\n    assert session.exec.await_count == 8\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_flow_remaps_guard_error_to_flow_delete_message(monkeypatch):\\n    from langflow.api.v1.flows import delete_flow\\n\\n    flow_id = uuid4()\\n    user_id = uuid4()\\n\\n    fake_flow = SimpleNamespace(id=flow_id, user_id=user_id)\\n    monkeypatch.setattr(\\\"langflow.api.v1.flows._read_flow\\\", AsyncMock(return_value=fake_flow))\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.flows.retry_flow_operation_on_deployment_guard\\\",\\n        AsyncMock(\\n            side_effect=DeploymentGuardError(\\n                code=\\\"FLOW_HAS_DEPLOYED_VERSIONS\\\",\\n                technical_detail=(\\n                    \\\"DELETE flow_version blocked: dependent rows exist in flow_version_deployment_attachment \\\"\\n                    \\\"for the target flow.\\\"\\n                ),\\n                detail=(\\n                    \\\"This flow cannot be deleted because it has deployed versions. \\\"\\n                    \\\"Please remove its versions from deployments first.\\\"\\n                ),\\n            )\\n        ),\\n    )\\n\\n    with pytest.raises(\\n        DeploymentGuardError,\\n        match=(\\n            r\\\"cannot be deleted because it has deployed versions\\\\. \\\"\\n            r\\\"Please remove its versions from deployments first\\\\.\\\"\\n        ),\\n    ) as exc_info:\\n        await delete_flow(\\n            session=AsyncMock(),\\n            flow_id=flow_id,\\n            current_user=SimpleNamespace(id=user_id),\\n        )\\n\\n    assert exc_info.value.code == \\\"FLOW_HAS_DEPLOYED_VERSIONS\\\"\\n    assert \\\"DELETE flow_version blocked\\\" in exc_info.value.technical_detail\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_flow_translates_guard_error_from_flush(monkeypatch):\\n    \\\"\\\"\\\"update_flow must propagate DeploymentGuardError from guarded operations.\\\"\\\"\\\"\\n    from langflow.api.v1.flows import update_flow\\n    from langflow.services.database.models.flow.model import FlowUpdate\\n\\n    flow_id = uuid4()\\n    user_id = uuid4()\\n    folder_id = uuid4()\\n    new_folder_id = uuid4()\\n\\n    fake_flow = SimpleNamespace(\\n        id=flow_id,\\n        user_id=user_id,\\n        folder_id=folder_id,\\n        data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        fs_path=None,\\n        webhook=False,\\n        updated_at=None,\\n    )\\n\\n    monkeypatch.setattr(\\\"langflow.api.v1.flows._read_flow\\\", AsyncMock(return_value=fake_flow))\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.flows._patch_flow\\\",\\n        AsyncMock(\\n            side_effect=DeploymentGuardError(\\n                code=\\\"FLOW_DEPLOYED_IN_PROJECT\\\",\\n                technical_detail=(\\n                    \\\"Cannot move flow to a different project because it has versions deployed in the current project.\\\"\\n                ),\\n                detail=(\\n                    \\\"This flow cannot be moved to another project until its versions \\\"\\n                    \\\"are removed from deployments in its current project.\\\"\\n                ),\\n            )\\n        ),\\n    )\\n    monkeypatch.setattr(\\\"langflow.api.v1.mappers.deployments.sync.sync_flow_deployment_state\\\", AsyncMock())\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.flows.get_settings_service\\\",\\n        lambda: SimpleNamespace(settings=SimpleNamespace(remove_api_keys=False)),\\n    )\\n\\n    session = AsyncMock()\\n    session.exec = AsyncMock(return_value=_ExecResult(SimpleNamespace(id=new_folder_id)))\\n    session.add = AsyncMock()\\n    session.begin_nested = lambda: _AsyncNullContext()\\n\\n    flow_update = FlowUpdate(folder_id=new_folder_id)\\n\\n    with pytest.raises(\\n        DeploymentGuardError,\\n        match=(\\n            r\\\"cannot be moved to another project until its versions are \\\"\\n            r\\\"removed from deployments in its current project\\\"\\n        ),\\n    ):\\n        await update_flow(\\n            session=session,\\n            flow_id=flow_id,\\n            flow=flow_update,\\n            current_user=SimpleNamespace(id=user_id),\\n            storage_service=AsyncMock(),\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_multiple_flows_propagates_guard_error(monkeypatch):\\n    \\\"\\\"\\\"delete_multiple_flows must let DeploymentGuardError propagate to the caller.\\\"\\\"\\\"\\n    from langflow.api.v1.flows import delete_multiple_flows\\n\\n    flow_id = uuid4()\\n    user_id = uuid4()\\n\\n    fake_flow = SimpleNamespace(id=flow_id)\\n\\n    monkeypatch.setattr(\\n        \\\"langflow.api.v1.flows.cascade_delete_flow\\\",\\n        AsyncMock(\\n            side_effect=DeploymentGuardError(\\n                code=\\\"FLOW_HAS_DEPLOYED_VERSIONS\\\",\\n                technical_detail=(\\n                    \\\"DELETE flow_version blocked: dependent rows exist in flow_version_deployment_attachment \\\"\\n                    \\\"for the target flow.\\\"\\n                ),\\n                detail=(\\n                    \\\"This flow cannot be deleted because it has deployed versions. \\\"\\n                    \\\"Please remove its versions from deployments first.\\\"\\n                ),\\n            )\\n        ),\\n    )\\n    monkeypatch.setattr(\\\"langflow.api.v1.mappers.deployments.sync.sync_flow_deployment_state\\\", AsyncMock())\\n\\n    session = AsyncMock()\\n    session.exec = AsyncMock(return_value=_ExecResult([fake_flow]))\\n    session.begin_nested = lambda: _AsyncNullContext()\\n\\n    with pytest.raises(\\n        DeploymentGuardError,\\n        match=(\\n            r\\\"cannot be deleted because it has deployed versions\\\\. \\\"\\n            r\\\"Please remove its versions from deployments first\\\\.\\\"\\n        ),\\n    ):\\n        await delete_multiple_flows(\\n            flow_ids=[flow_id],\\n            user=SimpleNamespace(id=user_id),\\n            db=session,\\n        )\\n\\n\\n# \u2500\u2500 Global exception handler \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\n\\n\\n@pytest.mark.asyncio\\nasync def test_global_exception_handler_returns_409_for_deployment_guard_error():\\n    \\\"\\\"\\\"The global exception handler must convert DeploymentGuardError to a 409 Conflict response.\\\"\\\"\\\"\\n\\n    async def _handler(_request, exc: Exception):\\n        if isinstance(exc, DeploymentGuardError):\\n            return JSONResponse(\\n                status_code=HTTPStatus.CONFLICT,\\n                content={\\\"detail\\\": exc.detail},\\n            )\\n        return JSONResponse(status_code=500, content={\\\"message\\\": str(exc)})\\n\\n    app = FastAPI()\\n    app.add_exception_handler(DeploymentGuardError, _handler)\\n\\n    _detail = \\\"Cannot delete project because it contains deployments.\\\"\\n\\n    @app.get(\\\"/boom\\\")\\n    async def _boom():\\n        raise DeploymentGuardError(\\n            code=\\\"PROJECT_HAS_DEPLOYMENTS\\\",\\n            technical_detail=\\\"DELETE folder blocked: dependent rows exist in deployment for the target project.\\\",\\n            detail=_detail,\\n        )\\n\\n    async with AsyncClient(transport=ASGITransport(app=app), base_url=\\\"http://test\\\") as client:\\n        response = await client.get(\\\"/boom\\\")\\n\\n    assert response.status_code == 409\\n    body = response.json()\\n    assert body == {\\\"detail\\\": _detail}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/api/v1/test_openai_responses_error.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9be42583be40d127807d48fb959487dc8526140a1c3bcc8815792a5416484541\",\"content\":\"\\\"\\\"\\\"Test OpenAI Responses Error Handling.\\\"\\\"\\\"\\n\\nimport json\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom fastapi.testclient import TestClient\\nfrom langflow.main import create_app\\n\\n\\n@pytest.fixture\\ndef client():\\n    app = create_app()\\n    return TestClient(app)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_openai_response_stream_error_handling(client):\\n    \\\"\\\"\\\"Test that errors during streaming are correctly propagated to the client.\\n\\n    Ensure errors are propagated as OpenAI-compatible error responses.\\n    \\\"\\\"\\\"\\n    # Mock api_key_security dependency\\n    from langflow.services.auth.utils import api_key_security\\n    from langflow.services.database.models.user.model import UserRead\\n\\n    async def mock_api_key_security():\\n        from datetime import datetime, timezone\\n\\n        now = datetime.now(timezone.utc)\\n        return UserRead(\\n            id=\\\"00000000-0000-0000-0000-000000000000\\\",\\n            username=\\\"testuser\\\",\\n            is_active=True,\\n            is_superuser=False,\\n            create_at=now,\\n            updated_at=now,\\n            profile_image=None,\\n            store_api_key=None,\\n            last_login_at=None,\\n            optins=None,\\n        )\\n\\n    client.app.dependency_overrides[api_key_security] = mock_api_key_security\\n\\n    # Mock the flow execution to simulate an error during streaming\\n    with (\\n        patch(\\\"langflow.api.v1.openai_responses.get_flow_by_id_or_endpoint_name\\\") as mock_get_flow,\\n        patch(\\\"langflow.api.v1.openai_responses.run_flow_generator\\\") as _,\\n        patch(\\\"langflow.api.v1.openai_responses.consume_and_yield\\\") as mock_consume,\\n    ):\\n        # Setup mock flow\\n        mock_flow = MagicMock()\\n        mock_flow.data = {\\\"nodes\\\": [{\\\"data\\\": {\\\"type\\\": \\\"ChatInput\\\"}}, {\\\"data\\\": {\\\"type\\\": \\\"ChatOutput\\\"}}]}\\n        mock_get_flow.return_value = mock_flow\\n\\n        # We need to simulate the event manager queue behavior\\n        # The run_flow_generator in the actual code puts events into the event_manager\\n        # which puts them into the queue.\\n\\n        # Instead of mocking the complex event manager interaction, we can mock\\n        # consume_and_yield to yield our simulated error event\\n\\n        # Simulate an error event from the queue\\n        error_event = json.dumps({\\\"event\\\": \\\"error\\\", \\\"data\\\": {\\\"error\\\": \\\"Simulated streaming error\\\"}}).encode(\\\"utf-8\\\")\\n\\n        # Yield error event then None to end stream\\n        async def event_generator(*_, **__):\\n            yield error_event\\n            yield None\\n\\n        mock_consume.side_effect = event_generator\\n\\n        # Make the request\\n        response = client.post(\\n            \\\"/api/v1/responses\\\",\\n            json={\\\"model\\\": \\\"test-flow-id\\\", \\\"input\\\": \\\"test input\\\", \\\"stream\\\": True},\\n            headers={\\\"Authorization\\\": \\\"Bearer test-key\\\"},\\n        )\\n\\n        # Check response\\n        assert response.status_code == 200\\n        content = response.content.decode(\\\"utf-8\\\")\\n\\n        # Verify we got the error event in the stream\\n        assert (\\n            \\\"event: error\\\" not in content\\n        )  # OpenAI format doesn't use event: error for the data payload itself usually, but let's check the data\\n\\n        # We expect a data line with the error JSON\\n        # The fix implementation: yield f\\\"data: {json.dumps(error_response)}\\\\n\\\\n\\\"\\n\\n        expected_error_part = '\\\"message\\\": \\\"Simulated streaming error\\\"'\\n        assert expected_error_part in content\\n        assert '\\\"type\\\": \\\"processing_error\\\"' in content\\n\\n    # Clean up overrides\\n    client.app.dependency_overrides = {}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/services/database/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8c1d21302ccf8ea253b43f968b2b49469f0b9e01ad71e15f240d3807a7dfc917\",\"content\":\"\\\"\\\"\\\"Database tests package.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/services/database/models/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"da6ff829221c0589f7576a1ada3b45af6080d0918a3a7c158aa35c9362806e7e\",\"content\":\"\\\"\\\"\\\"Database models tests package.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/services/database/models/deployment/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/services/database/models/deployment/test_crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cd28ff015d57a4656b79df4a5aefe72e7be906f71eb5cf55c69755cd97adbbb2\",\"content\":\"from __future__ import annotations\\n\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.deployment.crud import (\\n    UNCONFIRMED_DELETE_ROWCOUNT,\\n    DeploymentMetadataUpdate,\\n    create_deployment,\\n    delete_deployment_by_id,\\n    delete_deployment_by_resource_key,\\n    delete_deployments_by_ids,\\n    get_deployment,\\n    list_deployments_page,\\n    update_deployment,\\n    update_deployment_metadata,\\n    update_deployment_metadata_batch,\\n)\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.deployment_provider_account.model import (\\n    DeploymentProviderAccount,\\n    DeploymentProviderKey,\\n)\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.flow_version.model import FlowVersion\\nfrom langflow.services.database.models.flow_version_deployment_attachment.model import (\\n    FlowVersionDeploymentAttachment,\\n)\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.user.model import User\\nfrom lfx.services.adapters.deployment.schema import DeploymentType\\nfrom sqlalchemy import event\\nfrom sqlalchemy.ext.asyncio import create_async_engine\\nfrom sqlalchemy.pool import StaticPool\\nfrom sqlmodel import SQLModel, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n_TEST_PASSWORD = \\\"hashed\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n\\n# ---------------------------------------------------------------------------\\n# Mock helper (for pure-validation tests that raise before touching DB)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _make_db() -> AsyncMock:\\n    db = AsyncMock()\\n    db.add = MagicMock()\\n    return db\\n\\n\\nclass _ExecResult:\\n    def __init__(self, rows):\\n        self._rows = rows\\n\\n    def all(self):\\n        return self._rows\\n\\n\\n# ---------------------------------------------------------------------------\\n# In-memory SQLite fixtures\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.fixture(name=\\\"db_engine\\\")\\ndef db_engine_fixture():\\n    engine = create_async_engine(\\n        \\\"sqlite+aiosqlite://\\\",\\n        connect_args={\\\"check_same_thread\\\": False},\\n        poolclass=StaticPool,\\n    )\\n\\n    @event.listens_for(engine.sync_engine, \\\"connect\\\")\\n    def _enable_fk(dbapi_connection, connection_record):  # noqa: ARG001\\n        cursor = dbapi_connection.cursor()\\n        cursor.execute(\\\"PRAGMA foreign_keys=ON\\\")\\n        cursor.close()\\n\\n    return engine\\n\\n\\n@pytest.fixture(name=\\\"db\\\")\\nasync def db_fixture(db_engine):\\n    async with db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.create_all)\\n    async with AsyncSession(db_engine, expire_on_commit=False) as session:\\n        yield session\\n    async with db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.drop_all)\\n    await db_engine.dispose()\\n\\n\\n@pytest.fixture\\nasync def user(db: AsyncSession) -> User:\\n    u = User(username=\\\"testuser\\\", password=_TEST_PASSWORD, is_active=True)\\n    db.add(u)\\n    await db.commit()\\n    await db.refresh(u)\\n    return u\\n\\n\\n@pytest.fixture\\nasync def folder(db: AsyncSession, user: User) -> Folder:\\n    f = Folder(name=\\\"test-project\\\", user_id=user.id)\\n    db.add(f)\\n    await db.commit()\\n    await db.refresh(f)\\n    return f\\n\\n\\n@pytest.fixture\\nasync def provider_account(db: AsyncSession, user: User) -> DeploymentProviderAccount:\\n    acct = DeploymentProviderAccount(\\n        user_id=user.id,\\n        provider_tenant_id=\\\"tenant-1\\\",\\n        provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n        name=\\\"provider-1\\\",\\n        provider_url=\\\"https://provider.example.com\\\",\\n        api_key=\\\"encrypted-value\\\",  # pragma: allowlist secret\\n    )\\n    db.add(acct)\\n    await db.commit()\\n    await db.refresh(acct)\\n    return acct\\n\\n\\n# ---------------------------------------------------------------------------\\n# Pure-validation tests (raise before any DB call)\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_deployment_empty_resource_key_raises():\\n    db = _make_db()\\n    with pytest.raises(ValueError, match=\\\"resource_key must not be empty\\\"):\\n        await create_deployment(\\n            db,\\n            user_id=uuid4(),\\n            project_id=uuid4(),\\n            deployment_provider_account_id=uuid4(),\\n            resource_key=\\\"   \\\",\\n            display_name=\\\"my-deploy\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_deployment_empty_display_name_raises():\\n    db = _make_db()\\n    with pytest.raises(ValueError, match=\\\"display_name must not be empty\\\"):\\n        await create_deployment(\\n            db,\\n            user_id=uuid4(),\\n            project_id=uuid4(),\\n            deployment_provider_account_id=uuid4(),\\n            resource_key=\\\"rk-1\\\",\\n            display_name=\\\"\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_deployment_invalid_uuid_raises():\\n    db = _make_db()\\n    with pytest.raises(ValueError, match=\\\"deployment_id is not a valid UUID\\\"):\\n        await get_deployment(db, user_id=uuid4(), deployment_id=\\\"not-a-uuid\\\")\\n\\n\\n@pytest.mark.asyncio\\nasync def test_list_deployments_page_negative_offset_raises():\\n    db = _make_db()\\n    with pytest.raises(ValueError, match=\\\"offset must be greater than or equal to 0\\\"):\\n        await list_deployments_page(\\n            db,\\n            user_id=uuid4(),\\n            row_owner_id=uuid4(),\\n            deployment_provider_account_id=uuid4(),\\n            offset=-1,\\n            limit=10,\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_list_deployments_page_zero_limit_raises():\\n    db = _make_db()\\n    with pytest.raises(ValueError, match=\\\"limit must be greater than 0\\\"):\\n        await list_deployments_page(\\n            db,\\n            user_id=uuid4(),\\n            row_owner_id=uuid4(),\\n            deployment_provider_account_id=uuid4(),\\n            offset=0,\\n            limit=0,\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_list_deployments_page_negative_limit_raises():\\n    db = _make_db()\\n    with pytest.raises(ValueError, match=\\\"limit must be greater than 0\\\"):\\n        await list_deployments_page(\\n            db,\\n            user_id=uuid4(),\\n            row_owner_id=uuid4(),\\n            deployment_provider_account_id=uuid4(),\\n            offset=0,\\n            limit=-5,\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_list_deployments_page_attachment_count_only_counts_live_flow_versions():\\n    db = _make_db()\\n    db.exec = AsyncMock(return_value=_ExecResult([]))\\n    await list_deployments_page(\\n        db,\\n        user_id=uuid4(),\\n        row_owner_id=uuid4(),\\n        deployment_provider_account_id=uuid4(),\\n        offset=0,\\n        limit=20,\\n    )\\n\\n    # String-match on compiled SQL because these tests use mocked sessions.\\n    statement_text = str(db.exec.await_args.args[0]).lower()\\n    assert \\\"join flow_version\\\" in statement_text\\n    assert \\\"flow_version_deployment_attachment.user_id\\\" in statement_text\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_deployment_empty_display_name_raises():\\n    db = _make_db()\\n    deploy = MagicMock()\\n    with pytest.raises(ValueError, match=\\\"display_name must not be empty\\\"):\\n        await update_deployment(db, deployment=deploy, display_name=\\\"   \\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Mock-based tests (can't trigger with real SQLite)\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_by_resource_key_none_rowcount_returns_unconfirmed():\\n    db = _make_db()\\n    lookup_result = MagicMock()\\n    lookup_result.first.return_value = uuid4()\\n    attachment_delete_result = MagicMock()\\n    attachment_delete_result.rowcount = 3\\n    mock_result = MagicMock()\\n    mock_result.rowcount = None\\n    db.exec.side_effect = [lookup_result, attachment_delete_result, mock_result]\\n\\n    with patch(\\\"langflow.services.database.models.deployment.crud.logger\\\") as mock_logger:\\n        mock_logger.aerror = AsyncMock()\\n        count = await delete_deployment_by_resource_key(\\n            db,\\n            user_id=uuid4(),\\n            deployment_provider_account_id=uuid4(),\\n            resource_key=\\\"rk-1\\\",\\n        )\\n\\n    assert count is UNCONFIRMED_DELETE_ROWCOUNT\\n    assert db.exec.await_count == 3\\n    lookup_stmt = str(db.exec.await_args_list[0].args[0]).lower()\\n    attachment_stmt = str(db.exec.await_args_list[1].args[0]).lower()\\n    deployment_stmt = str(db.exec.await_args_list[2].args[0]).lower()\\n    assert \\\"select deployment.id\\\" in lookup_stmt\\n    assert \\\"delete from flow_version_deployment_attachment\\\" in attachment_stmt\\n    assert \\\"delete from deployment\\\" in deployment_stmt\\n    mock_logger.aerror.assert_awaited_once()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_by_resource_key_missing_row_skips_attachment_delete():\\n    db = _make_db()\\n    lookup_result = MagicMock()\\n    lookup_result.first.return_value = None\\n    deployment_delete_result = MagicMock()\\n    deployment_delete_result.rowcount = 0\\n    db.exec.side_effect = [lookup_result, deployment_delete_result]\\n\\n    with patch(\\\"langflow.services.database.models.deployment.crud.logger\\\") as mock_logger:\\n        mock_logger.aerror = AsyncMock()\\n        count = await delete_deployment_by_resource_key(\\n            db,\\n            user_id=uuid4(),\\n            deployment_provider_account_id=uuid4(),\\n            resource_key=\\\"rk-missing\\\",\\n        )\\n\\n    assert count == 0\\n    assert db.exec.await_count == 2\\n    lookup_stmt = str(db.exec.await_args_list[0].args[0]).lower()\\n    deployment_stmt = str(db.exec.await_args_list[1].args[0]).lower()\\n    assert \\\"select deployment.id\\\" in lookup_stmt\\n    assert \\\"delete from deployment\\\" in deployment_stmt\\n    assert \\\"flow_version_deployment_attachment\\\" not in deployment_stmt\\n    mock_logger.aerror.assert_not_awaited()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_by_id_none_rowcount_returns_unconfirmed():\\n    db = _make_db()\\n    attachment_delete_result = MagicMock()\\n    attachment_delete_result.rowcount = 1\\n    mock_result = MagicMock()\\n    mock_result.rowcount = None\\n    db.exec.side_effect = [attachment_delete_result, mock_result]\\n\\n    with patch(\\\"langflow.services.database.models.deployment.crud.logger\\\") as mock_logger:\\n        mock_logger.aerror = AsyncMock()\\n        count = await delete_deployment_by_id(\\n            db,\\n            user_id=uuid4(),\\n            deployment_id=uuid4(),\\n        )\\n\\n    assert count is UNCONFIRMED_DELETE_ROWCOUNT\\n    assert db.exec.await_count == 2\\n    attachment_stmt = str(db.exec.await_args_list[0].args[0]).lower()\\n    deployment_stmt = str(db.exec.await_args_list[1].args[0]).lower()\\n    assert \\\"delete from flow_version_deployment_attachment\\\" in attachment_stmt\\n    assert \\\"delete from deployment\\\" in deployment_stmt\\n    mock_logger.aerror.assert_awaited_once()\\n\\n\\nasync def test_delete_by_id_negative_rowcount_returns_unconfirmed():\\n    \\\"\\\"\\\"PEP 249 / SQLAlchemy use -1 when the driver did not determine rowcount.\\\"\\\"\\\"\\n    db = _make_db()\\n    attachment_delete_result = MagicMock()\\n    attachment_delete_result.rowcount = 1\\n    mock_result = MagicMock()\\n    mock_result.rowcount = -1\\n    db.exec.side_effect = [attachment_delete_result, mock_result]\\n\\n    with patch(\\\"langflow.services.database.models.deployment.crud.logger\\\") as mock_logger:\\n        mock_logger.aerror = AsyncMock()\\n        count = await delete_deployment_by_id(\\n            db,\\n            user_id=uuid4(),\\n            deployment_id=uuid4(),\\n        )\\n\\n    assert count is UNCONFIRMED_DELETE_ROWCOUNT\\n    mock_logger.aerror.assert_awaited_once()\\n\\n\\n# ---------------------------------------------------------------------------\\n# FK-disabled safety test (real SQLite, FK off)\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_by_id_prunes_attachments_when_fk_disabled():\\n    engine = create_async_engine(\\n        \\\"sqlite+aiosqlite://\\\",\\n        connect_args={\\\"check_same_thread\\\": False},\\n        poolclass=StaticPool,\\n    )\\n\\n    @event.listens_for(engine.sync_engine, \\\"connect\\\")\\n    def _disable_fk(dbapi_connection, connection_record):  # noqa: ARG001\\n        cursor = dbapi_connection.cursor()\\n        cursor.execute(\\\"PRAGMA foreign_keys=OFF\\\")\\n        cursor.close()\\n\\n    async with engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.create_all)\\n\\n    async with AsyncSession(engine, expire_on_commit=False) as db:\\n        user = User(username=\\\"fk-off-user\\\", password=_TEST_PASSWORD, is_active=True)\\n        db.add(user)\\n        await db.flush()\\n\\n        folder = Folder(name=\\\"fk-off-folder\\\", user_id=user.id)\\n        db.add(folder)\\n        await db.flush()\\n\\n        provider_account = DeploymentProviderAccount(\\n            user_id=user.id,\\n            provider_tenant_id=\\\"tenant-fk-off\\\",\\n            provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            name=\\\"provider-fk-off\\\",\\n            provider_url=\\\"https://provider-fk-off.example.com\\\",\\n            api_key=\\\"encrypted-value\\\",  # pragma: allowlist secret\\n        )\\n        db.add(provider_account)\\n        await db.flush()\\n\\n        deployment = Deployment(\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-fk-off\\\",\\n            display_name=\\\"deployment-fk-off\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        db.add(deployment)\\n        await db.flush()\\n\\n        flow = Flow(\\n            name=\\\"flow-fk-off\\\",\\n            user_id=user.id,\\n            folder_id=folder.id,\\n            data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        )\\n        db.add(flow)\\n        await db.flush()\\n\\n        flow_version = FlowVersion(\\n            flow_id=flow.id,\\n            user_id=user.id,\\n            version_number=1,\\n            data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        )\\n        db.add(flow_version)\\n        await db.flush()\\n\\n        attachment = FlowVersionDeploymentAttachment(\\n            user_id=user.id,\\n            flow_version_id=flow_version.id,\\n            deployment_id=deployment.id,\\n            provider_snapshot_id=\\\"snapshot-fk-off\\\",\\n        )\\n        db.add(attachment)\\n        await db.commit()\\n\\n        deleted = await delete_deployment_by_id(db, user_id=user.id, deployment_id=deployment.id)\\n        await db.commit()\\n        assert deleted == 1\\n\\n        deployment_row = (await db.exec(select(Deployment).where(Deployment.id == deployment.id))).first()\\n        attachment_row = (\\n            await db.exec(\\n                select(FlowVersionDeploymentAttachment).where(\\n                    FlowVersionDeploymentAttachment.deployment_id == deployment.id\\n                )\\n            )\\n        ).first()\\n        assert deployment_row is None\\n        assert attachment_row is None\\n\\n    async with engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.drop_all)\\n    await engine.dispose()\\n\\n\\n# ---------------------------------------------------------------------------\\n# In-memory SQLite tests\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_deployment_preserves_display_name_whitespace_and_strips_resource_key(\\n    db: AsyncSession, user: User, folder: Folder, provider_account: DeploymentProviderAccount\\n):\\n    assert folder.id is not None\\n    row = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"  rk-1  \\\",\\n        display_name=\\\"  my-deploy  \\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    await db.commit()\\n\\n    fetched = await get_deployment(db, user_id=user.id, deployment_id=row.id)\\n    assert fetched is not None\\n    assert fetched.resource_key == \\\"rk-1\\\"\\n    assert fetched.display_name == \\\"  my-deploy  \\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_deployment_preserves_display_name_whitespace(\\n    db: AsyncSession, user: User, folder: Folder, provider_account: DeploymentProviderAccount\\n):\\n    assert folder.id is not None\\n    row = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-1\\\",\\n        display_name=\\\"original\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    await db.commit()\\n\\n    updated = await update_deployment(db, deployment=row, display_name=\\\"  new-name  \\\")\\n    await db.commit()\\n\\n    fetched = await get_deployment(db, user_id=user.id, deployment_id=updated.id)\\n    assert fetched is not None\\n    assert fetched.display_name == \\\"  new-name  \\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_deployment_metadata_preserves_updated_at(\\n    db: AsyncSession, user: User, folder: Folder, provider_account: DeploymentProviderAccount\\n):\\n    row = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-metadata-sync\\\",\\n        display_name=\\\"original\\\",\\n        description=\\\"old desc\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    await db.commit()\\n    await db.refresh(row)\\n    original_updated_at = row.updated_at\\n\\n    updated = await update_deployment_metadata(\\n        db,\\n        user_id=user.id,\\n        deployment=row,\\n        display_name=\\\"provider name\\\",\\n        description=\\\"provider desc\\\",\\n    )\\n    assert updated is row\\n    assert row.display_name == \\\"provider name\\\"\\n    assert row.description == \\\"provider desc\\\"\\n    await db.commit()\\n\\n    fetched = await get_deployment(db, user_id=user.id, deployment_id=row.id)\\n    assert fetched is not None\\n    assert fetched.display_name == \\\"provider name\\\"\\n    assert fetched.description == \\\"provider desc\\\"\\n    assert fetched.updated_at == original_updated_at\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_deployment_metadata_skips_when_provider_description_is_unchanged(\\n    db: AsyncSession, user: User, folder: Folder, provider_account: DeploymentProviderAccount\\n):\\n    description = \\\"x\\\" * 501\\n    row = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-metadata-noop\\\",\\n        display_name=\\\"original\\\",\\n        description=description,\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    await db.commit()\\n    await db.refresh(row)\\n\\n    with patch.object(db, \\\"exec\\\", wraps=db.exec) as mock_exec:\\n        updated = await update_deployment_metadata(\\n            db,\\n            user_id=user.id,\\n            deployment=row,\\n            display_name=\\\"original\\\",\\n            description=description,\\n        )\\n\\n    assert updated is row\\n    mock_exec.assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_deployment_metadata_batch_writes_changed_rows_only(\\n    db: AsyncSession, user: User, folder: Folder, provider_account: DeploymentProviderAccount\\n):\\n    changed_row = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-metadata-batch-changed\\\",\\n        display_name=\\\"changed\\\",\\n        description=\\\"old desc\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    unchanged_row = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-metadata-batch-unchanged\\\",\\n        display_name=\\\"unchanged\\\",\\n        description=\\\"same desc\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    await db.commit()\\n    await db.refresh(changed_row)\\n    await db.refresh(unchanged_row)\\n\\n    await update_deployment_metadata_batch(\\n        db,\\n        deployment_updates=[\\n            DeploymentMetadataUpdate(\\n                langflow_db_row=changed_row,\\n                display_name=\\\"provider changed\\\",\\n                description=\\\"new desc\\\",\\n            ),\\n            DeploymentMetadataUpdate(\\n                langflow_db_row=unchanged_row,\\n                display_name=\\\"unchanged\\\",\\n                description=\\\"same desc\\\",\\n            ),\\n        ],\\n    )\\n    await db.refresh(changed_row)\\n    await db.refresh(unchanged_row)\\n    assert changed_row.display_name == \\\"provider changed\\\"\\n    assert changed_row.description == \\\"new desc\\\"\\n    assert unchanged_row.display_name == \\\"unchanged\\\"\\n    assert unchanged_row.description == \\\"same desc\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_deployment_metadata_rejects_actor_user_id(\\n    db: AsyncSession, user: User, folder: Folder, provider_account: DeploymentProviderAccount\\n):\\n    row = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-metadata-owner\\\",\\n        display_name=\\\"original\\\",\\n        description=\\\"old desc\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    await db.commit()\\n\\n    with pytest.raises(ValueError, match=\\\"deployment owner\\\"):\\n        await update_deployment_metadata(\\n            db,\\n            user_id=uuid4(),\\n            deployment=row,\\n            display_name=\\\"provider name\\\",\\n            description=\\\"provider desc\\\",\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_deployment_metadata_batch_matches_owner_per_row(\\n    db: AsyncSession,\\n    user: User,\\n    folder: Folder,\\n    provider_account: DeploymentProviderAccount,\\n):\\n    other_user = User(username=f\\\"other-{uuid4()}\\\", password=_TEST_PASSWORD, is_active=True)\\n    db.add(other_user)\\n    await db.flush()\\n    owner_row = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-metadata-owner-row\\\",\\n        display_name=\\\"owner\\\",\\n        description=\\\"owner desc\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    other_row = Deployment(\\n        user_id=other_user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-metadata-other-row\\\",\\n        display_name=\\\"other\\\",\\n        description=\\\"other desc\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    db.add(other_row)\\n    await db.commit()\\n    await db.refresh(owner_row)\\n    await db.refresh(other_row)\\n\\n    await update_deployment_metadata_batch(\\n        db,\\n        deployment_updates=[\\n            DeploymentMetadataUpdate(\\n                langflow_db_row=owner_row,\\n                display_name=\\\"owner synced\\\",\\n                description=\\\"owner synced desc\\\",\\n            ),\\n            DeploymentMetadataUpdate(\\n                langflow_db_row=other_row,\\n                display_name=\\\"other synced\\\",\\n                description=\\\"other synced desc\\\",\\n            ),\\n        ],\\n    )\\n    await db.refresh(owner_row)\\n    await db.refresh(other_row)\\n    assert owner_row.display_name == \\\"owner synced\\\"\\n    assert other_row.display_name == \\\"other synced\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_by_id_removes_attached_rows_with_fk_on(\\n    db: AsyncSession, user: User, folder: Folder, provider_account: DeploymentProviderAccount\\n):\\n    flow = Flow(name=\\\"flow-del-id\\\", user_id=user.id, folder_id=folder.id, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n    db.add(flow)\\n    await db.flush()\\n\\n    flow_version_1 = FlowVersion(flow_id=flow.id, user_id=user.id, version_number=1, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n    flow_version_2 = FlowVersion(flow_id=flow.id, user_id=user.id, version_number=2, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n    db.add_all([flow_version_1, flow_version_2])\\n    await db.flush()\\n\\n    deployment = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-delete-id\\\",\\n        display_name=\\\"delete-id\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    await db.flush()\\n\\n    db.add_all(\\n        [\\n            FlowVersionDeploymentAttachment(\\n                user_id=user.id,\\n                flow_version_id=flow_version_1.id,\\n                deployment_id=deployment.id,\\n                provider_snapshot_id=\\\"snap-del-id-1\\\",\\n            ),\\n            FlowVersionDeploymentAttachment(\\n                user_id=user.id,\\n                flow_version_id=flow_version_2.id,\\n                deployment_id=deployment.id,\\n                provider_snapshot_id=\\\"snap-del-id-2\\\",\\n            ),\\n        ]\\n    )\\n    await db.commit()\\n\\n    deleted = await delete_deployment_by_id(db, user_id=user.id, deployment_id=deployment.id)\\n    await db.commit()\\n    assert deleted == 1\\n\\n    deployment_row = (await db.exec(select(Deployment).where(Deployment.id == deployment.id))).first()\\n    attachment_rows = (\\n        await db.exec(\\n            select(FlowVersionDeploymentAttachment).where(\\n                FlowVersionDeploymentAttachment.deployment_id == deployment.id\\n            )\\n        )\\n    ).all()\\n    assert deployment_row is None\\n    assert attachment_rows == []\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_by_ids_removes_multiple_deployments_and_attached_rows(\\n    db: AsyncSession, user: User, folder: Folder, provider_account: DeploymentProviderAccount\\n):\\n    flow = Flow(name=\\\"flow-del-ids\\\", user_id=user.id, folder_id=folder.id, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n    db.add(flow)\\n    await db.flush()\\n\\n    flow_version_1 = FlowVersion(flow_id=flow.id, user_id=user.id, version_number=1, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n    flow_version_2 = FlowVersion(flow_id=flow.id, user_id=user.id, version_number=2, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n    db.add_all([flow_version_1, flow_version_2])\\n    await db.flush()\\n\\n    deployment_1 = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-delete-ids-1\\\",\\n        display_name=\\\"delete-ids-1\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    deployment_2 = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-delete-ids-2\\\",\\n        display_name=\\\"delete-ids-2\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    await db.flush()\\n\\n    db.add_all(\\n        [\\n            FlowVersionDeploymentAttachment(\\n                user_id=user.id,\\n                flow_version_id=flow_version_1.id,\\n                deployment_id=deployment_1.id,\\n                provider_snapshot_id=\\\"snap-del-ids-1\\\",\\n            ),\\n            FlowVersionDeploymentAttachment(\\n                user_id=user.id,\\n                flow_version_id=flow_version_2.id,\\n                deployment_id=deployment_2.id,\\n                provider_snapshot_id=\\\"snap-del-ids-2\\\",\\n            ),\\n        ]\\n    )\\n    await db.commit()\\n\\n    deleted = await delete_deployments_by_ids(\\n        db,\\n        user_id=user.id,\\n        deployment_ids=[deployment_1.id, deployment_2.id],\\n    )\\n    await db.commit()\\n    assert deleted == 2\\n\\n    deployment_rows = (\\n        await db.exec(select(Deployment).where(Deployment.id.in_([deployment_1.id, deployment_2.id])))\\n    ).all()\\n    attachment_rows = (\\n        await db.exec(\\n            select(FlowVersionDeploymentAttachment).where(\\n                FlowVersionDeploymentAttachment.deployment_id.in_([deployment_1.id, deployment_2.id])\\n            )\\n        )\\n    ).all()\\n    assert deployment_rows == []\\n    assert attachment_rows == []\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_by_resource_key_removes_attached_rows_with_fk_on(\\n    db: AsyncSession, user: User, folder: Folder, provider_account: DeploymentProviderAccount\\n):\\n    flow = Flow(name=\\\"flow-del-rk\\\", user_id=user.id, folder_id=folder.id, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n    db.add(flow)\\n    await db.flush()\\n\\n    flow_version = FlowVersion(flow_id=flow.id, user_id=user.id, version_number=1, data={\\\"nodes\\\": [], \\\"edges\\\": []})\\n    db.add(flow_version)\\n    await db.flush()\\n\\n    deployment = await create_deployment(\\n        db,\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-delete-rk\\\",\\n        display_name=\\\"delete-rk\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    await db.flush()\\n\\n    db.add(\\n        FlowVersionDeploymentAttachment(\\n            user_id=user.id,\\n            flow_version_id=flow_version.id,\\n            deployment_id=deployment.id,\\n            provider_snapshot_id=\\\"snap-del-rk-1\\\",\\n        )\\n    )\\n    await db.commit()\\n\\n    deleted = await delete_deployment_by_resource_key(\\n        db,\\n        user_id=user.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-delete-rk\\\",\\n    )\\n    await db.commit()\\n    assert deleted == 1\\n\\n    deployment_row = (await db.exec(select(Deployment).where(Deployment.id == deployment.id))).first()\\n    attachment_rows = (\\n        await db.exec(\\n            select(FlowVersionDeploymentAttachment).where(\\n                FlowVersionDeploymentAttachment.deployment_id == deployment.id\\n            )\\n        )\\n    ).all()\\n    assert deployment_row is None\\n    assert attachment_rows == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/services/database/models/deployment/test_deployment_guard_triggers.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b9402d199da4ecd40386835392ac00009c849db29ba8aa58441165ed923b5d1a\",\"content\":\"from __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING, cast\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.deployment.crud import update_deployment\\nfrom langflow.services.database.models.deployment.exceptions import DeploymentGuardError\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.deployment.orm_guards import (\\n    ensure_attachment_project_match,\\n    ensure_deployment_immutable_fields,\\n    ensure_flow_move_allowed,\\n    ensure_flow_moves_allowed,\\n    ensure_provider_account_identity_immutable,\\n)\\nfrom langflow.services.database.models.deployment_provider_account.crud import update_provider_account\\nfrom langflow.services.database.models.deployment_provider_account.model import (\\n    DeploymentProviderAccount,\\n    DeploymentProviderKey,\\n)\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.flow_version.model import FlowVersion\\nfrom langflow.services.database.models.flow_version_deployment_attachment.crud import create_deployment_attachment\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.user.model import User\\nfrom lfx.services.adapters.deployment.schema import DeploymentType\\nfrom sqlalchemy import event\\nfrom sqlalchemy.ext.asyncio import create_async_engine\\nfrom sqlalchemy.pool import StaticPool\\nfrom sqlmodel import SQLModel\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nif TYPE_CHECKING:\\n    from sqlalchemy.ext.asyncio import AsyncEngine\\n\\n_TEST_PASSWORD = \\\"hashed\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n\\ndef _utcnow_naive() -> datetime:\\n    return datetime.now(timezone.utc).replace(tzinfo=None)\\n\\n\\ndef _create_sqlite_engine() -> AsyncEngine:\\n    engine = create_async_engine(\\n        \\\"sqlite+aiosqlite://\\\",\\n        connect_args={\\\"check_same_thread\\\": False},\\n        poolclass=StaticPool,\\n    )\\n\\n    @event.listens_for(engine.sync_engine, \\\"connect\\\")\\n    def _enable_fk(dbapi_connection, _connection_record):\\n        cursor = dbapi_connection.cursor()\\n        cursor.execute(\\\"PRAGMA foreign_keys=ON\\\")\\n        cursor.close()\\n\\n    return engine\\n\\n\\n@pytest.fixture(name=\\\"db_engine\\\")\\ndef db_engine_fixture():\\n    return _create_sqlite_engine()\\n\\n\\n@pytest.fixture(name=\\\"db\\\")\\nasync def db_fixture(db_engine):\\n    async with db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.create_all)\\n    async with AsyncSession(db_engine, expire_on_commit=False) as session:\\n        yield session\\n    async with db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.drop_all)\\n    await db_engine.dispose()\\n\\n\\n@pytest.fixture\\nasync def user(db: AsyncSession) -> User:\\n    now = _utcnow_naive()\\n    row = User(username=\\\"testuser\\\", password=_TEST_PASSWORD, is_active=True, create_at=now, updated_at=now)\\n    db.add(row)\\n    await db.commit()\\n    await db.refresh(row)\\n    return row\\n\\n\\n@pytest.fixture\\nasync def source_project(db: AsyncSession, user: User) -> Folder:\\n    row = Folder(name=\\\"source-project\\\", user_id=user.id)\\n    db.add(row)\\n    await db.commit()\\n    await db.refresh(row)\\n    return row\\n\\n\\n@pytest.fixture\\nasync def target_project(db: AsyncSession, user: User) -> Folder:\\n    row = Folder(name=\\\"target-project\\\", user_id=user.id)\\n    db.add(row)\\n    await db.commit()\\n    await db.refresh(row)\\n    return row\\n\\n\\n@pytest.fixture\\nasync def flow(db: AsyncSession, user: User, source_project: Folder) -> Flow:\\n    row = Flow(\\n        name=\\\"flow-1\\\",\\n        user_id=user.id,\\n        folder_id=source_project.id,\\n        data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        updated_at=_utcnow_naive(),\\n    )\\n    db.add(row)\\n    await db.commit()\\n    await db.refresh(row)\\n    return row\\n\\n\\n@pytest.fixture\\nasync def flow_version(db: AsyncSession, user: User, flow: Flow) -> FlowVersion:\\n    row = FlowVersion(\\n        flow_id=flow.id,\\n        user_id=user.id,\\n        version_number=1,\\n        data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n    )\\n    db.add(row)\\n    await db.commit()\\n    await db.refresh(row)\\n    return row\\n\\n\\n@pytest.fixture\\nasync def provider_account(db: AsyncSession, user: User) -> DeploymentProviderAccount:\\n    row = DeploymentProviderAccount(\\n        user_id=user.id,\\n        provider_tenant_id=\\\"tenant-1\\\",\\n        provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n        name=\\\"provider-1\\\",\\n        provider_url=\\\"https://provider-1.example.com\\\",\\n        api_key=\\\"encrypted-value\\\",  # pragma: allowlist secret\\n    )\\n    db.add(row)\\n    await db.commit()\\n    await db.refresh(row)\\n    return row\\n\\n\\n@pytest.fixture\\nasync def deployment(\\n    db: AsyncSession,\\n    user: User,\\n    source_project: Folder,\\n    provider_account: DeploymentProviderAccount,\\n) -> Deployment:\\n    row = Deployment(\\n        user_id=user.id,\\n        project_id=source_project.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-1\\\",\\n        display_name=\\\"deployment-1\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    db.add(row)\\n    await db.commit()\\n    await db.refresh(row)\\n    return row\\n\\n\\n@pytest.mark.asyncio\\nasync def test_flow_move_guard_allows_noop(db: AsyncSession, flow: Flow) -> None:\\n    await ensure_flow_move_allowed(\\n        db,\\n        flow_id=flow.id,\\n        old_folder_id=flow.folder_id,\\n        new_folder_id=flow.folder_id,\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_flow_move_guard_blocks_when_flow_is_deployed(\\n    db: AsyncSession,\\n    user: User,\\n    flow: Flow,\\n    flow_version: FlowVersion,\\n    deployment: Deployment,\\n    target_project: Folder,\\n) -> None:\\n    _ = target_project\\n    await create_deployment_attachment(\\n        db,\\n        user_id=user.id,\\n        flow_version_id=flow_version.id,\\n        deployment_id=deployment.id,\\n        provider_snapshot_id=\\\"snapshot-1\\\",\\n    )\\n    await db.commit()\\n\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        await ensure_flow_move_allowed(\\n            db,\\n            flow_id=flow.id,\\n            old_folder_id=flow.folder_id,\\n            new_folder_id=target_project.id,\\n        )\\n\\n    assert exc_info.value.code == \\\"FLOW_DEPLOYED_IN_PROJECT\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_flow_moves_guard_allows_empty_batch(db: AsyncSession, target_project: Folder) -> None:\\n    await ensure_flow_moves_allowed(\\n        db,\\n        flow_folder_pairs=[],\\n        new_folder_id=target_project.id,\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_flow_moves_guard_allows_when_all_moves_are_noop(db: AsyncSession, flow: Flow) -> None:\\n    await ensure_flow_moves_allowed(\\n        db,\\n        flow_folder_pairs=[(flow.id, flow.folder_id)],\\n        new_folder_id=flow.folder_id,\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_flow_moves_guard_blocks_when_any_group_has_deployed_flow(\\n    db: AsyncSession,\\n    user: User,\\n    flow: Flow,\\n    flow_version: FlowVersion,\\n    deployment: Deployment,\\n    target_project: Folder,\\n) -> None:\\n    other_source_project = Folder(name=\\\"source-project-2\\\", user_id=user.id)\\n    db.add(other_source_project)\\n    await db.commit()\\n    await db.refresh(other_source_project)\\n\\n    undeployed_flow = Flow(\\n        name=\\\"flow-2\\\",\\n        user_id=user.id,\\n        folder_id=other_source_project.id,\\n        data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        updated_at=_utcnow_naive(),\\n    )\\n    db.add(undeployed_flow)\\n    await db.commit()\\n    await db.refresh(undeployed_flow)\\n\\n    undeployed_flow_version = FlowVersion(\\n        flow_id=undeployed_flow.id,\\n        user_id=user.id,\\n        version_number=1,\\n        data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n    )\\n    db.add(undeployed_flow_version)\\n    await db.commit()\\n    await db.refresh(undeployed_flow_version)\\n\\n    await create_deployment_attachment(\\n        db,\\n        user_id=user.id,\\n        flow_version_id=flow_version.id,\\n        deployment_id=deployment.id,\\n        provider_snapshot_id=\\\"snapshot-batch\\\",\\n    )\\n    await db.commit()\\n\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        await ensure_flow_moves_allowed(\\n            db,\\n            flow_folder_pairs=[\\n                (flow.id, flow.folder_id),\\n                (undeployed_flow.id, undeployed_flow.folder_id),\\n            ],\\n            new_folder_id=target_project.id,\\n        )\\n\\n    assert exc_info.value.code == \\\"FLOW_DEPLOYED_IN_PROJECT\\\"\\n\\n\\ndef test_deployment_immutable_field_guard_blocks_project_move(deployment: Deployment, target_project: Folder) -> None:\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        ensure_deployment_immutable_fields(\\n            old_project_id=deployment.project_id,\\n            new_project_id=target_project.id,\\n            old_deployment_type=deployment.deployment_type,\\n            new_deployment_type=deployment.deployment_type,\\n            old_resource_key=deployment.resource_key,\\n            new_resource_key=deployment.resource_key,\\n            old_provider_account_id=deployment.deployment_provider_account_id,\\n            new_provider_account_id=deployment.deployment_provider_account_id,\\n        )\\n\\n    assert exc_info.value.code == \\\"DEPLOYMENT_PROJECT_MOVE\\\"\\n\\n\\ndef test_deployment_immutable_field_guard_blocks_type_update(deployment: Deployment) -> None:\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        ensure_deployment_immutable_fields(\\n            old_project_id=deployment.project_id,\\n            new_project_id=deployment.project_id,\\n            old_deployment_type=deployment.deployment_type,\\n            new_deployment_type=cast(\\\"DeploymentType\\\", \\\"changed-type\\\"),\\n            old_resource_key=deployment.resource_key,\\n            new_resource_key=deployment.resource_key,\\n            old_provider_account_id=deployment.deployment_provider_account_id,\\n            new_provider_account_id=deployment.deployment_provider_account_id,\\n        )\\n\\n    assert exc_info.value.code == \\\"DEPLOYMENT_TYPE_UPDATE\\\"\\n\\n\\ndef test_deployment_immutable_field_guard_blocks_resource_key_update(deployment: Deployment) -> None:\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        ensure_deployment_immutable_fields(\\n            old_project_id=deployment.project_id,\\n            new_project_id=deployment.project_id,\\n            old_deployment_type=deployment.deployment_type,\\n            new_deployment_type=deployment.deployment_type,\\n            old_resource_key=deployment.resource_key,\\n            new_resource_key=\\\"rk-updated\\\",\\n            old_provider_account_id=deployment.deployment_provider_account_id,\\n            new_provider_account_id=deployment.deployment_provider_account_id,\\n        )\\n\\n    assert exc_info.value.code == \\\"DEPLOYMENT_RESOURCE_KEY_UPDATE\\\"\\n\\n\\ndef test_deployment_immutable_field_guard_blocks_provider_account_move(deployment: Deployment) -> None:\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        ensure_deployment_immutable_fields(\\n            old_project_id=deployment.project_id,\\n            new_project_id=deployment.project_id,\\n            old_deployment_type=deployment.deployment_type,\\n            new_deployment_type=deployment.deployment_type,\\n            old_resource_key=deployment.resource_key,\\n            new_resource_key=deployment.resource_key,\\n            old_provider_account_id=deployment.deployment_provider_account_id,\\n            new_provider_account_id=uuid4(),\\n        )\\n\\n    assert exc_info.value.code == \\\"DEPLOYMENT_PROVIDER_ACCOUNT_MOVE\\\"\\n\\n\\ndef test_deployment_immutable_field_guard_allows_noop(deployment: Deployment) -> None:\\n    ensure_deployment_immutable_fields(\\n        old_project_id=deployment.project_id,\\n        new_project_id=deployment.project_id,\\n        old_deployment_type=deployment.deployment_type,\\n        new_deployment_type=deployment.deployment_type,\\n        old_resource_key=deployment.resource_key,\\n        new_resource_key=deployment.resource_key,\\n        old_provider_account_id=deployment.deployment_provider_account_id,\\n        new_provider_account_id=deployment.deployment_provider_account_id,\\n    )\\n\\n\\ndef test_provider_identity_guard_blocks_changes(provider_account: DeploymentProviderAccount) -> None:\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        ensure_provider_account_identity_immutable(\\n            old_provider_key=provider_account.provider_key,\\n            new_provider_key=provider_account.provider_key,\\n            old_provider_tenant_id=provider_account.provider_tenant_id,\\n            new_provider_tenant_id=provider_account.provider_tenant_id,\\n            old_provider_url=provider_account.provider_url,\\n            new_provider_url=\\\"https://provider-renamed.example.com\\\",\\n        )\\n\\n    assert exc_info.value.code == \\\"DEPLOYMENT_PROVIDER_ACCOUNT_IDENTITY_UPDATE\\\"\\n\\n\\ndef test_provider_identity_guard_blocks_provider_key_changes(provider_account: DeploymentProviderAccount) -> None:\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        ensure_provider_account_identity_immutable(\\n            old_provider_key=provider_account.provider_key,\\n            new_provider_key=cast(\\\"DeploymentProviderKey\\\", \\\"changed-provider-key\\\"),\\n            old_provider_tenant_id=provider_account.provider_tenant_id,\\n            new_provider_tenant_id=provider_account.provider_tenant_id,\\n            old_provider_url=provider_account.provider_url,\\n            new_provider_url=provider_account.provider_url,\\n        )\\n\\n    assert exc_info.value.code == \\\"DEPLOYMENT_PROVIDER_ACCOUNT_IDENTITY_UPDATE\\\"\\n\\n\\ndef test_provider_identity_guard_blocks_provider_tenant_id_changes(provider_account: DeploymentProviderAccount) -> None:\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        ensure_provider_account_identity_immutable(\\n            old_provider_key=provider_account.provider_key,\\n            new_provider_key=provider_account.provider_key,\\n            old_provider_tenant_id=provider_account.provider_tenant_id,\\n            new_provider_tenant_id=\\\"tenant-updated\\\",\\n            old_provider_url=provider_account.provider_url,\\n            new_provider_url=provider_account.provider_url,\\n        )\\n\\n    assert exc_info.value.code == \\\"DEPLOYMENT_PROVIDER_ACCOUNT_IDENTITY_UPDATE\\\"\\n\\n\\ndef test_provider_identity_guard_allows_noop(provider_account: DeploymentProviderAccount) -> None:\\n    ensure_provider_account_identity_immutable(\\n        old_provider_key=provider_account.provider_key,\\n        new_provider_key=provider_account.provider_key,\\n        old_provider_tenant_id=provider_account.provider_tenant_id,\\n        new_provider_tenant_id=provider_account.provider_tenant_id,\\n        old_provider_url=provider_account.provider_url,\\n        new_provider_url=provider_account.provider_url,\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_crud_update_deployment_blocks_project_move(\\n    db: AsyncSession,\\n    deployment: Deployment,\\n    target_project: Folder,\\n) -> None:\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        await update_deployment(db, deployment=deployment, project_id=target_project.id)\\n\\n    assert exc_info.value.code == \\\"DEPLOYMENT_PROJECT_MOVE\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_crud_update_deployment_blocks_type_update(\\n    db: AsyncSession,\\n    deployment: Deployment,\\n) -> None:\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        await update_deployment(\\n            db,\\n            deployment=deployment,\\n            deployment_type=cast(\\\"DeploymentType\\\", \\\"changed-type\\\"),\\n        )\\n\\n    assert exc_info.value.code == \\\"DEPLOYMENT_TYPE_UPDATE\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_crud_update_provider_account_blocks_identity_update(\\n    db: AsyncSession,\\n    provider_account: DeploymentProviderAccount,\\n) -> None:\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        await update_provider_account(\\n            db,\\n            provider_account=provider_account,\\n            provider_url=\\\"https://provider-renamed.example.com\\\",\\n        )\\n\\n    assert exc_info.value.code == \\\"DEPLOYMENT_PROVIDER_ACCOUNT_IDENTITY_UPDATE\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_attachment_project_match_blocks_cross_project_directly(\\n    db: AsyncSession,\\n    user: User,\\n    target_project: Folder,\\n    flow_version: FlowVersion,\\n    provider_account: DeploymentProviderAccount,\\n) -> None:\\n    deployment_in_other_project = Deployment(\\n        user_id=user.id,\\n        project_id=target_project.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-direct-block\\\",\\n        display_name=\\\"deployment-direct-block\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    db.add(deployment_in_other_project)\\n    await db.commit()\\n    await db.refresh(deployment_in_other_project)\\n\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        await ensure_attachment_project_match(\\n            db,\\n            flow_version_id=flow_version.id,\\n            deployment_id=deployment_in_other_project.id,\\n        )\\n\\n    assert exc_info.value.code == \\\"CROSS_PROJECT_ATTACHMENT\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_attachment_project_match_allows_same_project_directly(\\n    db: AsyncSession,\\n    flow_version: FlowVersion,\\n    deployment: Deployment,\\n) -> None:\\n    await ensure_attachment_project_match(\\n        db,\\n        flow_version_id=flow_version.id,\\n        deployment_id=deployment.id,\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_attachment_create_blocks_cross_project(\\n    db: AsyncSession,\\n    user: User,\\n    target_project: Folder,\\n    flow_version: FlowVersion,\\n    provider_account: DeploymentProviderAccount,\\n) -> None:\\n    deployment_in_other_project = Deployment(\\n        user_id=user.id,\\n        project_id=target_project.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-other\\\",\\n        display_name=\\\"deployment-other\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    db.add(deployment_in_other_project)\\n    await db.commit()\\n    await db.refresh(deployment_in_other_project)\\n\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        await create_deployment_attachment(\\n            db,\\n            user_id=user.id,\\n            flow_version_id=flow_version.id,\\n            deployment_id=deployment_in_other_project.id,\\n            provider_snapshot_id=\\\"snapshot-2\\\",\\n        )\\n\\n    assert exc_info.value.code == \\\"CROSS_PROJECT_ATTACHMENT\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_attachment_create_succeeds_same_project(\\n    db: AsyncSession,\\n    user: User,\\n    flow_version: FlowVersion,\\n    deployment: Deployment,\\n) -> None:\\n    row = await create_deployment_attachment(\\n        db,\\n        user_id=user.id,\\n        flow_version_id=flow_version.id,\\n        deployment_id=deployment.id,\\n        provider_snapshot_id=\\\"snapshot-3\\\",\\n    )\\n    await db.commit()\\n    assert row.id is not None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/services/database/models/deployment/test_exceptions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"be839249cb19937ca52f7ac3da84b702ddb74eb65bcfcb389a1954b4338c17de\",\"content\":\"from __future__ import annotations\\n\\nimport pytest\\nfrom langflow.services.database.models.deployment.exceptions import (\\n    DeploymentGuardError,\\n    araise_if_deployment_guard_error_or_skip,\\n    get_friendly_guard_detail,\\n    parse_deployment_guard_error,\\n    raise_if_deployment_guard_error_or_skip,\\n    remap_flow_guard_for_project_delete,\\n)\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"code\\\", \\\"technical_detail\\\", \\\"friendly_detail\\\"),\\n    [\\n        (\\n            \\\"FLOW_DEPLOYED_IN_PROJECT\\\",\\n            \\\"UPDATE flow.folder_id blocked: versions of this flow remain attached to deployments in the current \\\"\\n            \\\"project scope (OLD.folder_id). Remove rows from flow_version_deployment_attachment for this flow in the \\\"\\n            \\\"current project before changing flow.folder_id.\\\",\\n            \\\"This flow cannot be moved to another project until its versions are removed from deployments \\\"\\n            \\\"in its current project.\\\",\\n        ),\\n        (\\n            \\\"DEPLOYMENT_PROJECT_MOVE\\\",\\n            \\\"UPDATE deployment.project_id blocked: project scope is immutable for existing deployments. \\\"\\n            \\\"Re-create the deployment in the target project.\\\",\\n            \\\"This deployment cannot be moved to a different project. Re-create it in the target project instead.\\\",\\n        ),\\n        (\\n            \\\"DEPLOYMENT_TYPE_UPDATE\\\",\\n            \\\"Cannot modify deployment type on an existing deployment.\\\",\\n            \\\"The deployment type cannot be modified.\\\",\\n        ),\\n        (\\n            \\\"DEPLOYMENT_PROVIDER_ACCOUNT_MOVE\\\",\\n            \\\"UPDATE deployment.deployment_provider_account_id blocked: provider account scope is immutable \\\"\\n            \\\"for existing deployments. Re-create the deployment under the target provider account.\\\",\\n            \\\"This deployment cannot be moved to a different provider account. Re-create it under the target \\\"\\n            \\\"provider account.\\\",\\n        ),\\n        (\\n            \\\"CROSS_PROJECT_ATTACHMENT\\\",\\n            \\\"INSERT flow_version_deployment_attachment blocked: flow project scope (flow.folder_id) does not match \\\"\\n            \\\"deployment project scope (deployment.project_id).\\\",\\n            \\\"Flow versions can only be in deployments in the same project.\\\",\\n        ),\\n        (\\n            \\\"DEPLOYMENT_RESOURCE_KEY_UPDATE\\\",\\n            \\\"Cannot modify deployment resource key on an existing deployment. Re-create it instead.\\\",\\n            \\\"This deployment resource key cannot be modified on an existing deployment. Re-create it instead.\\\",\\n        ),\\n        (\\n            \\\"DEPLOYMENT_PROVIDER_ACCOUNT_IDENTITY_UPDATE\\\",\\n            \\\"UPDATE deployment_provider_account blocked: provider_key, provider_tenant_id, and provider_url \\\"\\n            \\\"are immutable on existing accounts. Re-create the account instead.\\\",\\n            \\\"This deployment provider account identity cannot be modified. Re-create the account instead.\\\",\\n        ),\\n    ],\\n)\\ndef test_parse_deployment_guard_error_maps_code_to_friendly_detail(\\n    code: str,\\n    technical_detail: str,\\n    friendly_detail: str,\\n) -> None:\\n    exc = DeploymentGuardError(\\n        code=code,\\n        technical_detail=technical_detail,\\n        detail=friendly_detail,\\n    )\\n\\n    parsed = parse_deployment_guard_error(exc)\\n\\n    assert isinstance(parsed, DeploymentGuardError)\\n    assert parsed.code == code\\n    assert parsed.technical_detail == technical_detail\\n    assert parsed.detail == friendly_detail\\n\\n\\ndef test_get_friendly_guard_detail_falls_back_to_generic_code_message() -> None:\\n    assert (\\n        get_friendly_guard_detail(\\\"SOME_UNKNOWN_CODE\\\") == \\\"Operation blocked by deployment guard (SOME_UNKNOWN_CODE).\\\"\\n    )\\n\\n\\ndef test_parse_deployment_guard_error_returns_none_when_absent() -> None:\\n    parsed = parse_deployment_guard_error(Exception(\\\"plain error DEPLOYMENT_GUARD:PROJECT_HAS_DEPLOYMENTS:oops\\\"))\\n    assert parsed is None\\n\\n\\ndef test_deployment_guard_error_supports_manual_technical_and_code() -> None:\\n    err = DeploymentGuardError(\\n        code=\\\"FLOW_HAS_DEPLOYED_VERSIONS\\\",\\n        technical_detail=\\\"DELETE flow_version blocked due to dependent rows.\\\",\\n        detail=(\\n            \\\"This flow cannot be deleted because it has deployed versions. \\\"\\n            \\\"Please remove its versions from deployments first.\\\"\\n        ),\\n    )\\n    assert err.code == \\\"FLOW_HAS_DEPLOYED_VERSIONS\\\"\\n    assert err.technical_detail == \\\"DELETE flow_version blocked due to dependent rows.\\\"\\n    assert (\\n        err.detail == \\\"This flow cannot be deleted because it has deployed versions. \\\"\\n        \\\"Please remove its versions from deployments first.\\\"\\n    )\\n\\n\\ndef test_raise_if_deployment_guard_error_or_skip_raises_guard_error() -> None:\\n    guard_error = DeploymentGuardError(\\n        code=\\\"PROJECT_HAS_DEPLOYMENTS\\\",\\n        technical_detail=\\\"DELETE project blocked: dependent deployments exist.\\\",\\n        detail=get_friendly_guard_detail(\\\"PROJECT_HAS_DEPLOYMENTS\\\"),\\n    )\\n\\n    with pytest.raises(DeploymentGuardError) as raised:\\n        raise_if_deployment_guard_error_or_skip(guard_error)\\n\\n    assert raised.value is guard_error\\n\\n\\ndef test_raise_if_deployment_guard_error_or_skip_is_noop_when_guard_absent() -> None:\\n    raise_if_deployment_guard_error_or_skip(Exception(\\\"not a guard error\\\"))\\n\\n\\n@pytest.mark.asyncio\\nasync def test_araise_if_deployment_guard_error_or_skip_raises_and_logs_message(monkeypatch) -> None:\\n    guard_error = DeploymentGuardError(\\n        code=\\\"PROJECT_HAS_DEPLOYMENTS\\\",\\n        technical_detail=\\\"DELETE project blocked: dependent deployments exist.\\\",\\n        detail=get_friendly_guard_detail(\\\"PROJECT_HAS_DEPLOYMENTS\\\"),\\n    )\\n    debug_calls: list[tuple[str, tuple[object, ...]]] = []\\n\\n    async def _fake_adebug(message: str, *args: object) -> None:\\n        debug_calls.append((message, args))\\n\\n    monkeypatch.setattr(\\\"langflow.services.database.models.deployment.exceptions.logger.adebug\\\", _fake_adebug)\\n\\n    with pytest.raises(DeploymentGuardError) as raised:\\n        await araise_if_deployment_guard_error_or_skip(\\n            guard_error,\\n            log_message=\\\"op=test\\\",\\n        )\\n\\n    assert raised.value is guard_error\\n    assert debug_calls == [\\n        (\\n            \\\"%s code=%s technical_detail=%s\\\",\\n            (\\n                \\\"op=test\\\",\\n                \\\"PROJECT_HAS_DEPLOYMENTS\\\",\\n                \\\"DELETE project blocked: dependent deployments exist.\\\",\\n            ),\\n        )\\n    ]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_araise_if_deployment_guard_error_or_skip_raises_without_logging_when_message_absent(monkeypatch) -> None:\\n    guard_error = DeploymentGuardError(\\n        code=\\\"PROJECT_HAS_DEPLOYMENTS\\\",\\n        technical_detail=\\\"DELETE project blocked: dependent deployments exist.\\\",\\n        detail=get_friendly_guard_detail(\\\"PROJECT_HAS_DEPLOYMENTS\\\"),\\n    )\\n    debug_calls: list[tuple[str, tuple[object, ...]]] = []\\n\\n    async def _fake_adebug(message: str, *args: object) -> None:\\n        debug_calls.append((message, args))\\n\\n    monkeypatch.setattr(\\\"langflow.services.database.models.deployment.exceptions.logger.adebug\\\", _fake_adebug)\\n\\n    with pytest.raises(DeploymentGuardError):\\n        await araise_if_deployment_guard_error_or_skip(guard_error)\\n\\n    assert debug_calls == []\\n\\n\\ndef test_remap_flow_guard_for_project_delete_remaps_flow_guard() -> None:\\n    flow_guard = DeploymentGuardError(\\n        code=\\\"FLOW_HAS_DEPLOYED_VERSIONS\\\",\\n        technical_detail=\\\"DELETE flow blocked by deployment attachment\\\",\\n        detail=get_friendly_guard_detail(\\\"FLOW_HAS_DEPLOYED_VERSIONS\\\"),\\n    )\\n\\n    remapped = remap_flow_guard_for_project_delete(flow_guard)\\n\\n    assert remapped is not flow_guard\\n    assert remapped.code == \\\"PROJECT_HAS_DEPLOYMENTS\\\"\\n    assert remapped.technical_detail == (\\n        \\\"DELETE folder blocked while deleting project flows: DELETE flow blocked by deployment attachment\\\"\\n    )\\n    assert remapped.detail == get_friendly_guard_detail(\\\"PROJECT_HAS_DEPLOYMENTS\\\")\\n\\n\\ndef test_remap_flow_guard_for_project_delete_keeps_non_flow_guard() -> None:\\n    project_guard = DeploymentGuardError(\\n        code=\\\"PROJECT_HAS_DEPLOYMENTS\\\",\\n        technical_detail=\\\"DELETE project blocked by deployment row\\\",\\n        detail=get_friendly_guard_detail(\\\"PROJECT_HAS_DEPLOYMENTS\\\"),\\n    )\\n\\n    remapped = remap_flow_guard_for_project_delete(project_guard)\\n\\n    assert remapped is project_guard\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/services/database/models/deployment/test_guards.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2aba56274e3e2854dc71e2c378f1510eaafa00e674178c7d7fd1dbf0c72495f2\",\"content\":\"from __future__ import annotations\\n\\nfrom unittest.mock import AsyncMock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.deployment.exceptions import DeploymentGuardError\\nfrom langflow.services.database.models.deployment.guards import (\\n    check_flow_has_deployed_versions,\\n    check_project_has_deployments,\\n)\\n\\n\\nclass _ExecResult:\\n    def __init__(self, value, rowcount: int = 0):\\n        self._value = value\\n        self.rowcount = rowcount\\n\\n    def first(self):\\n        return self._value\\n\\n    def all(self):\\n        return self._value\\n\\n\\n@pytest.mark.asyncio\\nasync def test_check_flow_has_deployed_versions_allows_when_no_attachments() -> None:\\n    db = AsyncMock()\\n    db.exec = AsyncMock(\\n        side_effect=[\\n            _ExecResult(None, rowcount=0),  # prune orphan attachments (no-op)\\n            _ExecResult(None),  # live deployment attachment lookup\\n        ]\\n    )\\n\\n    await check_flow_has_deployed_versions(db, flow_id=uuid4())\\n\\n    assert db.exec.await_count == 2\\n\\n\\n@pytest.mark.asyncio\\nasync def test_check_flow_has_deployed_versions_raises_guard_when_attached() -> None:\\n    db = AsyncMock()\\n    db.exec = AsyncMock(\\n        side_effect=[\\n            _ExecResult(None, rowcount=0),  # prune orphan attachments (no-op)\\n            _ExecResult(uuid4()),  # live deployment attachment lookup\\n        ]\\n    )\\n\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        await check_flow_has_deployed_versions(db, flow_id=uuid4())\\n\\n    assert exc_info.value.code == \\\"FLOW_HAS_DEPLOYED_VERSIONS\\\"\\n    assert (\\n        exc_info.value.detail == \\\"This flow cannot be deleted because it has deployed versions. \\\"\\n        \\\"Please remove its versions from deployments first.\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_check_flow_has_deployed_versions_prunes_orphan_attachments() -> None:\\n    db = AsyncMock()\\n    db.exec = AsyncMock(\\n        side_effect=[\\n            _ExecResult(None, rowcount=1),  # prune orphan attachments (one row pruned)\\n            _ExecResult(None),  # live deployment attachment lookup\\n        ]\\n    )\\n\\n    await check_flow_has_deployed_versions(db, flow_id=uuid4())\\n\\n    assert db.exec.await_count == 2\\n\\n\\n@pytest.mark.asyncio\\nasync def test_check_flow_has_deployed_versions_prunes_orphans_even_when_attached() -> None:\\n    \\\"\\\"\\\"Prune step must run before the live-attachment check.\\n\\n    This ensures flows with both orphan and live attachments still get their orphans cleaned up.\\n    \\\"\\\"\\\"\\n    db = AsyncMock()\\n    db.exec = AsyncMock(\\n        side_effect=[\\n            _ExecResult(None, rowcount=2),  # prune orphan attachments\\n            _ExecResult(uuid4()),  # live deployment attachment lookup -> raises\\n        ]\\n    )\\n\\n    with pytest.raises(DeploymentGuardError):\\n        await check_flow_has_deployed_versions(db, flow_id=uuid4())\\n\\n    assert db.exec.await_count == 2\\n\\n\\n@pytest.mark.asyncio\\nasync def test_check_project_has_deployments_allows_when_empty() -> None:\\n    db = AsyncMock()\\n    db.exec = AsyncMock(return_value=_ExecResult(None))\\n\\n    await check_project_has_deployments(db, project_id=uuid4())\\n\\n\\n@pytest.mark.asyncio\\nasync def test_check_project_has_deployments_raises_guard_when_present() -> None:\\n    db = AsyncMock()\\n    db.exec = AsyncMock(return_value=_ExecResult(uuid4()))\\n\\n    with pytest.raises(DeploymentGuardError) as exc_info:\\n        await check_project_has_deployments(db, project_id=uuid4())\\n\\n    assert exc_info.value.code == \\\"PROJECT_HAS_DEPLOYMENTS\\\"\\n    assert (\\n        exc_info.value.detail\\n        == \\\"This project cannot be deleted because it has deployments. Please delete its deployments first.\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/services/database/models/deployment/test_in_memory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"031454a3288a3452467ea153aa748cd38123d6ac7ab2ff27337311b4f4caa885\",\"content\":\"\\\"\\\"\\\"Deployment and DeploymentProviderAccount tests against in-memory SQLite.\\n\\nUses a real database with foreign keys enabled to verify CASCADE deletes,\\nidentity constraints, relationships, and CRUD operations.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.deployment.crud import (\\n    count_deployments_by_provider,\\n    create_deployment,\\n    delete_deployment_by_id,\\n    delete_deployment_by_resource_key,\\n    get_deployment,\\n    get_deployment_by_resource_key,\\n    list_deployments_page,\\n    update_deployment,\\n)\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.deployment_provider_account.crud import (\\n    create_provider_account,\\n    delete_provider_account,\\n    get_provider_account_by_id,\\n    list_provider_accounts,\\n    update_provider_account,\\n)\\nfrom langflow.services.database.models.deployment_provider_account.model import (\\n    DeploymentProviderAccount,\\n    DeploymentProviderKey,\\n)\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.user.model import User\\nfrom lfx.services.adapters.deployment.schema import DeploymentType\\nfrom sqlalchemy import event\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlalchemy.ext.asyncio import create_async_engine\\nfrom sqlalchemy.pool import StaticPool\\nfrom sqlmodel import SQLModel, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n_TEST_PASSWORD = \\\"hashed\\\"  # noqa: S105  # pragma: allowlist secret\\n_ENCRYPT_TARGET = \\\"langflow.services.database.models.deployment_provider_account.crud.auth_utils\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Fixtures\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.fixture(name=\\\"db_engine\\\")\\ndef db_engine_fixture():\\n    engine = create_async_engine(\\n        \\\"sqlite+aiosqlite://\\\",\\n        connect_args={\\\"check_same_thread\\\": False},\\n        poolclass=StaticPool,\\n    )\\n\\n    @event.listens_for(engine.sync_engine, \\\"connect\\\")\\n    def _enable_fk(dbapi_connection, connection_record):  # noqa: ARG001\\n        cursor = dbapi_connection.cursor()\\n        cursor.execute(\\\"PRAGMA foreign_keys=ON\\\")\\n        cursor.close()\\n\\n    return engine\\n\\n\\n@pytest.fixture(name=\\\"db\\\")\\nasync def db_fixture(db_engine):\\n    async with db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.create_all)\\n    async with AsyncSession(db_engine, expire_on_commit=False) as session:\\n        yield session\\n    async with db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.drop_all)\\n    await db_engine.dispose()\\n\\n\\n@pytest.fixture\\nasync def user(db: AsyncSession) -> User:\\n    u = User(username=\\\"testuser\\\", password=_TEST_PASSWORD, is_active=True)\\n    db.add(u)\\n    await db.commit()\\n    await db.refresh(u)\\n    return u\\n\\n\\n@pytest.fixture\\nasync def folder(db: AsyncSession, user: User) -> Folder:\\n    f = Folder(name=\\\"test-project\\\", user_id=user.id)\\n    db.add(f)\\n    await db.commit()\\n    await db.refresh(f)\\n    return f\\n\\n\\n@pytest.fixture\\nasync def provider_account(db: AsyncSession, user: User) -> DeploymentProviderAccount:\\n    acct = DeploymentProviderAccount(\\n        user_id=user.id,\\n        name=\\\"provider-account-1\\\",\\n        provider_tenant_id=\\\"tenant-1\\\",\\n        provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n        provider_url=\\\"https://provider.example.com\\\",\\n        api_key=\\\"encrypted-value\\\",  # pragma: allowlist secret\\n    )\\n    db.add(acct)\\n    await db.commit()\\n    await db.refresh(acct)\\n    return acct\\n\\n\\n@pytest.fixture\\nasync def deployment(\\n    db: AsyncSession,\\n    user: User,\\n    folder: Folder,\\n    provider_account: DeploymentProviderAccount,\\n) -> Deployment:\\n    d = Deployment(\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-1\\\",\\n        display_name=\\\"my-deployment\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    db.add(d)\\n    await db.commit()\\n    await db.refresh(d)\\n    return d\\n\\n\\n# ===========================================================================\\n# DeploymentProviderAccount \u2014 model-level integration\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestProviderAccountModel:\\n    async def test_create_and_read(self, db: AsyncSession, provider_account: DeploymentProviderAccount):\\n        stmt = select(DeploymentProviderAccount).where(DeploymentProviderAccount.id == provider_account.id)\\n        row = (await db.exec(stmt)).one()\\n        assert row.provider_key == DeploymentProviderKey.WATSONX_ORCHESTRATE\\n        assert row.provider_url == \\\"https://provider.example.com\\\"\\n        assert row.provider_tenant_id == \\\"tenant-1\\\"\\n        assert row.created_at is not None\\n        assert row.updated_at is not None\\n\\n    async def test_unique_constraint_user_url_tenant(\\n        self, db: AsyncSession, user: User, provider_account: DeploymentProviderAccount\\n    ):\\n        dup = DeploymentProviderAccount(\\n            user_id=user.id,\\n            name=\\\"provider-account-duplicate\\\",\\n            provider_tenant_id=provider_account.provider_tenant_id,\\n            provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            provider_url=provider_account.provider_url,\\n            api_key=\\\"other-encrypted\\\",  # pragma: allowlist secret\\n        )\\n        db.add(dup)\\n        with pytest.raises(IntegrityError):\\n            await db.commit()\\n\\n    async def test_null_tenant_allows_multiple_rows(self, db: AsyncSession, user: User):\\n        \\\"\\\"\\\"SQL NULL != NULL in unique constraints, so two rows with tenant=NULL are allowed.\\\"\\\"\\\"\\n        for i in range(2):\\n            acct = DeploymentProviderAccount(\\n                user_id=user.id,\\n                name=f\\\"null-tenant-{i}\\\",\\n                provider_tenant_id=None,\\n                provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n                provider_url=\\\"https://same-url.example.com\\\",\\n                api_key=f\\\"enc-{i}\\\",\\n            )\\n            db.add(acct)\\n        await db.commit()\\n\\n        stmt = select(DeploymentProviderAccount).where(\\n            DeploymentProviderAccount.user_id == user.id,\\n            DeploymentProviderAccount.provider_tenant_id.is_(None),  # type: ignore[union-attr]\\n        )\\n        rows = (await db.exec(stmt)).all()\\n        assert len(rows) == 2\\n\\n    async def test_cascade_delete_on_user(\\n        self, db: AsyncSession, user: User, provider_account: DeploymentProviderAccount\\n    ):\\n        acct_id = provider_account.id\\n        await db.delete(user)\\n        await db.commit()\\n\\n        stmt = select(DeploymentProviderAccount).where(DeploymentProviderAccount.id == acct_id)\\n        assert (await db.exec(stmt)).first() is None\\n\\n    async def test_user_relationship(self, db: AsyncSession, provider_account: DeploymentProviderAccount):\\n        await db.refresh(provider_account, attribute_names=[\\\"user\\\"])\\n        assert provider_account.user is not None\\n        assert provider_account.user.username == \\\"testuser\\\"\\n\\n\\n# ===========================================================================\\n# Deployment \u2014 model-level integration\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestDeploymentModel:\\n    async def test_create_and_read(self, db: AsyncSession, deployment: Deployment):\\n        stmt = select(Deployment).where(Deployment.id == deployment.id)\\n        row = (await db.exec(stmt)).one()\\n        assert row.display_name == \\\"my-deployment\\\"\\n        assert row.resource_key == \\\"rk-1\\\"\\n        assert row.created_at is not None\\n        assert row.updated_at is not None\\n\\n    async def test_duplicate_display_name_allowed_per_provider(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n        deployment: Deployment,\\n    ):\\n        dup = Deployment(\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-different\\\",\\n            display_name=deployment.display_name,\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        db.add(dup)\\n        await db.commit()\\n        await db.refresh(dup)\\n        assert dup.display_name == deployment.display_name\\n\\n    async def test_unique_resource_key_per_provider(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n        deployment: Deployment,\\n    ):\\n        dup = Deployment(\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=deployment.resource_key,\\n            display_name=\\\"different-name\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        db.add(dup)\\n        with pytest.raises(IntegrityError):\\n            await db.commit()\\n\\n    async def test_same_display_name_allowed_across_providers(\\n        self, db: AsyncSession, user: User, folder: Folder, deployment: Deployment\\n    ):\\n        other_acct = DeploymentProviderAccount(\\n            user_id=user.id,\\n            name=\\\"provider-account-2\\\",\\n            provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n            provider_url=\\\"https://other.example.com\\\",\\n            api_key=\\\"enc-other\\\",  # pragma: allowlist secret\\n        )\\n        db.add(other_acct)\\n        await db.commit()\\n        await db.refresh(other_acct)\\n\\n        d2 = Deployment(\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=other_acct.id,\\n            resource_key=deployment.resource_key,\\n            display_name=deployment.display_name,\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        db.add(d2)\\n        await db.commit()\\n        await db.refresh(d2)\\n        assert d2.id is not None\\n\\n    async def test_cascade_delete_on_user(self, db: AsyncSession, user: User, deployment: Deployment):\\n        dep_id = deployment.id\\n        await db.delete(user)\\n        await db.commit()\\n\\n        stmt = select(Deployment).where(Deployment.id == dep_id)\\n        assert (await db.exec(stmt)).first() is None\\n\\n    async def test_cascade_delete_on_folder(self, db: AsyncSession, folder: Folder, deployment: Deployment):\\n        dep_id = deployment.id\\n        await db.delete(folder)\\n        await db.commit()\\n\\n        stmt = select(Deployment).where(Deployment.id == dep_id)\\n        assert (await db.exec(stmt)).first() is None\\n\\n    async def test_cascade_delete_on_provider_account(\\n        self, db: AsyncSession, provider_account: DeploymentProviderAccount, deployment: Deployment\\n    ):\\n        dep_id = deployment.id\\n        await db.delete(provider_account)\\n        await db.commit()\\n\\n        stmt = select(Deployment).where(Deployment.id == dep_id)\\n        assert (await db.exec(stmt)).first() is None\\n\\n    async def test_relationships_load(self, db: AsyncSession, deployment: Deployment):\\n        await db.refresh(deployment, attribute_names=[\\\"user\\\", \\\"folder\\\", \\\"deployment_provider_account\\\"])\\n        assert deployment.user.username == \\\"testuser\\\"\\n        assert deployment.folder.name == \\\"test-project\\\"\\n        assert deployment.deployment_provider_account.provider_key == DeploymentProviderKey.WATSONX_ORCHESTRATE\\n\\n    async def test_fk_rejects_nonexistent_folder(self, db: AsyncSession, user: User, provider_account):\\n        d = Deployment(\\n            user_id=user.id,\\n            project_id=uuid4(),\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-orphan\\\",\\n            display_name=\\\"orphan\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        db.add(d)\\n        with pytest.raises(IntegrityError):\\n            await db.commit()\\n\\n\\n# ===========================================================================\\n# DeploymentProviderAccount \u2014 CRUD integration\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestProviderAccountCRUD:\\n    async def test_create_and_get(self, db: AsyncSession, user: User):\\n        with patch(_ENCRYPT_TARGET) as mock_auth:\\n            mock_auth.encrypt_api_key.return_value = \\\"enc-token\\\"\\n            acct = await create_provider_account(\\n                db,\\n                user_id=user.id,\\n                name=\\\"acct-1\\\",\\n                provider_tenant_id=\\\"t1\\\",\\n                provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE.value,\\n                provider_url=\\\"https://api.example.com\\\",\\n                api_key=\\\"raw-key\\\",  # pragma: allowlist secret\\n            )\\n            await db.commit()\\n\\n        assert acct.id is not None\\n        assert acct.api_key == \\\"enc-token\\\"  # pragma: allowlist secret\\n\\n        fetched = await get_provider_account_by_id(db, provider_id=acct.id, user_id=user.id)\\n        assert fetched is not None\\n        assert fetched.provider_key == DeploymentProviderKey.WATSONX_ORCHESTRATE\\n\\n    async def test_list(self, db: AsyncSession, user: User):\\n        with patch(_ENCRYPT_TARGET) as mock_auth:\\n            mock_auth.encrypt_api_key.return_value = \\\"enc\\\"\\n            for i in range(3):\\n                await create_provider_account(\\n                    db,\\n                    user_id=user.id,\\n                    name=f\\\"acct-{i}\\\",\\n                    provider_tenant_id=f\\\"t-{i}\\\",\\n                    provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE.value,\\n                    provider_url=f\\\"https://p{i}.example.com\\\",\\n                    api_key=\\\"key\\\",  # pragma: allowlist secret\\n                )\\n            await db.commit()\\n\\n        accounts = await list_provider_accounts(db, user_id=user.id)\\n        assert len(accounts) == 3\\n\\n    async def test_update_api_key(self, db: AsyncSession, user: User):\\n        with patch(_ENCRYPT_TARGET) as mock_auth:\\n            mock_auth.encrypt_api_key.return_value = \\\"enc-initial\\\"\\n            acct = await create_provider_account(\\n                db,\\n                user_id=user.id,\\n                name=\\\"acct-update\\\",\\n                provider_tenant_id=None,\\n                provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE.value,\\n                provider_url=\\\"https://p.example.com\\\",\\n                api_key=\\\"key\\\",  # pragma: allowlist secret\\n            )\\n            await db.commit()\\n\\n        with patch(_ENCRYPT_TARGET) as mock_auth:\\n            mock_auth.encrypt_api_key.return_value = \\\"enc-rotated\\\"\\n            updated = await update_provider_account(\\n                db,\\n                provider_account=acct,\\n                api_key=\\\"rotated-key\\\",  # pragma: allowlist secret\\n            )\\n            await db.commit()\\n\\n        assert updated.provider_key == DeploymentProviderKey.WATSONX_ORCHESTRATE\\n        assert updated.provider_tenant_id is None\\n        assert updated.api_key == \\\"enc-rotated\\\"  # pragma: allowlist secret\\n\\n    async def test_delete(self, db: AsyncSession, user: User):\\n        with patch(_ENCRYPT_TARGET) as mock_auth:\\n            mock_auth.encrypt_api_key.return_value = \\\"enc\\\"\\n            acct = await create_provider_account(\\n                db,\\n                user_id=user.id,\\n                name=\\\"acct-delete\\\",\\n                provider_tenant_id=None,\\n                provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE.value,\\n                provider_url=\\\"https://p.example.com\\\",\\n                api_key=\\\"key\\\",  # pragma: allowlist secret\\n            )\\n            await db.commit()\\n\\n        acct_id = acct.id\\n        assert acct_id is not None\\n        await delete_provider_account(db, provider_account=acct)\\n        await db.commit()\\n\\n        assert await get_provider_account_by_id(db, provider_id=acct_id, user_id=user.id) is None\\n\\n    async def test_create_duplicate_raises(self, db: AsyncSession, user: User):\\n        with patch(_ENCRYPT_TARGET) as mock_auth:\\n            mock_auth.encrypt_api_key.return_value = \\\"enc\\\"\\n            await create_provider_account(\\n                db,\\n                user_id=user.id,\\n                name=\\\"acct-dupe-1\\\",\\n                provider_tenant_id=\\\"t1\\\",\\n                provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE.value,\\n                provider_url=\\\"https://p.example.com\\\",\\n                api_key=\\\"key\\\",  # pragma: allowlist secret\\n            )\\n            await db.commit()\\n\\n            with pytest.raises(ValueError, match=\\\"Provider account already exists\\\"):\\n                await create_provider_account(\\n                    db,\\n                    user_id=user.id,\\n                    name=\\\"acct-dupe-2\\\",\\n                    provider_tenant_id=\\\"t1\\\",\\n                    provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE.value,\\n                    provider_url=\\\"https://p.example.com\\\",\\n                    api_key=\\\"key2\\\",  # pragma: allowlist secret\\n                )\\n\\n\\n# ===========================================================================\\n# Deployment \u2014 CRUD integration\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestDeploymentCRUD:\\n    async def test_create_and_get(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        assert folder.id is not None\\n        assert provider_account.id is not None\\n\\n        dep = await create_deployment(\\n            db,\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-crud\\\",\\n            display_name=\\\"crud-deploy\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        await db.commit()\\n\\n        assert dep.id is not None\\n        fetched = await get_deployment(db, user_id=user.id, deployment_id=dep.id)\\n        assert fetched is not None\\n        assert fetched.display_name == \\\"crud-deploy\\\"\\n\\n    async def test_get_by_resource_key(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        assert folder.id is not None\\n        assert provider_account.id is not None\\n\\n        await create_deployment(\\n            db,\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-lookup\\\",\\n            display_name=\\\"lookup-deploy\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        await db.commit()\\n\\n        found = await get_deployment_by_resource_key(\\n            db,\\n            user_id=user.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-lookup\\\",\\n        )\\n        assert found is not None\\n        assert found.display_name == \\\"lookup-deploy\\\"\\n\\n    async def test_list_page_and_count(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        assert folder.id is not None\\n        assert provider_account.id is not None\\n\\n        for i in range(5):\\n            await create_deployment(\\n                db,\\n                user_id=user.id,\\n                project_id=folder.id,\\n                deployment_provider_account_id=provider_account.id,\\n                resource_key=f\\\"rk-{i}\\\",\\n                display_name=f\\\"deploy-{i}\\\",\\n                deployment_type=DeploymentType.AGENT,\\n            )\\n        await db.commit()\\n\\n        total = await count_deployments_by_provider(\\n            db, user_id=user.id, row_owner_id=user.id, deployment_provider_account_id=provider_account.id\\n        )\\n        assert total == 5\\n\\n        page = await list_deployments_page(\\n            db,\\n            user_id=user.id,\\n            row_owner_id=user.id,\\n            deployment_provider_account_id=provider_account.id,\\n            offset=0,\\n            limit=3,\\n        )\\n        assert len(page) == 3\\n\\n        page2 = await list_deployments_page(\\n            db,\\n            user_id=user.id,\\n            row_owner_id=user.id,\\n            deployment_provider_account_id=provider_account.id,\\n            offset=3,\\n            limit=3,\\n        )\\n        assert len(page2) == 2\\n\\n    async def test_update(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        assert folder.id is not None\\n        assert provider_account.id is not None\\n\\n        dep = await create_deployment(\\n            db,\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-upd\\\",\\n            display_name=\\\"original\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        await db.commit()\\n\\n        updated = await update_deployment(db, deployment=dep, display_name=\\\"renamed\\\")\\n        await db.commit()\\n\\n        assert updated.display_name == \\\"renamed\\\"\\n\\n        assert dep.id is not None\\n        fetched = await get_deployment(db, user_id=user.id, deployment_id=dep.id)\\n        assert fetched is not None\\n        assert fetched.display_name == \\\"renamed\\\"\\n\\n    async def test_delete_by_id(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        assert folder.id is not None\\n        assert provider_account.id is not None\\n\\n        dep = await create_deployment(\\n            db,\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-del\\\",\\n            display_name=\\\"to-delete\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        await db.commit()\\n\\n        assert dep.id is not None\\n        count = await delete_deployment_by_id(db, user_id=user.id, deployment_id=dep.id)\\n        await db.commit()\\n        assert count == 1\\n\\n        assert await get_deployment(db, user_id=user.id, deployment_id=dep.id) is None\\n\\n    async def test_delete_by_resource_key(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        assert folder.id is not None\\n        assert provider_account.id is not None\\n\\n        await create_deployment(\\n            db,\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-delrk\\\",\\n            display_name=\\\"to-delete-rk\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        await db.commit()\\n\\n        count = await delete_deployment_by_resource_key(\\n            db,\\n            user_id=user.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-delrk\\\",\\n        )\\n        await db.commit()\\n        assert count == 1\\n\\n    async def test_create_duplicate_display_name_allowed(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        assert folder.id is not None\\n        assert provider_account.id is not None\\n\\n        await create_deployment(\\n            db,\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-a\\\",\\n            display_name=\\\"same-name\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        await db.commit()\\n\\n        duplicate = await create_deployment(\\n            db,\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-b\\\",\\n            display_name=\\\"same-name\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        await db.commit()\\n        assert duplicate.display_name == \\\"same-name\\\"\\n\\n    async def test_create_duplicate_resource_key_raises(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        assert folder.id is not None\\n        assert provider_account.id is not None\\n\\n        await create_deployment(\\n            db,\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-dup\\\",\\n            display_name=\\\"name-a\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        await db.commit()\\n\\n        with pytest.raises(ValueError, match=\\\"conflicts with an existing record\\\"):\\n            await create_deployment(\\n                db,\\n                user_id=user.id,\\n                project_id=folder.id,\\n                deployment_provider_account_id=provider_account.id,\\n                resource_key=\\\"rk-dup\\\",\\n                display_name=\\\"name-b\\\",\\n                deployment_type=DeploymentType.AGENT,\\n            )\\n\\n    async def test_user_scoping(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        \\\"\\\"\\\"Deployments are scoped to user_id \u2014 another user cannot see them.\\\"\\\"\\\"\\n        assert folder.id is not None\\n        assert provider_account.id is not None\\n\\n        dep = await create_deployment(\\n            db,\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-scoped\\\",\\n            display_name=\\\"scoped\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        await db.commit()\\n\\n        other_user = User(username=\\\"other\\\", password=_TEST_PASSWORD, is_active=True)\\n        db.add(other_user)\\n        await db.commit()\\n        await db.refresh(other_user)\\n\\n        assert dep.id is not None\\n        assert await get_deployment(db, user_id=other_user.id, deployment_id=dep.id) is None\\n\\n    async def test_cascade_delete_via_provider_crud(\\n        self,\\n        db: AsyncSession,\\n        user: User,\\n        folder: Folder,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        \\\"\\\"\\\"Deleting a provider account via CRUD cascades to its deployments.\\\"\\\"\\\"\\n        assert folder.id is not None\\n        assert provider_account.id is not None\\n\\n        dep = await create_deployment(\\n            db,\\n            user_id=user.id,\\n            project_id=folder.id,\\n            deployment_provider_account_id=provider_account.id,\\n            resource_key=\\\"rk-cascade\\\",\\n            display_name=\\\"cascade-test\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        await db.commit()\\n        dep_id = dep.id\\n\\n        await delete_provider_account(db, provider_account=provider_account)\\n        await db.commit()\\n\\n        stmt = select(Deployment).where(Deployment.id == dep_id)\\n        assert (await db.exec(stmt)).first() is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/tests/services/database/models/deployment/test_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"36fd59908367bd8ab5772f3da22f7910b57130b152f18a4c323653a9d87feb80\",\"content\":\"from unittest.mock import MagicMock\\n\\nimport pytest\\nfrom langflow.services.database.models.deployment.model import Deployment, DeploymentRead\\n\\n\\nclass TestDeploymentValidation:";
